insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (97,'قوانين','قانون الإجراءات الضريبية قانون رقم 44 - 11 تشرين الثاني 2008','2008-11-11','https://www.ppa.gov.lb/ar/pages/details/97','{"https://admin.ppa.gov.lb/storage/listing-pages/files/8n7FhRxAZJV5kI5LoiL5gxNbUcE1nICkNOTY-1760211160.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/8n7FhRxAZJV5kI5LoiL5gxNbUcE1nICkNOTY-1760211160.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=97),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "قانون رقم 44\n صادر في 11تشرين الثاني2008\n الاجراءات الضريبية\n معدل بموجب:\n القانون رقم 54تاريخ27/12/2008\n أقر مجلس النواب،\n وينشر رئيس الجمهورية القانون التالي نصه :\n مادة وحيدة\n صدق مشروع القانون الوارد بالمرسوم رقم 17080تاريخ 29أيار 2006المتعلق بالاجراءات الضريبية آما عدلته\n اللجنة الفرعية المنبثقة عن اللجان النيابية المشترآة ومجلس النواب .\n ‐ينشر هذا القانون في الجريدة الرسمية ويعمل به اعتبارا من1/1/2009.\nبعبدا في 11تشرين الثاني 2008\nالامضاء :ميشال سليمان\n قانون الاجراءات الضريبية\n الباب الاول\n احكام عامة\n الفصل الاول\n تعريف المصطلحات\n المادة الاولى -تعريف المصطلحات\n يقصد بالعبارات التالية أينما وردت في هذا القانون ،المعاني المبينة تجاه آل منها :\n ‐1الضريبة :أي ضريبة أو رسم باستثناء الرسوم الجمرآية والعقارية ،تتولى وزارة المالية تحقيقها وتحصيلها ،ومنها :\n أ ‐ضريبة الدخل\n ب -ضريبة الأملاك المبنية\n ج -رسم الانتقال\n د -ضريبة التحسين\n هـ -الضريبة على القيمة المضافة.\n و -الضرائب غير المباشرة والرسوم المماثلة لها.\n 1\n\fز -الضرائب والرسوم التي قد تستحدث ما لم ينص هذا القانون على خلاف ذلك ،تشمل آلمة \"الضريبة\" أينما وردت في\n هذا القانون أساس الضريبة وملحقاتها ،أي الغرامات والفوائد ونفقات التحصيل الجبري المتعلقة بالضريبة.\n ‐2المكلف :آل شخص ملزم بحكم القوانين الضريبية بموجبات ضريبية ،وتسري أحكام هذا القانون المطبقة على\n المكلف ،على مقتطع الضريبة إلا في الحالات التي ينص القانون على خلاف ذلك .\n‐3الفترة الضريبية :الفترة الزمنية التي تتضمن الواقعة أو الوقائع المنشئة للضريبة ،والتي عند انتهائها يتوجب التصريح\n عن الضريبة أو تأديتها خلال مهلة محددة وفقا للنصوص القانونية لكل ضريبة ."}, {"o": 1, "l": null, "b": "‐4الإدارة الضريبية :الوحدة المختصة في وزارة المالية -مديرية المالية العامة -المناط بها أعمال إدارة وتحقق ومراقبة\n الضريبة وتحصيلها ،وذلك وفقا للصلاحيات المحددة قانونا .\n ‐5الشخص :الشخص الطبيعي والمعنوي ما لم يحدد القانون أحدهما.\n ‐6مقتطع الضريبة :الشخص الذي يتوجب عليه قانونا اقتطاع الضريبة عند المنبع من المبالغ المستحقة لشخص آخر\n )المكلف الأساسي( وتسديدها للخزينة .\n ‐7الضريبة الإضافية :الضريبة الناتجة عن تدارك آل آتمان أو نقص في الضريبة المتوجبة .\n الفصل الثاني\n نطاق القانون وتطبيقه\n موضوع قانون الاجراءات الضريبية ونطاق تطبيقه المادة ‐ 2\n يحدد هذا القانون القواعد والإجراءات المشترآة لمختلف أنواع الضرائب في الأمور التالية :\n ‐1القواعد والإجراءات المتعلقة بأسس فرض الضرائب وتحصيلها.\n ‐2حقوق وواجبات الإدارة الضريبية والمكلفين بالضريبة.\n ‐3الغرامات المتوجبة على المكلفين في حال عدم الإلتزام بالموجبات المطلوبة .\n ‐4طرق الطعن بالقرارات الصادرة عن الإدارة الضريبية وأصول الاعتراض عليها .\n قانون الاجراءات الضريبية والقوانين الاخرى المادة ‐ 3\n ‐ 1تخضع الشؤون الضريبية لأحكام هذا القانون ولأحكام التشريعات الأخرى والمعاهدات الدولية .\n ‐2عند تعارض أحكام هذا القانون وآذلك احكام القوانين الضريبية المعمول بها في لبنان مع أحكام المعاهدات الدولية،\n تطبق أحكام هذه الأخيرة.\n ‐3تخضع الشؤون الضريبية لأحكام هذا القانون عند تعارضها مع أحكام التشريعات الأخرى أآانت ذات طابع عام أو\n خاص .\n الفصل الثالث\n مبادىء عامة\n مبدأ شرعية النص المادة ‐ 4\n تحدث وتعدل وتلغى الضرائب والغرامات المتعلقة بها وتجاز الإعفاءات منها بموجب نص قانوني .\n 2\n\f نشر النصوص التطبيقية والتنظيمية المادة ‐ 5\n تنشر في الجريدة الر سمية وعلى الموقع الإلكتروني الخاص بوزارة المالية القرارات والنصوص الصادرة عن وزير"}, {"o": 2, "l": null, "b": "المالية والإدارة الضريبية والمتعلقة بالأمور الضريبية ذات الطابع العام ،وفي حالة العجلة ،للوزير تقرير النشر باللصق\n على باب الإدارة المعنية على أن يستتبع النشر مجددا في الجريدة الرسمية .\n للإدارة الضريبية نشر هذه النصوص في الوسائل الإعلامية الأخرى .\n بدء سريان مفعول القوانين الضريبية المادة ‐ 6\n ‐ 1ما لم يأت النص على خلاف ذلك ،تسري مفاعيل هذا القانون وفقا للأسس التالية :\nأ -يطبق هذا القانون على الإجراءات الضريبية ،اعتبارا من الحالات التي تكون قد وصلت إليها هذه الإجراءات في ظل\n النصوص السابقة .\n ب -يؤخد في احتساب مهل مرور الزمن المدة السابقة لتاريخ صدور هذا القانون .\n ‐2تطبق أحكام القوانين الضريبية التي تفرض غرامات و/أو فائدة جديدة أو ترفع قيمة الغرامات و/أو الفائدة على\n المخالفات المرتكبة بعد تاريخ نفاذ هذه القوانين .\nوتطبق أحكام القوانين الضريبية التي تخفض أو تعفي من قيمة الغرامات و/أو الفائدة ،على آافة المخالفات التي لا يكون\n قد جرى تسديد الغرامات المتوجبة عليها بتاريخ نفاذ تلك القوانين .\n تستفيد من التخفيض أو الإعفاء من الغرامات و/أو الفوائد وفقا لما هو مبين أعلاه ،المبالغ المقسطة وفقا لأحكام"}, {"o": 3, "l": "المادة 61", "b": "المادة\n 61من هذا القانون وغير المسددة .\n الضريبة على الايرادات والعمليات غير الشرعية المادة ‐ 7\nلا يعتد في فرض الضرائب بعدم شرعية الإيرادات أو العمليات الخاضعة للضريبة إلا إذا تمت مصادرة هذه الإيرادات\n أو الأموال المنشئة للضريبة لصالح الخزينة .\n تفسير النصوص القانونية الضريبية المادة ‐ 8\n في حال وجود نص يمكن تفسيره بأآثر من معنى ،يجب الأخذ بالمعنى الذي يجعل النص متوافقا مع هدفه ومؤمنا\n التناسق بينه وبين النصوص الأخرى .\n وفي هذه الحالة تبادر وزارة المالية إلى إصدار قرارات وتعاميم وتعليمات لتفسير هذه النصوص وطرق تطبيقها ،على\n أن تنشر في الجريدة الرسمية .\n المهل المادة ‐ 9\n ‐ 1في حال لم يحدد القانون مهلة خاصة لإجراء ما أو تنفيذ موجب معين ،تعطي الإدارة الضريبية للمكلف مهلة لهذه\n الغاية تتناسب مدتها مع طبيعة الإجراء أو تنفيذ الموجب شرط أن لا تقل هذه المهلة عن ثلاثة أيام عمل .\n ‐2في احتساب المهل ،لا يدخل ضمن المهلة يوم التبليغ أو يوم حصول الواقعة التي نشأت المهلة بسببها .\n ‐3تنقضي المهل المحددة بالأشهر أو بالسنوات في اليوم المقابل من الشهر الأخير من المهلة وفي حال عدم وجود يوم\n مقابل تنتهي المهلة في آخر يوم من هذا الشهر .\n‐4تحتسب المهل من منتصف ليل تاريخ ابتداء المهلة الى منتصف ليل اليوم المعين لانتهائها ،أو عند انقضاء آخر ساعة\n من ساعات الدوام الرسمي للعمل في حال وجود دوام رسمي للإدارة الضريبية في مراجعة المكلف لها .\n 3\n\f ‐5إذا صادف آخر يوم في المهلة يوم عطلة رسمية بما فيها يوم الاحد تمدد المهلة إلى أول يوم عمل يليه .\n ‐6ما لم ينص القانون على خلاف ذلك ،تكون المهل المعينة في هذا القانون لاستعمال حق من قبل المكلف مهل إسقاط\n يؤدي تجاوزها إلى سقوط هذا الحق .\n ‐7مع مراعاة أحكام"}, {"o": 4, "l": "المادة 39", "b": "المادة 39و"}, {"o": 5, "l": "المادة 61", "b": "المادة 61من هذا القانون ،يمكن لوزير المالية في حالات الضرورة أن يمدد المهل\n القانونية المنصوص عليها في هذا القانون والقوانين الضريبية ،وذلك بصورة عامة وشاملة لجميع المكلفين .\n ‐8يعتبر تقديم المستندات المطلوبة واقعا ضمن المهلة القانونية في حال أرسلت هذه المستندات بالبريد العادي أو\nالمضمون أو بالبريد الالكتروني وفقا لآلية توضع لهذه الغاية بقرار يصدر من وزير المالية أو في حال قدمت مباشرة إلى\n الإدارة الضريبية قبل انتهاء هذه المهلة .\n ويعتد لهذه الغاية بتاريخ الإيداع بالبريد أو تاريخ الرسالة الالكترونية المطابقة لمضمون المستند الالكتروني وفقا\n للأصول .\n شرعية استعمال الحق المادة ‐ 10\n ‐ 1لغايات تحديد الضريبة المتوجبة عن عملية ما ،يحق للإدارة الضريبية أن تعيد توصيف تلك العملية وفقا لحقيقتها\n وذلك في الحالات التالية :\n أ( في حال قام المكلف بعملية صورية من أجل التهرب من الضريبة .\n ب( في حال قام المكلف بعملية قانونية بشكلها ولكن تهدف بصورة أساسية إلى التهرب من الضريبة .\n ‐2يحق للإدارة الضريبية تعديل قيمة العمليات وشروطها التي تتم بين أشخاص مترابطين على أساس قيمة وشروط\n حصلت في عمليات مشابهة بين شخصين مستقلين وضمن شروط تنافسية آاملة .\n يعتبر أشخاص مترابطين عندما يكون لأحد الأشخاص سلطة التوجيه والإشراف على الآخر ،أي عندما يتمتع بسلطة\n إدارية على الآخر من شأنها تقرير مسار عمله في النواحي المالية والإقتصادية والتنظيمية .\n تحدد دقائق تطبيق هذه الفقرة بموجب قرار يصدر عن وزير المالية .\n ‐3تطبق الإدارة الضريبية القوانين دون إساءة أو تعسف أو تجاوز ،ودون تفريط في حقوق الخزينة .\n الباب الثاني\n الموجب الضريبي\n الفصل الاول\n احكام عامة\n الموجب الضريبي المادة ‐ 11\n ‐ 1الموجب الضريبي هو مسؤولية تأدية الضريبة المتوجبة والتي تقع على المكلف بالضريبة أو على مقتطع الضريبة"}, {"o": 6, "l": "المادة 61", "b": "أو على شخص ثالث متضامن أو مدين للمكلف أو المقتطع وفقا لاحكام القانون.\n ‐2باستثناء حالات المسؤولية التضامنية التي ينص عليها القانون ،إن مسؤولية الشخص الثالث الذي يتوجب عليه قانونا\n تسديد الضرائب المتوجبة على المكلف من أموال هذا الأخير الخاصة ،هي مسؤولية ثانوية محصورة بالمبالغ المطلوب\n منه تسديدها.\n ‐3بالإضافة الى مسؤولية المكلف أو المقتطع ،يكون الشخص الثالث مسؤولا بالتكافل والتضامن مع المكلف أو المقتطع\n عن الضريبة الناتجة عن عدم تنفيذه عمدا للموجبات الضريبية المترتبة عليهم ،أو تنفيذها عمدا بشكل مخالف لأحكام\n القانون أدى إلى تهرب من الضريبة .\n ‐4عند عدم وجود نص خاص ،وفي الحالات التي تتوفر فيها شروط مسؤولية الشخص الثالث لدى أآثر من شخص،\n يكون هؤلاء الأشخاص مسؤولين بالتكافل والتضامن فيما بينهم عن تأدية الضريبة المتوجبة .\n 4\n\f ‐5يتمتع الشخص الثالث المسؤول عن تأدية الضريبة عن المكلف أو المقتطع بجميع الحقوق المتعلقة بهذه الضريبة\n والعائدة للمكلف أو المقتطع وفقا لأحكام هذا القانون .\n نشوء وزوال الموجب الضريبي المادة ‐ 12\n ‐ 1ينشأ الموجب الضريبي ابتداء من تاريخ نشوء الواقعة التي تنتج الإيرادات الخاضعة قانونا للضريبة .\n ‐2يزول الموجب الضريبي في الحالات التالية :\n أ -تحصيل الضريبة )دفع ،مقاصة )...وفقا لأحكام هذا القانون،\n ب -مرور الزمن على تحقق أو تحصيل الضريبة،\n ج ‐إلغاء الضريبة بموجب القانون،\n د -حالات أخرى ينص عليها القانون .\n في الاهلية والتمثيل المادة ‐ 13\n‐ 1على الشخص المتمتع بالأهلية القيام بجميع الإجراءات المحددة في هذا القانون وفي القوانين الضريبية ،شخصيا أو\n بواسطة ممثل مختار .\n ‐2يتمثل المكلف غير المتمتع بالأهلية أمام الإدارة الضريبية بالأوصياء ،أو بالقيمين عليه قانونا .\n ‐3يمثل الأشخاص المعنويين أمام الإدارة الضريبية ممثلوهم القانونيون ."}, {"o": 7, "l": "المادة 61", "b": "‐4إن وجود ممثل للمكلف لدى الإدارة الضريبية ،لا يمنع المكلف من حق المشارآة الشخصية في علاقته مع هذه\n الإدارة .\n ‐5تحدد أصول التمثيل ونطاقه وفق أحكام هذا القانون والقوانين الأخرى النافذة .\n ‐6لا يحق لموظفي الإدارة الضريبية أو لأي شخص آخر محظر عليه قانونا تمثيل المكلفين أن يجري تعيينه ممثلا\n لهؤلاء المكلفين .\n الفصل الثاني\n تسديد الضريبة المتوجبة\n في حالات خاصة\n تسديد الضريبة المتوجبة من قبل مقتطع الضريبة المادة ‐ 14\n ‐ 1إن المقتطع مسؤول عن تأدية الضريبة المتوجبة على المكلف الأساسي.\n ‐2تعتبر الضريبة المقتطعة والمدفوعة من قبل المقتطع ،آأنها مدفوعة من قبل الشخص الذي اقتطعت من مستحقاته\n ولحسابه ،ويحق للمكلف الأساسي الإطلاع لدى الإدارة الضريبية على قيمة الضريبة المقتطعة والمسددة للخزينة .\n ‐3إن المقتطع الذي يمتنع عن اقتطاع الضريبة عندما يكون ذلك إلزاميا ،مسؤول شخصيا وبالتكافل والتضامن مع\n المكلف الأساسي عن المبالغ غير المقتطعة ،وذلك حتى في الحالات التي يكون فيها الامتناع عن الاقتطاع نتيجة\n معلومات غير صحيحة معطاة من قبل المكلف الأصلي الى المقتطع .\n‐4في الحالات التي لا تسدد فيها الضريبة المقتطعة للخزينة ،يكون مقتطع الضريبة مسؤولا بصورة شخصية عن المبالغ\n غير المدفوعة ،ويعفى المكلف الأساسي من مسؤولية دفعها إلا في حالة وجود تواطؤ بين الطرفين .\n 5\n\f تسديد الضريبة المتوجبة في حال التصفية او الافلاس المادة ‐ 15\n‐ 1على المصفي أو وآيل التفليسة أن يسدد الضريبة التي تتوجب على المكلف ،وذلك من إيرادات المؤسسة أو من بيع\n موجوداتها الثابتة .\n ‐2في حال تمت التصفية ذاتيا من قبل أصحاب المؤسسة ،فعليهم الاستمرار في تقديم التصاريح اللازمة للوحدة المالية\n المختصة وتسديد الضرائب والرسوم المتوجبة عليهم للخزينة خلال المهلة القانونية طيلة فترة التصفية الذاتية ."}, {"o": 8, "l": "المادة 61", "b": "‐3إذا لم يكن للشخص الطبيعي صاحب المؤسسة أو للشرآاء المتضامنين في شرآات الأشخاص قيد التصفية ما يكفي\n من أموال مادية وغير مادية عائدة للمؤسسة أو للشرآة من أجل تسديد الضريبة فعليهم أن يسددوا الضريبة من أموالهم\n الخاصة.\n ‐4إذا لم يكن للشخص المعنوي قيد التصفية ما يكفي من أموال مادية وغير مادية من اجل تسديد آامل الضريبة\n المتوجبة ،يقتضي تسديد الضريبة المتوجبة غير المسددة من قبل أشخاص آخرين في حال آانوا مسؤولين بالتضامن\n والتكافل عن تسديد ديون الشخص المعنوي ،وفقا لأحكام القانون أو النظام التأسيسي أو عقد الشراآة .\n‐5في حال إعلان إفلاس المكلف ،تزود المحكمة الناظرة بالإفلاس وزارة المالية بجميع المستندات والمعلومات المتوفرة\n لديها ،فتقوم الإدارة الضريبية المختصة بدرس أعماله وإبلاغ النتيجة إلى المحكمة وإلى الجهات المعنية .\n تسديد الضريبة المتوجبة في حال تغيير الشكل القانوني للشخص المعنوي المادة ‐ 16\n‐ 1تسدد الضريبة المتوجبة على الشخص المعنوي الذي تغير شكله القانوني من قبل الشخص المعنوي الذي حل محله .\n ‐2يعتبر الشخص المعنوي الجديد مسؤولا عن جميع المبالغ الناتجة عن عدم تسديد الضريبة المتوجبة سابقا .\n‐3تبقى دون تغيير مهل تسديد الضريبة التي آانت متوجبة أساسا على الشخص المعنوي السابق والتي انتقلت على عاتق\n الشخص المعنوي الجديد بفعل تغيير الشكل القانوني .\n ‐4يحل الشخص المعنوي الجديد محل الشخص المعنوي السابق في جميع حقوقه وواجباته تجاه الإدارة الضريبية بما\n فيها الضرائب المدفوعة التي يجيز القانون استردادها.\n ‐5في حال تعدد الأشخاص المعنويين الجدد ،يكون هؤلاء مسؤولين بالتكافل والتضامن عن تأدية الضريبة التي آانت\n متوجبة على الشخص المعنوي السابق.\n ‐6إن التغيير المحدث في تنظيم إدارة الشخص المعنوي أو في ملكيته ،لا يؤثر على موجب تسديد الضريبة المتوجبة ."}, {"o": 9, "l": "المادة 61", "b": "‐7في حال التحويل من شرآة أشخاص إلى شرآة أموال ،يبقى الشرآاء المتضامنون مسؤولين عن تسديد الضريبة\n المتوجبة عليهم وعلى الشرآة من أموالهم الخاصة .\n تسديد الضريبة المتوجبة في حال التفرغ عن المؤسسة المادة ‐ 17\nفي حال تفرغ المكلف عن مؤسسته أو عن العناصر الأساسية لها إلى الغير ،يعتبر البائع والشاري مسؤولين بالتضامن\nعن تأدية الضرائب المترتبة على المؤسسة عن أعمال السنة التي تم التفرغ خلالها وأعمال السنوات السابقة التي لم تسقط\n بمرور الزمن .\n لا يشمل التضامن التكاليف التي تفرض على المؤسسة بعد انقضاء سنة على تاريخ إبلاغ الإدارة عن عملية البيع .\n تسديد الضريبة المتوجبة في حال الوفاة والغياب وانعدام الاهلية المادة ‐ 18\n ‐ 1تسدد الضريبة المتوجبة على الشخص الطبيعي عن الفترة الضريبية الواقعة قبل تاريخ الوفاة ،من قيمة عناصر\n الترآة أو من الدخل الناتج عنها قبل توزيعها على الورثة أو الموصى لهم.\n 6\n\f ‐2ما لم ينص القانون على خلاف ذلك ،يسدد آل وريث الضريبة المتوجبة على المكلف المتوفى ،وذلك ضمن حدود\n حصته من قيمة الترآة .\n ‐3تسدد الضريبة المتوجبة على فاقد الأهلية أو على الغائب أو المفقود أو غير المعروف محل إقامته من قبل ممثله\n القانوني ،وذلك من أموال وأملاك الشخص الذي يمثله .\n ‐4إذا لم يكن للأشخاص فاقدي الأهلية أو المفقودين المذآورين في البند ) (3من هذه المادة ما يكفي من أموال منقولة أو\nغير منقولة لتسديد الضريبة المتوجبة عليهم ،تشطب الضريبة بالنسبة للجزء من الدين غير المدفوع وفقا لإجراءات تحدد\n بقرار من وزير المالية .\n ‐5يمكن الرجوع عن قرار شطب الضريبة في حال استعاد الشخص المنصوص عليه في البند ) (3من هذه المادة أهليته\nأو تم العثور عليه ،وذلك من دون سريان الفائدة والغرامة على الرصيد غير المدفوع من الفترة التي آان الشخص خلالها\n غير متمتع بالأهلية أو آان مفقودا ."}, {"o": 10, "l": "المادة 61", "b": "ويعود سريان الفائدة والغرامة من تاريخ استعادة الأهلية أو عودة المفقود .\n مسؤولية الشرآاء في شرآات الاشخاص المادة ‐ 19\n إن الشرآاء في شرآات الأشخاص المسؤولين قانونا بالتكافل والتضامن عن ديون الشرآة هم مسؤولون بصفة\n شخصية عن الضرائب المتوجبة عليهم وذلك بالتكافل والتضامن فيما بينهم ومع الشرآة .\n المسؤولية في اوضاع مشترآة لا تتمتع بالشخصية المعنوية المادة ‐ 20\n ‐ 1في حال اشتراك عدة أشخاص في ملكية عقار أو عند وجود أي شراآة في نشاطات لا تتمتع بالشخصية المعنوية،\n يكون آل شخص مسؤولا عن حصته .وفي حال أخذت هذه الملكية المشترآة صفة آيان مستقل من الناحية الضريبية\n)شرآة محاصة ،شرآة فعلية (...يكون هؤلاء الأشخاص مسؤولين بالتكافل والتضامن فيما بينهم عن الموجبات الضريبية\n الناتجة عن الملكية المشترآة .\n ‐2تعتبر حصص الشراآة المشار اليها في الفقرة الاولى من هذه المادة ،متساوية في حال عدم إمكانية إثبات قيمة آل\n منها .\n مسؤولية الاشخاص المعنويين المادة ‐ 21\n بالإضافة الى المسؤولية الأساسية للأشخاص المعنويين ،يكون المدير العام في الشرآات المحدودة المسؤولية ،ورئيس\n مجلس الإدارة و/أو المدير العام في الشرآات المغفلة ،مسؤولين بالتكافل والتضامن مع الشخص المعنوي وفيما بينهم،\n عن الضريبة الناتجة عن عدم الالتزام عمدا بالموجبات الضريبية بما فيها قيامهم أو موافقتهم على القيام بأعمال أدت إلى\n التهرب من الضريبة إذا ثبت ذلك بموجب حكم قضائي .\n الباب الثالث\n الاجراءات الضريبية\n الفصل الاول\n احكام عامة\n تضارب المصالح المادة ‐ 22\n‐ 1يحظر على موظف الإدارة الضريبية القيام أو المشارآة بأية اجراءات ضريبية تؤثر على مطرح الضريبة وتخص\n 7\n\f مكلفا معينا ،في الحالات التالية :\n أ -في حال وجود صلة قرابة حتى الدرجة الخامسة بين المكلف والموظف."}, {"o": 11, "l": "المادة 61", "b": "ب -في حال وجود مصلحة مادية بين الموظف والمكلف أو بين أحد أقربائهما حتى الدرجة الثالثة .\n ج -في حال وجود نزاع قائم أو شكوى رسمية بين الموظف والمكلف .\n‐2في حال تضارب المصالح بين موظف الإدارة الضريبية والمكلف وفقا للحالات المشار اليها في البند الأول من هذه\nالمادة ،يحظر على الموظف والإدارة الضريبية متابعة الإجراء الضريبي من قبل هذا الموظف ويتم تكليف موظف آخر\n بهذه المهمة .\n التعاون بين مختلف الادارات العامة والخاصة والجهات المعنية المادة ‐ 23\n ‐ 1مع مراعاة أحكام القانون رقم 3تاريخ 3/9/1956المتعلق بالسرية المصرفية ،على آل شخص بما فيه إدارات\n الدولة والمؤسسات العامة والبلديات واتحاد البلديات آافة وآذلك الهيئات المختلفة في القطاع الخاص والنقابات ،التعاون\n مع السلطات الضريبية وإعطائها المعلومات التي تطلبها للقيام بمهامها ،ولا يجوز لأي آان التذرع بسر المهنة للحؤول\nدون تمكين موظفي الإدارة الضريبية من مراجعة السجلات والمستندات المحاسبية التي تسمح بالتحقق من صحة استيفاء\n الضريبة المتوجبة .\n ‐2يجوز للدوائر المالية أن تطلب إلى النيابة العامة الاطلاع على ملف أية دعوى مقامة لدى المحاآم ،وعلى السلطة\n القضائية أن تطلع الدوائر المذآورة بواسطة النيابة العامة على ما لديها من معلومات تحمل على الظن بأن أحد المكلفين\n غش الدوائر المالية أو حاول غشها في ما له علاقة بالضرائب والرسوم آافة ،سواء آانت الدعوى مدنية أو تجارية أو\n جزائية ،حتى وان انتهت بقرار منع محاآمة .\n ابلاغ الادارة الضريبية عن تأسيس المؤسسات وتعديلاتها والانتساب الى النقابات المادة ‐ 24\n‐ 1على رؤساء الأقلام في المحاآم التجارية المختصة إبلاغ الإدارة الضريبية عن التسجيلات التي حصلت في السجل\n التجاري وبصورة خاصة عن معلومات حول التأسيس ،الاسم ،الشكل القانوني ،مرآز ونوع العمل ،رأس المال ،توزيع"}, {"o": 12, "l": "المادة 61", "b": "الحصص والأسهم وانتقالها بالإرث أو بالتنازل ،الدمج ،إعادة التنظيم ،التصفية ،الإفلاس ،الشطب وآذلك أية معلومة\n أخرى تفيد الإدارة الضريبية ،وذلك آل شهر في موعد لا يتعدى العاشر من الشهر الذي يليه .\n ‐2يتوجب على رؤساء الأقلام في المحاآم المدنية المسؤولة عن تسجيل الشرآات المدنية وآذلك النقابات والهيئات\n الخاصة المسؤولة عن تسجيل الأشخاص الذين يقومون بمهن غير تجارية ،إعلام الإدارة الضريبية عن آل تسجيل\n وإلغاء تسجيل أو نقل تسجيل ،وذلك آل شهر من موعد لا يتعدى العاشر من الشهر الذي يليه .\n ‐3على دوائر الأحوال الشخصية إبلاغ الإدارة الضريبية عن الوفيات الحاصلة وعن آل حالة إعلان وفاة شخص آان\n بحكم المفقود ،وذلك آل ثلاثة أشهر في موعد لا يتعدى الخامس عشر من الشهر الذي يلي فترة الأشهر الثلاثة المعنية .\n ‐4تحدد أصول إبلاغ المعلومات المنوه عنها في بنود هذه المادة بموجب قرارات تصدر عن وزير المالية .\n السرية المهنية المادة ‐ 25\n ‐ 1يلتزم العاملون لدى الإدارة الضريبية الحاليون أو السابقون بالسرية المهنية ،فيما يتعلق بالمعلومات التي حصلوا\n عليها بصفتهم موظفين ،ولا يمكن البوح بهذه المعلومات إلا للجهات التالية :\n أ ‐لموظفي الإدارة الضريبية ومدير المالية العام ووزير المالية في سياق قيامهم بمهامهم الرسمية .\n ب -للنيابة العامة وديوان المحاسبة أو المحاآم في حال ملاحقة شخص ارتكب مخالفات مالية بناء على قرارات صادرة\n عنها .\n ج -للإدارات الضريبية التابعة لدول أجنبية تنفيذا لمعاهدات دولية .\n 8\n\f د -لدوائر مراقبة التحقق أو التحصيل في وزارة المالية أو التفتيش المالي في سياق قيام هذه الدوائر بمهامها الرسمية .\n هـ -للمكلفين بناء لطلبهم فيما يتعلق بملفاتهم وبالضرائب والرسوم المتوجبة عليهم .\n و -لأية جهة شرط وجود موافقة مسبقة خطية من المكلف ."}, {"o": 13, "l": "المادة 61", "b": "‐2يلزم الموظفون التابعون للأشخاص المذآورين في الفقرات المبينة في البند الأول من هذه المادة ،بعدم إفشاء أو\n استعمال المعلومات إلا للغاية التي من أجلها حصلوا عليها.\n ‐3يترتب على مخالفة السرية المهنية المنصوص عليها في هذه المادة مسؤولية إدارية ومدنية وجزائية وفقا للقوانين\n المرعية الاجراء .\n الاستفسارات الضريبية المادة ‐ 26\n ‐ 1يحق لأي شخص يرغب المباشرة بعمل أو عملية ما ،الاستفسار من الإدارة الضريبية المختصة عن آيفية تطبيق\n القانون الضريبي على هذا العمل الذي ينوي القيام به ،شرط أن لا يكون قد اآتمل بتاريخ تقديم طلب الاستيضاح .\n ‐2يجب أن يكون طلب الاستفسار مرتكزا على عملية واقعية وليس افتراضية ويذآر فيه آافة تفاصيل الموضوع\n والعملية المراد الاستفسار عنها والنقاط التي يطلب المكلف إيضاحات عنها ،ولا سيما الوقائع والأدلة والمستندات وآل\n المعلومات الخاصة بهذا العمل ،ويمكن للإدارة الضريبية أن تطلب أية معلومات إضافية تراها مناسبة .\nعلى الإدارة الضريبية أن تجيب المكلف خطيا على طلبه في مهلة تحددها على أن لا تزيد عن شهرين من تاريخ اآتمال\n المعلومات.\n ‐3في حال نفذ المكلف العمل بحسب الأسس المبينة في جواب الإدارة الضريبية على الطلب ،يصبح هذا التنفيذ ملزما\n للإدارة الضريبية وللمكلف معا في إطار العمل المنفذ حصرا ،دون أن يمنع ذلك المكلف من حق الطعن بالتكاليف\n الضريبية الناتجة عن هذا العمل وفقا لأحكام الفصل 12من هذا القانون .\n ‐4يفرض على آل طلب استفسار المنصوص عليه في هذه المادة رسم تحدد شروطه ومقداره بمرسوم يتخذ بناء على\n اقتراح وزير المالية .\n ‐5تحدد إجراءات تطبيق هذه المادة بقرار يصدر عن وزير المالية .\n الفصل الثاني\n التبليغ\n التبليغ المادة ‐ 27\n ‐ 1يتم تبليغ الشخص الطبيعي أو المعنوي في محل الإقامة المختار الذي يصرح عنه للإدارة الضريبية ."}, {"o": 14, "l": "المادة 61", "b": "في حال غير المكلف محل الإقامة المختار ترسل أوراق التبليغ إلى عنوانه الجديد في حال إعلام الإدارة الضريبية بهذا\nالعنوان وفقا لأحكام البند ) (2من"}, {"o": 15, "l": "المادة 32", "b": "المادة 32من هذا القانون وإلا يكون التبليغ قانونيا عند إرساله إلى آخر عنوان مصرح\n عنه .\n ‐2في الحالات التي لم يعلم الشخص محل الإقامة المختار للإدارة الضريبية ،يتم تبليغه وفقا للآتي :\n أ -بالنسبة الى الشخص الطبيعي :في مرآز عمله الرئيسي وفي حال عدم وجود مرآز عمل يتم تبليغه في مسكنه\n الرئيسي .\n ب -بالنسبة الى الشخص المعنوي :في مرآزه الرئيسي وإذا آان المكلف فرعا لشرآة أجنبية ،يتم تبليغه في الفرع\n الرئيسي الموجود على الأراضي اللبنانية .\n ‐3في الحالات التي تكون فيها الإدارة الضريبية ملزمة بتبليغ المكلف ،يتم التبليغ إما بتسليم أوراق التبليغ شخصيا إلى\n المكلف أو من ينوب عنه قانونا أو بواسطة البريد المضمون مع إشعار بالإستلام وفقا للأصول ويعتد لهذه الغاية بتاريخ\n الإستلام ،أو بأية وسيلة قانونية أخرى .\n ‐4تبلغ شرآة المحاصة بواسطة الشريك الذي آلفته الشرآة القيام بالموجبات الضريبية عنها ،وذلك وفقا للقواعد\n 9\n\f المنصوص عليها في هذا الفصل .\n ‐5في ما يتعلق بالأشخاص الذين يشترآون في ملكية عقار أو عند وجود أي شراآة في نشاطات لا تتمتع بالشخصية\n المعنوية ،يتم تبليغ آل شخص في الشراآة وفقا للقواعد المنصوص عليها في هذا الفصل .\n عمليات التبليغ المادة ‐ 28\n ‐ 1في حال تبليغ الشخص الطبيعي في محل الاقامة المختار أو في مرآز عمله أو في مسكنه ،يجب أن يبلغ صاحب\n العلاقة شخصيا بعد التثبت من هويته .\n ولا يبلغ المكلف خارج مرآز عمله أو مسكنه أو في محل الاقامة المختار الذي اختاره إلا بعد الإطلاع على مستند\n رسمي يثبت هويته .\n ‐2إذا لم يكن الشخص المطلوب تبليغه موجودا في مرآز عمله أو في مسكنه أو في محل الاقامة الذي اختاره ،جاز\n التبليغ إلى من يصرح بأنه من الساآنين معه من الأزواج والأقارب أو من العاملين معه أو في خدمته.\n ‐3يتبلغ عن الأشخاص المعنويين على مختلف أنواعهم الشخص المكلف منهم بتبلغ البريد ."}, {"o": 16, "l": "المادة 32", "b": "‐4عند عدم وجود أي من الأشخاص الذين يمكن تبليغهم وتعذر تبليغهم مرتين متتاليتين ،يقوم الموظف المكلف بالتبليغ\n أو موظف البريد ،وبعد موافقة الإدارة الضريبية ،بلصق إعلام على باب مكان تبليغ المكلف المعني وينشر هذا الإعلام\n في جريدتين محليتين وعلى الموقع الالكتروني الخاص بوزارة المالية .\nيجب أن يتضمن الإعلام تاريخ اللصق والطلب الى المكلف المعني مراجعة الإدارة الضريبية خلال مهلة ثلاثين يوما من\n تاريخ النشر.\n عند عدم معرفة مرآز عمل أو محل إقامة الشخص المراد تبليغه ،يكتفى بالنشر في جريديتين محليتين وعلى الموقع\n الإلكتروني الخاص بوزارة المالية .\n يعتبر التبليغ حاصلا بصورة صحيحة بعد انتهاء مهلة المراجعة المشار اليها أعلاه .\n ‐5في حال رفض التبلغ ،على الموظف المولج بالتبليغ أو موزع البريد أن يدون واقعة الرفض وتاريخها على الغلاف\n مع توقيعه ،وان يعيد المستند المطلوب إبلاغه إلى مصدره ،وأن يعلم المكلف بعنوان هذا المصدر ويعتبر عندها التبليغ\n حاصلا بصورة صحيحة اعتبارا من تاريخ الرفض .\n ‐6مع مراعاة ما تنص عليه القوانين الخاصة ،يتم التبليغ في بعض الحالات على الوجه التالي :\n أ -فيما يتعلق بأفراد الجيش والأجهزة الأمنية :بواسطة قيادة الوحدة .\n ب -فيما يتعلق بالمساجين :بواسطة مدير السجن .\n الفصل الثالث\n السجلات والمستندات المحاسبية\n مسك السجلات والمستندات المحاسبية المادة ‐ 29\n ‐ 1يتوجب على الأشخاص المكلفين بضريبة الدخل على أساس الربح الحقيقي مسك سجلات اليومية والجردة والأستاذ\nوسجل الرواتب والأجور .آما ويتوجب أيضا مسك هذه السجلات بالنسبة الى الضريبة على القيمة المضافة في حال آان\n هؤلاء المكلفون خاضعين لها أو في حال آانوا يستفيدون من أحكام"}, {"o": 17, "l": "المادة 59", "b": "المادة 59من القانون ) 2001/379الضريبة على\n القيمة المضافة ).\n آما يتوجب على الشرآات المساهمة وشرآات التوصية بالأسهم مسك سجل الأسهم الإسمية أيضا .\n‐2بالنسبة إلى الأشخاص المكلفين بضريبة الدخل على غير أساس الربح الحقيقي فعليهم مسك سجلات اليومية والأصول\n الثابتة والرواتب والأجور .آما ويتوجب أيضا مسك هذه السجلات بالنسبة للضريبة على القيمة المضافة في حال آان\n هؤلاء المكلفون خاضعين لها او آانوا يستفيدون من أحكام"}, {"o": 18, "l": "المادة 59", "b": "المادة 59من القانون (2001/379الضريبة على القيمة\n المضافة ).\n 10\n\f ‐3بالنسبة إلى الاشخاص المستفيدين من إعفاءات من ضريبة الدخل الخاضعين للضريبة على القيمة المضافة أو\n المستفيدين من أحكام"}, {"o": 19, "l": "المادة 59", "b": "المادة 59من القانون ) 2001/379الضريبة على القيمة المضافة( ،فعليهم مسك سجلات اليومية\n والأصول الثابتة لاعتمادها للضريبة على القيمة المضافة .\n ‐4تمسك السجلات المنصوص عليها في البند الأول من هذه المادة وفقا للقوانين المرعية الإجراء ،يدويا أو بواسطة\n الحاسوب الآلي .\n ‐5تحدد محتويات وآيفية مسك هذه السجلات وتنظيم المستندات المحاسبية بقرار يصدر عن وزير المالية.\n ‐6لغايات فرض الضرائب والرسوم ،يمكن مسك هذه السجلات بدون تختيمها أو التأشير عليها .\n حفظ السجلات والمستندات المحاسبية المادة ‐ 30\n تحفظ السجلات والمستندات المحسابية لمدة عشر سنوات من انتهاء السنة التي تعود لها هذه السجلات والمستندات،\n وذلك في مرآز عمل أو في محل إقامة المكلف ،على أن يكون حفظها بطريقة سليمة تجنبها التلف ،وأن تبقى طيلة هذه\n المدة قابلة للقراءة والمراجعة.\n آما يمكن حفظ تلك السجلات والمستندات بواسطة الحاسوب الآلي أو أي من التقنيات الحديثة الأخرى وذلك وفقا لقرار\n يصدر عن وزير المالية .\n السجلات والمستندات المحاسبية المنظمة بلغة اجنبية المادة ‐ 31\n تمسك السجلات والمستندات المحاسبية المنصوص عليها قانونا باللغة العربية ،آما يمكن مسكها باللغة الفرنسية أو\n الإنكليزية .\n يحق للإدارة الضريبية أن تطلب من المكلف ترجمة نظامية لما تحتاج إليه من عقود ومراسلات إلى اللغة العربية على\n نفقته ومسؤوليته .\n الفصل الرابع\n تعريف وتسجيل المكلفين\n التسجيل لدى الادارة الضريبية المادة ‐ 32\n‐ 1مع مراعاة أحكام القوانين الخاصة ،على آل شخص يباشر عملا خاضعا للضريبة أن يحيط الإدارة الضريبية علما\n بذلك بموجب طلب تسجيل يقدمه إليها خلال شهرين من تاريخ مباشرة العمل وذلك وفقا لمعايير وإجراءات تحدد بقرار\n يصدر عن وزير المالية .\n ‐2على آل شخص مسجل لدى الإدارة الضريبية ،أن يعلم هذه الإدارة خلال مهلة شهرين عن آل تغيير يتناول :"}, {"o": 20, "l": "المادة 59", "b": "أ -اسمه ،عنوانه ،مرآز عمله ،أو نوع نشاطه الرئيسي .\n ب -تعديل العنوان أو الاسم التجاري .\n ج -الشكل القانوني الذي يمارس النشاط من خلاله .\n التوقف عن العمل المادة ‐ 33\n‐ 1على المكلف الذي يتوقف نهائيا عن العمل أن يبلغ الإدارة الضريبية المختصة بذلك ضمن مهلة شهرين من تاريخ\n هذا التوقف ،على أن تحدد الأصول والإجراءات ومهل إصدار التكاليف بقرار يصدر عن وزير المالية.\n تحدد أسس تدقيق ملفات المكلفين المتوقفين عن العمل وفقا لمعايير إنتقاء توضع لهذه الغاية من قبل الإدارة المذآورة .\n 11\n\f ‐2مع مراعاة الأحكام القانونية التي تنص على المسؤولية التضامنية ،إن التصريح عن التوقف النهائي عن العمل لا\n يلغي مسؤولية المكلف عن تأدية الضرائب المتوجبة عليه عن فترة عمله حتى ولو تحققت هذه الضرائب أو أصبحت\n برسم التحصيل بعد هذا التوقف .\n ‐3على الإدارة الضريبية أن تنجز التدقيق بملف المكلف المتوقف نهائيا عن العمل خلال فترة أربعة أشهر من تاريخ\n التبليغ .\n الرقم الضريبي المادة ‐ 34\n ‐ 1تعطي الإدارة الضريبية المكلف عند تسجيله رقما ضريبيا واحدا لجميع أنواع الضرائب بما فيها الرسوم الجمرآية\n والعقارية ،وذلك وفقا لإجراءات تحدد بقرار يصدر عن وزير المالية .\n ‐2على جميع المؤسسات العامة والخاصة والبلديات واتحاد البلديات والهيئات والجمعيات وسائر الأشخاص المعنويين\n والطبيعيين أن تعتمد رقم تسجيلها لدى وزارة المالية على آافة المستندات الصادرة عنها وأن تلتزم استعمال أرقام\n التسجيل المعطاة من وزارة المالية لمستخدميها والمتعاملين معها في مستنداتها آافة .\n حساب المكلف المادة ‐ 35\n‐ 1يخصص لكل مكلف مسجل لدى الإدارة الضريبية حساب ضريبي واحد مبوب حسب آل نوع من أنواع الضرائب .\n ‐2يجب أن يظهر حساب المكلف حرآة العمليات العائدة لمختلف أنواع الضرائب ."}, {"o": 21, "l": "المادة 59", "b": "‐3مع مراعاة آل نص خاص ،تحفظ المستندات المتعلقة بحساب المكلفين لدى الادارة الضريبية لمدة عشر سنوات.\n ‐4يحق للمكلف أو لمن يمثله أو من يفوضه الطلب خطيا من الإدارة الضريبية تزويده بالمعلومات المتعلقة بحسابه،\nوعلى الإدارة الضريبية أن تعطيه إفادة بهذه المعلومات وذلك ضمن مهلة لا تزيد عن ثلاثة أيام من تاريخ تقديم الطلب .\n الفصل الخامس\n حقوق وموجبات المكلف\n حقوق المكلف المادة ‐ 36\n مع مراعاة أحكام القوانين الضريبية ،يحق للمكلف :\n أ -الاستفادة من التنزيلات الضريبية المنصوص عليها قانونا ومن حق حسم الضريبة ومن تخفيض الغرامات عند توافر\n الشروط القانونية .\n ب -حضور عمليات التدقيق الميداني وتبلغ نتائج التدقيق مع بيان الأسباب والمواد القانونية الموجبة لفرض ضرائب\n إضافية.\n ج -الطلب من الإدارة الضريبية أن تطلعه على مضمون المعلومات والمستندات التي بنت الإدارة على أساسها التكليف\n بالضريبة .\n د -التوضيح للإدارة الضريبية عن احتساب الضريبة ودفعها .\n هـ -الطعن في قرارات الإدارة الضريبية وفقا للقانون .\n و -الحصول مجانا على نماذج التصاريح والمطبوعات الضريبية .\n ز ‐تعديل التصاريح التي تقدم بها ضمن الشروط القانونية التي تجيز هذا التعديل .\n ح ‐أن تتعامل معه الإدارة الضريبية باحترام وموضوعية.\n ط -أن تحافظ الإدارة الضريبية على سرية المعلومات التي يدلي بها .\n 12\n\f ي -أن يطلب الى الموظفين المختصين إبراز بطاقة التعريف بأنفسهم وأمر المهمة قبل الشروع بأي آشف أو تدقيق .\nك -الاطلاع على نتائج التدقيق وطلب إفادات أو خلاصات تتعلق فقط بالتصاريح والمستندات التي سبق للمكلف تقديمها .\n موجبات المكلف المادة ‐ 37\n مع مراعاة أحكام القوانين الضريبية ،يتوجب على المكلف بصورة خاصة :\n أ -مسك السجلات والمستندات المحاسبية .\n ب ‐تأدية الضرائب والرسوم وتقديم التصاريح ضمن المهل المحددة لها ."}, {"o": 22, "l": "المادة 59", "b": "ج -تنفيذ طلبات الإدارة الضريبية في إطار قيامها بمهامها ،وخاصة بإيداعها معلومات عن نشاطه أو عن الأشخاص\n الذين يتعامل معهم وذلك مع مراعاة أحكام قانون السرية المصرفية والسرية المهنية.\n د -تسهيل مهمة موظفي الإدارة الضريبية المولجين بالتدقيق .\n الفصل السادس\n التصريح الضريبي\n موجب تقديم التصريح الضريبي المادة ‐ 38\n‐ 1على الأشخاص الملزمين وفقا للقوانين الضريبية الخاصة بتقديم التصاريح أو البيانات التي تفيد المطرح الضريبي،\nأن يقدموها إلى الإدارة الضريبية ضمن المهل القانونية وفقا للأصول المحددة لها ،ويدخل ضمن هذا الموجب أيضا تقديم\n التصاريح العائدة للضريبة المقتطعة عند المنبع.\n ‐2يمكن للمكلفين الخاضعين لنظام التكليف الذاتي إرسال التصاريح والبيانات الضريبية إلى الإدارة الضريبية بواسطة\n البريد الإلكتروني ،وذلك وفقا للأصول والاجراءات التي يحددها وزير المالية بقرار يصدر عنه .\n ‐3يجب أن يوقع التصريح من قبل المكلف أو من ممثليه القانونيين.\n ‐4على المكلف تسجيل اسم أي شخص ساهم في تحضير التصريح المقدم منه وأن يدون الرقم الضريبي لهذا الشخص\n وعنوانه .\n ويبقى المكلف وخبير المحاسبة وآل شخص ساهم في تحضير التصريح خاضعا لأحكام المرسوم الاشتراعي رقم 156\n تاريخ 16/9/1983المعدل بموجب القانون رقم 276تاريخ4/11/1993.\n ‐5مع مراعاة الاصول المحددة للتصريح بواسطة البريد الإلكتروني ،لا يمكن للإدارة الضريبية رفض استلام أي\n تصريح إلا إذا آان غير مقترن بتواقيع الأشخاص المذآورين في هذه المادة بصورة صحيحة .إن عدم تسديد قيمة\n الضريبة المتوجبة لا يؤثر على موجب الإدارة الضريبية استلام التصريح .\n تمديد مهل تقديم التصاريح المادة ‐ 39\n ‐ 1مع مراعاة أحكام القوانين الضريبية ،يحق للإدارة الضريبية أن تمدد مهل تقديم التصاريح شهرا واحدا آحد أقصى\n بناء على طلب خطي يقدم من المكلف إذا وجدت أسباب جوهرية تستوجب التمديد ."}, {"o": 23, "l": "المادة 59", "b": "‐2يقدم طلب تمديد التصريح قبل انتهاء المهلة الأساسية لتقديم التصاريح بعشرة أيام آحد أقصى ،وعلى الإدارة\n الضريبية البت بالطلب قبل انتهاء المهلة الأساسية لتقديم التصاريح بخمسة أيام آحد أقصى.\n يتوجب على صاحب العلاقة مراجعة الإدارة الضريبية لمعرفة قرارها بشأن طلبه وذلك ابتداء من اليوم الذي يلي تاريخ\n إنتهاء المهلة المخصصة لدرس الطلب .\n يعتبر عدم البت بالطلب من قبل الإدارة الضريبية بمثابة رفض ضمني ،وفي جميع الأحوال لا يقبل قرار الإدارة\n الضريبية بهذا المعنى أي مراجعة .\n 13\n\f ‐3في حال التأخر في تقديم التصاريح بعد انتهاء المهلة القانونية لتقديمها أو مهلة قبول تمديدها ،تسري غرامة التأخير\n عن هذه التصاريح اعتبارا من تاريخ انتهاء هذه المهل .\n ‐4باستثناء الحالات التي ينص عليها القانون ،لا يلغي تمديد مهل التصريح مهل الدفع ولا يوقف هذا التمديد سريان\n الغرامة المتوجبة عن المبالغ غير المدفوعة .\n تعديل التصاريح من قبل المكلف المادة ‐ 40\n ‐ 1إذا اآتشف المكلف أن التصريح الذي تقدم به للإدارة الضريبية يتضمن خطأ أو إغفالا ينتج عنه ضريبة إضافية،\n يحق له أن يتقدم بتصريح معدل يبين فيه الخطأ أو الإغفال الحاصل ،وان يسدد الضريبة الناقصة وملحقاتها في حال\n توجبها ،على أن يتم التعديل بتاريخ سابق لتاريخ صدور أمر مهمة التدقيق عن الفترة الضريبية موضوع التصريح .\n ‐2إذا قام المكلف بتقديم تعديل التصريح ضمن مهلة التصريح الأساسي ،يعتبر التصريح المعدل بمثابة ملحق للتصريح\n الأساسي ،فلا يتوجب عن الضريبة الإضافية ،في حال توجبها ،أي غرامة تحقق .\n ‐3إذا قام المكلف بتقديم تعديل التصريح ضمن مهلة ثلاثة أشهر من تاريخ انتهاء مهلة التصريح السنوي و 30يوما من\n تاريخ انتهاء مهلة التصريح الأساسي بالنسبة لباقي التصاريح ،فلا تتوجب أي غرامة تحقق شرط ألا ينتج عن هذا"}, {"o": 24, "l": "المادة 59", "b": "التعديل ضريبة إضافية تتجاوز نسبتها عشرة بالمئة ) (%10من قيمة الضريبة المتوجبة ،وفي هذه الحالة تفرض الغرامة\n المنصوص عليها في"}, {"o": 25, "l": "المادة 110", "b": "المادة 110من هذا القانون .\n ‐4في حال حصول خطأ في التصريح أدى إلى زيادة في الضريبة المدفوعة عن الضريبة المتوجبة بعد التعديل ،يحق\n للمكلف أن يقدم تعديلا لتصريحه ضمن مهلة مرور الزمن وأن يطلب استرداد هذه الزيادة ،في حال سبق أن سددها،\n وذلك وفقا لأحكام"}, {"o": 26, "l": "المادة 54", "b": "المادة 54من هذا القانون .\n بيانات المعلومات المادة ‐ 41\n يمكن للإدارة الضريبية ،أن تطلب من أي شخص يحصل على أموال أو خدمات من المكلف ،أو يقدم إلى المكلف\n أموالا أو خدمات ،أن يقدم معلومات عن المبالغ التي سددها لهذا المكلف أو حصل عليها لقاء تلك الأموال والخدمات .\n الفصل السابع\n التكليف الضريبي\n مفهوم التكليف الضريبي المادة‐ 42\n ‐ 1يقصد بالتكليف الضريبي وفقا لأحكام هذا القانون تحديد وتدوين قيمة الضريبة المتوجبة في حساب المكلف لدى\n الإدارة الضريبية عن فترة ضريبية معينة وعن ضريبة أو نوع ضريبة معين .\n‐2يقصد بالتكليف الذاتي بالضريبة قيام المكلف أو الشخص المسؤول عن اقتطاع الضريبة عند المنبع باحتساب الضريبة\n المتوجبة وفقا للقواعد القانونية والتصريح عنها وتأديتها للخزينة ضمن المهل القانونية .\n ‐3في الحالات التي تلزم فيها القوانين الضريبية التكليف الذاتي بالضريبة ،وآما بالنسبة لضريبة الدخل والضريبة على\nالقيمة المضافة ،يكون المكلف أو مقتطع الضريبة مسؤولا عن التصريح عن الضريبة المتوجبة وتأديتها دون الحاجة إلى\n إصدار إعلام ضريبي أو جدول تكليف من قبل الإدارة الضريبية .\n أما في الحالات التي لم تلزم فيها القوانين الضريبية التكليف الذاتي بالضريبة ،فتقوم الإدارة الضريبية بفرض الضريبة\n المتوجبة وفقا لآلية تحدد بموجب قرار يصدر عن وزير المالية .\n ‐4يحق للإدارة الضريبية أن تقوم بمراجعة وتدقيق تصاريح المكلفين وفقا للأصول المحددة في هذا القانون ،وفي حال\n تبين لها ما يوجب تعديل التصريح أو فرض ضريبة إضافية تصدر التكاليف اللازمة وتبلغها للمكلف بموجب إعلامات\n 14\n\f ضريبية فردية .\n إذا تبين للإدارة الضريبية عدم وجود أسباب للتعديل ،تبلغ المكلف بهذا الأمر .\n ‐5يتم التكليف بالضريبة من قبل الإدارة الضريبية استنادا الى مصادر المعلومات التالية :\n أ -المعلومات المستخرجة من تصاريح وسجلات المكلف ."}, {"o": 27, "l": "المادة 54", "b": "ب -المعلومات المتوفرة وفقا لأحكام"}, {"o": 28, "l": "المادة 41", "b": "المادة 41من هذا القانون .\n ج -المعلومات الناتجة عن التدقيق والكشف الميداني .\n د -أية معلومة تحصل عليها الإدارة الضريبية .\n ‐6إذا لم يقدم المكلف التصاريح أو لم يمسك السجلات والمستندات المحاسبية القانونية أو لم يعط الإدارة الضريبية\n المعلومات التي تفيد احتساب مطرح الضريبة ،تعلمه الإدارة الضريبية بأنها ستعمد خلال شهر من تاريخ تبلغه الإعلام\n إلى تحديد المطرح الضريبي وفقا لأحكام البند ) (5من هذه المادة وما يكون قد قدمه المكلف من تصاريح وأبرز من\n مستندات خلال الشهر .\n لا تدخل مهلة الشهر هذه في احتساب مهلة مرور الزمن .\n مرور الزمن على تدارك حقوق الخزينة المادة ‐ 43\n ‐ 1مع مراعاة أحكام المرسوم الإشتراعي رقم 146تاريخ 12/6/1959وتعديلاته المتعلقة برسم الانتقال ،يحق\nللإدارة الضريبية تدارك حقوق الخزينة بالضريبة ضمن مهلة أربع سنوات بعد انتهاء السنة التي تلي سنة الأعمال ،وست\n سنوات بالنسبة للمكلفين المكتومين أي غير المسجلين لدى الإدارة الضريبية متى آان ذلك إلزاميا ،على أن يصدر\n التكليف وأن يتم إيداعه بالبريد المضمون لإبلاغ المكلف بمدة أقصاها /12/31من سنة التكليف .\n ‐2يحق للمكلف أن يطالب باسترداد الضريبة الذي يجيزه القانون ضمن مهلة أربع سنوات تلي انتهاء السنة التي تنشأ\n خلالها حق الاسترداد.\n ‐3يمكن بعد انتهاء المهلة المنصوص عليها في البند الأول من هذه المادة تدارك التكاليف وتصحيحها وفرض الضريبة\nعلى آل ربح أو إيراد ثبت بموجب حكم قضائي أو قرار تحكيمي أو تحرير ترآة ،وذلك لغاية نهاية السنة الميلادية التي\n تلي السنة التي تم خلالها إبلاغ الإدارة الضريبية الحكم أو القرار أو التحرير .\n الفصل الثامن\n المراقبة الضريبية\n التدقيق المكتبي والميداني المادة ‐ 44\n‐ 1من أجل التثبت من صحة تحقق واستيفاء الضريبة ،يحق للإدارة الضريبية القيام بمراجعة وتدقيق تصاريح المكلف"}, {"o": 29, "l": "المادة 41", "b": "وأعماله على أساس عينات من الملفات يجري اختيارها وفقا لمعايير إختيار توضع لهذه الغاية من قبل الإدارة المذآورة\n وذلك نتيجة لعملية تحليل المخاطر .\n ‐2يحق لموظفي الإدارة الضريبية المختصة في إطار عملية التدقيق الكشف على مجمل عناصر المطرح الضريبي،\n والاطلاع على السجلات والمستندات المحاسبية العائدة للمكلف ،أو لأي شخص آخر له علاقة به .\n آما يحق لموظفي الإدارة الضريبية المختصة الدخول إلى مرآز عمل المكلف أو محل حفظ السجلات والمستندات\n المحاسبية على أن يتم ذلك بالتنسيق مع المكلف .\n إذا رفض المكلف طلبات الإدارة الضريبية أعلاه ،تطبق بحقه أحكام الفقرة ) (6من"}, {"o": 30, "l": "المادة 42", "b": "المادة 42من هذا القانون .\n 15\n\f امر مهمة بالتدقيق الضريبي المادة ‐ 45\n يقوم الموظف المختص بالتدقيق الضريبي لدى المكلف بناء على أمر مهمة يصدر عن رئيس الوحدة الضريبية\n المختصة .\n يجب أن يتضمن أمر المهمة المعلومات التالية :\n أ -رقم أمر المهمة وتاريخ تسجيله.\n ب -اسم المراقب المولج بالتدقيق .\n ج -اسم المكلف وعنوانه ورقمه الضريبي .\n د -الفترات الضريبية وأنواع الضرائب موضوع التدقيق .\n هـ -اسم رئيس الوحدة وتوقيعه .\n ابلاغ المكلف امر مهمة التدقيق الضريبي المادة ‐ 46\n‐ 1على الإدارة الضريبية إبلاغ المكلف أمر المهمة ،وفقا لأحكام"}, {"o": 31, "l": "المادة 27", "b": "المادة 27من هذا القانون ،وتاريخ بدء عملية التدقيق\nضمن مهلة لا تقل عن خمسة عشر يوما من تاريخ الإبلاغ ،ويشمل التبليغ تحديد السجلات والمستندات المحاسبية العائدة\n للفترة الضريبية موضوع التدقيق والتي يتوجب على المكلف إبرازها .\n ‐2يحق لرئيس الإدارة الضريبية المختصة تكليف الموظف بالكشف والتحقق من السجلات والمستندات المحاسبية\n وغيرها من العناصر المادية المرتبطة لممارسة النشاط تنفيذا لأمر مهمة خاص خطي لا يبلغ مسبقا للمكلف وذلك في\n حال آان لديها شكوك جدية بأن إبلاغه قد يعرض عملية التدقيق إلى الفشل شرط أن تكون هذه الشكوك مرتكزة على\n معلومات موثوقة وردت إلى الإدارة الضريبية ،أو على سوابق المكلف مع هذه الإدارة .\n حدود عملية التدقيق المادة ‐ 47\n ‐ 1على الموظف المولج بالتدقيق أن يبرز للمكلف عند البدء بمهمته بطاقة الوظيفة وأمر المهمة.\n ‐2تجري عملية التدقيق ميدانيا خلال ساعات الدوام الرسمي ،واستثنائيا خلال ساعات عمل المكلف .\n لا يمكن أن تتجاوز عملية التدقيق الميداني عند المكلف مهلة ثلاثة أشهر من تاريخ البدء بمهمة التدقيق .ويمكن لرئيس\nالإدارة الضريبية أن يمدد هذه المهلة لمدة أقصاها ثلاثة أشهر إضافية بناء لطلب معلل من الموظف المولج بمهمة التدقيق\n وذلك وفقا للأصول الإدارية .\n‐3تقتصر عملية التدقيق على الفترات الضريبية المحددة في أمر المهمة ،غير أنه يمكن أن تتناول أيضا فترات ضريبية\n أخرى بموافقة رئيس الوحدة المختصة .\n ‐4تتناول عملية التدقيق فقط الفترات الضريبية التي لم تسقط بعد بعامل مرور الزمن .وتشمل عجز الفترات الضريبية\n السابقة التي شملها مرور الزمن ،والذي تم تدويره الى الفترة الضريبية موضوع أمر المهمة .وفي هذه الحالة ،يقتصر\n التدقيق على ما يتعلق بقبول هذا العجز أو بتعديل مقداره زيادة أو نقصانا أو بإلغائه."}, {"o": 32, "l": "المادة 27", "b": "‐5على المكلف التعاون مع الموظف المولج بالتدقيق وتسهيل مهمته ،ولا يحق لهذا الموظف أن ينقل السجلات\n والمستندات التي توضع تحت تصرفه من مكانها ،بل يجب عليه مراجعتها في هذا المكان .\n ‐6لا يمكن إعادة تدقيق فترة ضريبية مدققة سابقا إلا في حالة ورود معلومات جديدة تؤثر على احتساب قيمة الضريبة\n المتوجبة وضمن نطاق هذه المعلومات فقط .\n حق الاستحصال على المعلومات المادة ‐ 48\n‐ 1يحق للإدارة الضريبية من اجل القيام بعملية التدقيق ،أن تطلب خطيا وضمن إطار القوانين والأنظمة النافذة من أي\n 16\n\f شخص لديه معلومات تفيد التحقق من صحة الضريبة المتوجبة على أي مكلف ،إعطاءها المعلومات التي تحددها وذلك\n ضمن مهلة تحددها الإدارة .\n‐2يمكن للموظف المولج بعملية التدقيق الإستحصال على صور من السجلات والمستندات ويكون لها ذات القوة الثبوتية\n لنسخها الأصلية شرط إقتران هذه النسخ بتوقيع الموظف والمكلف على أنها مطابقة للأصل .\n آما يحق له أن يطلب من صاحب العلاقة أو ممن يمثله الحضور في أماآن التدقيق والإجابة على الأسئلة التي تطرح\n عليه من أجل حسن تنفيذ المهمة والقيام بكل ما يوجبه التعاون مع الإدارة الضريبية .\n ‐3في حال آانت السجلات والمستندات ممسوآة أو محفوظة بطريقة إلكترونية ،يحق لموظفي الإدارة الضريبية\n المختصة طلب الإطلاع على برنامج المحاسبة الممكنن والمعلومات المسجلة فيه ،والحصول على هذه المعلومات بشكل\n مستندات رقمية أو ورقية يمكن قراءتها .\n‐4في حال تمنع المكلف أو أي شخص آخر عن الاستجابة لما تحدده البنود أعلاه من هذه المادة ،تطبق أحكام الفقرة )(6\n من"}, {"o": 33, "l": "المادة 42", "b": "المادة 42والغرامات المنصوص عليها في هذا القانون .\n نتائج التدقيق المادة ‐ 49\n ‐ 1مع مراعاة أحكام"}, {"o": 34, "l": "المادة 43", "b": "المادة 43من هذا القانون ،يتوجب على الإدارة الضريبية أن تبلغ المكلف النتائج الأولية للتدقيق،\nوتعطيه مهلة ثلاثين يوما لإبداء ملاحظاته عليها ،وذلك قبل إصدار التكليف الضريبي بصورة رسمية ،ولا يؤدي إعطاء\n المهلة المذآورة إلى سقوط ،الضرائب موضوع هذه التكاليف بعامل مرور الزمن.\n ‐2في حال أبرز المكلف معطيات أو مستندات ثبوتية جديدة ،يمكن للإدارة الضريبية استنادا الى هذه المعطيات\n والمستندات بعد دراستها أن تعدل في النتائج الأولية للتدقيق التي تكون قد توصلت إليها.\n ‐3تعمد الإدارة الضريبية إلى إصدار التكليف النهائي في مهلة أقصاها شهر تبدأ من تاريخ إستلامها ملاحظات المكلف\nأو من تاريخ إفادة المكلف بعدم وجود أي ملاحظات لديه أو عند إنقضاء المهلة المنصوص عليها في البند الأول من هذه\n المادة ،ولا تؤدي هذه المهلة الإضافية إلى سقوط الضرائب موضوع هذه التكاليف بعامل مرور الزمن .\n يتم إبلاغ المكلف النتيجة النهائية للتدقيق بموجب إعلام ضريبي ،وفي حال أدى هذا التدقيق إلى تعديلات ضريبية ،تبين\n الإدارة الضريبية في هذا الإعلام مقدار هذه التعديلات وأسبابها.\n ‐4تحدد دقائق تطبيق هذه المادة بموجب قرارات تصدر عن وزير المالية .\n مضمون الاعلام الضريبي المادة ‐ 50\n يتضمن الإعلام الضريبي ما يلي :\n ‐1رقم وتاريخ الإعلام.\n ‐2اسم المكلف وعنوانه.\n ‐3رقمه الضريبي.\n ‐4المبالغ الخاضعة للضريبة مع تحديد الفترات الضريبية العائد لها .\n ‐5أسباب التكليف .\n ‐6قيمة الضريبة والفوائد والغرامات المتوجبة .\n ‐7طلب تسديد المبالغ المتوجبة ضمن المهلة القانونية .\n ‐8بيان طرق التسديد الجائز إعتمادها .\n ‐9مهل الإعتراض .\n ‐10توقيع رئيس الإدارة الضريبية أو من يكلفه بذلك .\n 17\n\f عبء الاثبات المادة ‐ 51\n يقع عبء إثبات صحة التصريح بالضريبة على المكلف ،ويقع هذا العبء على الإدارة الضريبية لإثبات صحة"}, {"o": 35, "l": "المادة 43", "b": "التكاليف الإضافية في حال أجرت تعديلات على التصريح .\n الفصل التاسع\n دفع وتحصيل الضريبة\n احكام عامة المادة ‐ 52\n ‐ 1تتولى مهام التحصيل مديرية الواردات والماليات في المناطق فيما خص الضرائب والرسوم التي تتولى فرضها\n ومديرية الضريبة على القيمة المضافة فيما خص هذه الضريبة .\n ‐2يجري تحصيل الضريبة طوعا أو جبرا .\n ‐3يقصد بالتحصيل الطوعي ،تأدية الضريبة المباشرة من قبل المكلف .أما التحصيل الجبري فهو تحصيل الضرائب\n غير المسددة من قبل الإدارة الضريبية وفقا لأحكام هذا القانون .\n مهل تسديد الضريبة المادة ‐ 53\n ‐ 1يحدد القانون الخاص بكل ضريبة مهلة تسديدها .\n‐2باستثناء الحالات التي تنص عليها القوانين المرعية الاجراء ،يجب تسديد التكاليف التي تفرض ضريبة إضافية خلال\n مهلة شهرين من تاريخ إبلاغ التكليف بصورة شخصية .\n استرداد الضريبة المادة ‐ 54\n ‐ 1إذا زادت قيمة الضريبة المدفوعة عن قيمة الضريبة المتوجبة ،وما لم ينص هذا القانون أو قوانين أخرى على\nخلاف ذلك ،يحق للإدارة الضريبية أن تستعمل الزيادة الحاصلة لأجل استيفاء المبالغ المتوجبة على المكلف من ضرائب\n أخرى ،على أن تبلغه بذلك ،وعلى أن يراعى الترتيب المحدد في البند ) (2من هذه المادة وأحكام الفقرة ) (2من"}, {"o": 36, "l": "المادة 59", "b": "المادة\n 59من هذا القانون المتعلقة بتوزيع المبالغ المدفوعة .\n يرد إلى المكلف الرصيد المتبقي من الزيادة ضمن مهلة خمسة وأربعين يوما من تاريخ تقديم طلب الاسترداد .\nوفي حال آانت الزيادة ناتجة عن اآتشاف خطأ من قبل الإدارة الضريبية ،فعلى هذه الإدارة أن تعيد الزيادة تلقائيا وبدون\n طلب ضمن مهلة ثلاثين يوما من تاريخ اآتشاف الخطأ .\n ‐2إذا آان مستحقا عدة ضرائب خلال الفترة الضريبية ذاتها ،تقوم الإدارة الضريبية بتوزيع المبالغ المدفوعة على\n الضرائب المقتطعة عند المنبع والضريبة على القيمة المضافة أولا وثم على المبالغ الأخرى المتوجبة ،وفي حال آانت\n المبالغ المتوجبة عائدة لأآثر من فترة ضريبية ،يخصص الفائض للموجب الضريبي الأقدم أولا .\n ‐3تحسب على المبالغ المدفوعة الزائدة قيمتها عن قيمة الضريبة المتوجبة فائدة بمعدل %75،0شهريا من مقدار تلك\n المبالغ ،وذلك ابتداء من تاريخ انتهاء المهلة المنصوص عليها في البند الأول من هذه المادة ،ويعتبر آسر الشهر شهرا\n آاملا .\n أما إذا آانت الضريبة المستردة ناتجة عن قرار باطل ،ملغى ،أو معدل من قبل الإدارة الضريبية ،أو بموجب قرار\n قضائي ،أو في حال حصول خطأ مادي من قبل الإدارة الضريبية أدى إلى دفع ضريبة تزيد قيمتها عما هو متوجب\n قانونا ،تحتسب عندها الفائدة من اليوم الذي دفع فيه المكلف هذه الضريبة .\n 18\n\f غرامات التأخير في تسديد الضريبة )غرامة التحصيل) المادة ‐ 55\n ‐ 1في حال عدم تسديد الضريبة المتوجبة عن فترة ضريبية معينة ضمن المهل القانونية أو عند وجود نقص في\n الضريبة المسددة ،يضاف إلى الضريبة غير المسددة أو الناقصة غرامة تأخير في الدفع )غرامة تحصيل( بمعدل %1\nشهريا من مقدار الضريبة غير المسددة و% 5،1شهريا بالنسبة للضرائب التي يتم اقتطاعها عند المنبع وبالنسبة للضريبة\n على القيمة المضافة ويعتبر آسر الشهر شهرا آاملا .\n ‐2تسري غرامة التأخير في الدفع :"}, {"o": 37, "l": "المادة 59", "b": "‐في حالات التكليف الذاتي بالضريبة وفي الحالات التي تكلف فيها الإدارة الضريبية بضريبة إضافية :إعتبارا من تاريخ\n انتهاء مهلة الدفع الأساسية .\n ‐في الحالات التي لم تلزم فيها القوانين الضريبية التكليف الذاتي بالضريبة :إعتبارا من تاريخ انتهاء المهلة المحددة\n للدفع .\n مرور الزمن على تحصيل الضريبة المادة ‐ 56\n عدل نص المادة ، 56بموجب المادة الاولى من القانون رقم 54تاريخ 27/12/2008واصبح على الوجه التالي:\n مع مراعاة احكام الفقرة ) (4من"}, {"o": 38, "l": "المادة 64", "b": "المادة 64من هذا القانون المتعلقة ببدء اجراءات التحصيل الجبري .\n ‐لا يمكن تحصيل الضريبة المتوجبة بعد انقضاء اربع سنوات تلي انتهاء السنة التي صدر فيها التكليف .\n‐لا يطبق هذا النص على التكاليف الصادرة قبل نفاذ هذا القانون وتطبق عليها النصوص المعمول بها بتاريخ صدورهذه\n التكاليف .\n الفصل العاشر\n تحصيل الضريبة بالطرق العادية\n طرق تسديد الضريبة المادة ‐ 57\n ما لم ينص هذا القانون على خلاف ذلك ،يجب أن تسدد الضريبة بدفع المبلغ المتوجب بوسائل مختلفة ،وذلك وفقا\n لأصول وإجراءات تحدد بقرارات تصدر عن وزير المالية .\n تاريخ الدفع المادة ‐ 58\n ‐ 1تعتبر الضريبة مدفوعة في اليوم الذي يتم فيه تسديد قيمتها من قبل المكلف أو المقتطع سواء إلى الخزينة ،أو إلى\n المرجع الذي يتولى قبضها لحساب الخزينة .\n‐2تؤدي الضرائب والرسوم الخاضعة لنظام الدفع المسبق ،السنوية منها والدورية فقط ،لدى أي من المصارف الخاصة\n أو فروعها العاملة في لبنان ،أو لدى أي من المكاتب التابعة لشرآة ليبان بوست أو أي شرآة أخرى تتعاقد معها وزارة\n المالية لهذا الغرض ،أما التكاليف الإضافية والتكميلية فتسدد لدى صناديق الخزينة المختصة ،آما يمكن تأديتها لدى\n المصارف أو فروعها أو لدى أي من مكاتب شرآة ليبان بوست أو أي شرآة أخرى تتعاقد معها وزارة المالية لهذا\n الغرض.\n يمكن أيضا تأدية الضريبة بصورة إلكترونية وفقا لآلية تحدد بقرار يصدر عن وزير المالية .\n ‐3يعتبر الدفع حاصلا :\n ‐بتاريخ الدفع النقدي .\n ‐بتاريخ تقديم وسيلة الدفع الى الصندوق المخصص لهذا الدفع .\n 19\n\f ‐بتاريخ إرسال المبالغ المتوجبة إلى هذا الصندوق بتاريخ صحيح .\n توزيع المبالغ المدفوعة المادة ‐ 59\n ‐ 1يجاز للمكلف تأدية مبالغ على حساب الضرائب المتوجبة عليه ،ويجب على المكلف في هذه الحالة تحديد نوع\n الضريبة المتوجبة والفترة الضريبية التي تعود لها ."}, {"o": 39, "l": "المادة 64", "b": "تحدد دقائق تطبيق هذه الفقرة بموجب قرار يصدر عن وزير المالية .\n ‐2في حال آان المبلغ المدفوع غير آاف لتسديد آامل قيمة الضريبة المتوجبة ،يوزع هذا المبلغ وفق التسلسل التالي :\n أ -الفائدة .\n ب -غرامة التأخير في دفع الضريبة في حال وجودها .\n ج -غرامات التحقق من الضريبة في حال وجودها .\n د -الضريبة .\n الامتياز العام للخزينة المادة ‐ 60\n‐ 1من أجل تحصيل الضرائب المتوجبة على المكلف تنفيذا للقوانين الضريبية ،تتمتع الخزينة بامتياز عام من الدرجة\n الأولى على جميع أمواله المنقولة وغير المنقولة .\n ‐2يطال الامتيازالعام أيضا أموال الأشخاص الذين يعتبرون مسؤولين وفقا لأحكام هذا القانون .\n ‐3للإمتياز العام للخزينة أولوية على الإمتيازات الخاصة والعامة الأخرى .\n تتمتع الأموال غير المنقولة المؤمنة والمرهونة والأموال المنقولة المرهونة بالأولوية على امتياز الخزينة متى آان\n تسجيلها أو إيداعها مثبتا بتاريخ صحيح سابق لتاريخ تسجيل إمتياز الخزينة .\n ‐4للإدارة الضريبية تسجيل الإمتياز العام للخزينة على الصحيفة العينية لعقارات المكلف وفي السجلات الرسمية\n المختصة التي تقوم مقامها وذلك عند توجيه الإنذار بالدفع الى المكلف المنصوص عليه في"}, {"o": 40, "l": "المادة 63", "b": "المادة 63من هذا القانون،\n ويسري مفعول هذا الامتياز بوجه الغير اعتبارا من تاريخ تسجيل الإشارة المذآورة .\n ‐5يسري إمتياز الخزينة أيضا في حالة الصلح الاحتياطي أو الإفلاس .\n تقسيط دفع الضريبة المادة ‐ 61\n ‐ 1مع مراعاة الأحكام المتعلقة بتقسيط رسم الإنتقال الواردة في المرسوم الإشتراعي رقم 146تاريخ\n 1959/6/12وتعديلاتها ،يحق للإدارة الضريبية أن تقسط آامل الضريبة الإضافية المتوجبة أو جزءا منها ،بناء على\n طلب إسترحام خطي ومبرر من المكلف يبين فيه الأسباب التي تمنعه من دفع الضريبة المتوجبة ،وذلك إذا آانت تأديتها\n في الوقت المحدد لها :\n أ -تشكل عبئا جسيما على المكلف .\n ب -أو تؤدي لإحداث ضرر مادي فادح به .\n ‐2تعود صلاحية قبول أو رفض طلب تقسيط الضريبة لمدير المالية العام أو لأي شخص مفوض من قبله :\nعلى الإدارة الضريبية ضمن مهلة عشرة أيام قبول الطلب أو رفضه معللة أسباب القبول أو الرفض .لا يقبل قرار الإدارة\n الضريبية أي طريق من طرق المراجعة بما في ذلك مراجعات الإبطال لتجاوز حد السلطة .\n ‐3ينفذ تقسيط الضريبة بناء على برنامج تقسيط تضعه الإدارة الضريبية ويوقعه المكلف بالموافقة عليه .\n ‐4لا يمكن تقسيط الضريبة لفترة تزيد عن ثلاث سنوات ،ولا يمكن إعادة جدولة برنامج التقسيط .\n ‐5في حال لم ينفذ المكلف أي بند من برنامج التقسيط ،أو في حال إعلان إفلاسه أو تصفية أعماله تسقط إجراءات\n التقسيط ومهلها حكما ،وعلى الإدارة الضريبية المباشرة بإجراءات تحصيل الضريبة المستحقة وفقا لأحكام هذا القانون .\n 20\n\f ‐6تسري مهل مرور الزمن على آل مبلغ مقسط إعتبارا من تاريخ استحقاق دفعها .\n ‐7تحسب الفائدة المتوجبة على المبالغ المقسطة بمعدل الفائدة المحددة على سندات الخزينة لمهل التقسيط .\n ‐8تستثنى من أحكام تقسيط الضريبة المنصوص عليها في هذه المادة جميع الضرائب التي تخضع لنظام الإقتطاع عند"}, {"o": 41, "l": "المادة 63", "b": "المنبع وآذلك الضريبة على القيمة المضافة .\n ‐9في حال رفض طلب التقسيط ،لا يحق للمكلف أن يقدم طلبا جديدا بتقسيط الضريبة مرة واحدة إلا إذا تضمن الطلب\n الجديد شرحا لأسباب وظروف جديدة تبرر إعادة النظر به .\n ‐10تحدد دقائق تطبيق هذه المادة بقرار يصدر عن وزير المالية .\n الضمانات المادة ‐ 62\n في حال تقسيط الضريبة وفقا لأحكام"}, {"o": 42, "l": "المادة 61", "b": "المادة 61من هذا القانون توضع إشارة التقسيط على أموال المكلف المنقولة\n وغير المنقولة وذلك بمبلغ يعادل ضعفي قيمة الضريبة المقسطة على الأقل .\n الانذار بالدفع المادة ‐ 63\n ‐ 1عند تخلف المكلف عن تأدية الضريبة المتوجبة عليه ضمن المهل القانونية ،على الإدارة الضريبية أن توجه إليه\n إنذارا شخصيا مع إشعار بالاستلام تدعوه فيه إلى تأدية الضريبة ضمن مهلة شهر من تاريخ إبلاغه الإشعار على أن\n تراعى في التبليغ أحكام المادتين 27و 28من هذا القانون .\n ‐2يجب أن يتضمن الإنذار نوع الضريبة المتوجبة ،الغرامات ،الفوائد المستحقة ،الفترات الضريبية العائدة لها ،مهل\n الدفع ،وآذلك تدابير التحصيل التي يمكن اللجوء اليها في حال عدم التسديد .\n الفصل الحادي عشر\n التحصيل الجبري للضريبة\n الجزء الاول\n احكام عامة\n بدء اجراءات التحصيل الجبري المادة ‐ 64\n ‐ 1في حال تخلف المكلف عن التسديد ضمن المهلة المحددة في الإنذار بالدفع ،تعمد الإدارة الضريبية بموافقة مدير\n المالية العام أو من يفوضه إلى إصدار قرار خطي بتحصيل الضرائب جبريا يبلغ إلى المكلف .\n ‐2يحدد القرار المذآور في البند الأول من هذه المادة المبالغ المتوجبة والتي لا تزال غير مسددة .\n ‐3يصبح قرار التحصيل الجبري نافذا في اليوم التالي لتاريخ تبليغه إلى المكلف .\n‐4يوقف القرار القاضي بتحصيل الضرائب جبرا سريان عامل مرور الزمن على تحصيل المبالغ التي يتناولها ،دون أن\n يوقف سريان الغرامات والفوائد تجاه المكلف .\n ‐5يحق للمكلف أن يعترض على قرار التحصيل الجبري وفقا لأحكام الفصل الثاني عشر من هذا القانون .\n‐6يمكن للإدارة الضريبية أن تطلب من الجهات المعنية اقتطاع ما يترتب على المكلف من ضرائب من أصل ما يستحق\n له على الخزينة من ديون .\n ‐7يمكن لوزارة المالية أن تطلب من دوائر التنفيذ المختصة لدى وزارة العدل تحصيل ما يترتب لها بذمة المكلفين من\n ضرائب."}, {"o": 43, "l": "المادة 61", "b": "تطبق أمام دوائر التنفيذ المختصة التي تتولى تنفيذ طلبات التحصيل الواردة من وزارة المالية الأصول المنصوص عليها\n في هذا القانون .\n 21\n\f اجراءات التحصيل الجبري المادة ‐ 65\n يجري التحصيل الجبري وفقا لأحكام هذا القانون من خلال قيام الإدارة الضريبية بالإجراءات التسلسلية التالية :\n أ -حجز أموال المكلف المنقولة وغيرالمنقولة باستثناء تلك التي لا يسمح بحجزها بموجب القوانين والأنظمة النافذة .\n ب -بيع هذه الأموال بالمزاد العلني .\n وقف اجراءات التحصيل الجبري المادة ‐ 66\n ‐ 1يوقف مؤقتا تنفيذ الإجراءات المتعلقة بقرار التحصيل الجبري في الحالات التالية :\n أ -إذا تقدم المكلف بطلب تقسيط الضريبة المنصوص عليه في"}, {"o": 44, "l": "المادة 61", "b": "المادة 61من هذا القانون ،وذلك حتى البت في الطلب\n المذآور .يستمر هذا التوقف على المبالغ الموافق على تقسيطها ما دام المكلف يلتزم بدفع الأقساط في مواعيدها وفقا\n لشروط التقسيط .\n ب -خلال مهلة ثلاثة أشهر من حصول الحالات التالية :\n ‐وفاة المكلف،\n ‐فقدان أهليته،\n ‐زوال الصفة القانونية لمن آان يمثل المكلف .\n ج -في حال اعترض المكلف على قرار التكليف المستند إليه التحصيل الجبري وفقا لأحكام"}, {"o": 45, "l": "المادة 97", "b": "المادة 97وما يليها من هذا\n القانون ،وذلك لحين تبليغ المكلف القرار النهائي المبرم الصادر بشأن هذا الإعتراض .\n يطبق هذا البند فقط على تحصيل الضريبة المعترض عليها .\n ‐2يبدأ وقف الإجراءات بتاريخ موافقة الإدارة الضريبية على أسباب الوقف وينتج عن هذا التوقف انقطاع جميع المهل\n المتعلقة بهذه الإجراءات .\n بعد زوال أسباب الوقف ،تستأنف الإدارة الضريبية القيام بإجراءات التحصيل .\n ‐3مع مراعاة أحكام البند )) 1من"}, {"o": 46, "l": "المادة 102", "b": "المادة 102من هذا القانون ،يستمر سريان غرامة التأخير في تسديد الضريبة\n المنصوص عليها في"}, {"o": 47, "l": "المادة 55", "b": "المادة 55من هذا القانون طيلة مدة وقف إجراءات التحصيل الجبري ،شرط أن لا تزيد تلك المدة\n عن عشرين شهر وإلا يتوقف سريان الغرامة المذآورة من تاريخ انتهاء هذه المدة .\n ‐4إن اعتراض المكلف على قرار التحصيل الجبري لا يوقف إجراءات تنفيذه ،إلا إذا صدر عن مجلس شورى الدولة\n قرار بوقف التنفيذ .\n الاعفاء من اجراءات التحصيل الجبري المادة ‐ 67\nلا يمكن الإعفاء من إجراءات التحصيل الجبري إلا بموجب قانون يقضي إما بإلغاء الضريبة ،أو بالإعفاء من تسديدها،\n أو بقرار نهائي يصدر عن المراجع المختصة نتيجة للإعتراض يقضي بإلغاء التكليف .\n انهاء اجراءات التحصيل الجبري المادة ‐ 68\n ‐ 1تنتهي إجراءات التحصيل الجبري في الحالات التالية :\n أ -إذا سدد المكلف ما يتوجب عليه .\n ب ‐عند إآتشاف خطأ مادي من شأن تصحيحه أن يلغى آامل الضريبة .\n ‐2عند توافر الشروط المنصوص عليها في البند الأول من هذه المادة ،على الإدارة الضريبية بموافقة مدير المالية العام\n 22\n\f أن تصدر قرارا بإنهاء إجراءات التحصيل الجبري وتبلغه إلى المكلف .\n‐3ليس من شأن إنهاء إجراءات التحصيل الجبري أن يؤثر على الحجوزات الموضوعة لصالح إدارات أخرى ،ولا على\nمسؤولية المكلف بتحمل أعباء التحصيل إلا إذا آان الخطأ الوارد في الفقرة )ب( من البند الأول من هذه المادة آان بفعل\n الإدارة الضريبية .\n متابعة اجراءات التحصيل الجبري عند حصول نزاع حول صفة الورثة او اصحاب الحق او تعذر المادة ‐ 69\n تحديدهم\n ‐ 1في حالة وفاة المكلف ،يلاحق ورثته بالضرائب التي آانت متوجبة عليه ضمن الحدود التي يجيزها القانون .\n ‐ \u00152في حال حصول نزاع حول صفة الورثة أو أصحاب الحق أو في حال تعذر تحديدهم ،جاز للإدارة الضريبية\n المختصة طلب تعيين ممثل للورثة ومتابعة إجراءات التحصيل الجبري بعد تعيين هذا الممثل أو بعد مرور ثلاثة أشهر"}, {"o": 48, "l": "المادة 55", "b": "منذ تاريخ تقديم الطلب المذآور .ويبقى حق الإدارة الضريبية والورثة محفوظا في الفروقات التي قد تظهر عند بت\n النزاع حول صفة الورثة أو أصحاب الحق .\n الجزء الثاني\n التنفيذ على اموال المكلف\n اولا :الحجز\n حجز اموال المكلف المادة ‐ 70\n في حال لم يسدد المكلف الضريبة بعد انقضاء مهلة الإنذار الشخصي بالدفع واستصدار الإدارة الضريبية قرارا ببدء\n إجراءات التحصيل الجبري وفقا لأحكام"}, {"o": 49, "l": "المادة 64", "b": "المادة 64من هذا القانون ،تعمد الإدارة الضريبية إلى استصدار قرار من مدير\n المالية العام بحجز أموال المكلف ،لديه أو لدى شخص ثالث ،وبيعها .\n صلاحية تنفيذ الحجز المادة ‐ 71\n تتولى الإدارة الضريبية بموافقة مدير المالية العام صلاحية تنفيذ الحجز مباشرة ،ولها أن تستعين بقوى الأمن عند\n الاقتضاء .\n الحجز تحت يد شخص ثالث وتحصيل المبالغ المتوجبة المادة ‐ 72\n ‐ 1الحجز تحت يد شخص ثالث هو حجز الأموال العائدة للمكلف المحجوز عليه والموجودة في يد شخص ثالث\n )المحجوز لديه( ،وتحصيل المبالغ المتوجبة على هذا الشخص الثالث المحجوز لديه لصالح المكلف .\n ‐2يبلغ قرار الحجز ومستنداته الى المحجوز لديه والمحجوز عليه .\n ‐3في حال الحجز تحت يد شخص ثالث ،لا تؤخذ بعين الاعتبار المدفوعات التي يدعي هذا الشخص تسديدها قبل\n المواعيد المعينة لها ،ما لم يكن الدفع ثابتا بسند مصدق أو مؤيدا بتاريخ ثابت .\n ‐4على المحجوز لديه أن يصرح للإدارة الضريبية خلال خمسة أيام من تاريخ تبلغه قرار الحجز بما في ذمته من مال\n أو دين للمحجوز عليه ،ومقدار الدين أو رصيده ،وسببه وشروطه والحجوزات التي ألقيت عليه ،وآذلك الأشياء من\n المثليات والأعيان المنقولة .\n وعليه أن يصرح لاحقا أيضا بكل ما يقع على المال أو الدين من حجز أو حوالات ،وبكل ما يقع على المال من هلاك،\n وذلك خلال خمسة أيام من تاريخ حصول الواقعة .\n 23\n\f ‐5إذا لم يرسل المحجوز لديه التصريح الأساسي إلى الإدارة الضريبية ضمن المهلة المعينة ،أصبح ملزما تجاه الخزينة\n بالمبلغ المتوجب عليه للمكلف ،إلا ّإذا أبدى عذرا حريا بالقبول تقدره الإدارة الضريبية .\n ‐6إذا تبين أن التصريح المذآور في البند 4من هذه المادة والمقدم من قبل المحجوز لديه غير صحيح ،أصبح هذا\n الأخير ملزما بالفرق بين المبالغ المصرح عنها والمبالغ المتوجبة عليه للمكلف ،مع حفظ حق الخزينة بالتعويض لما"}, {"o": 50, "l": "المادة 64", "b": "أصابها من ضرر بسبب ما أحدثه هذا التأخير أو ما جرى تكبده من نفقات .\n ‐7في حال أخفى المحجوز لديه عن سوء نية الأموال موضوع الحجز ،يصبح ملزما بالمبالغ المتوجبة عليه للمكلف\n بالإضافة الى العقوبات المنصوص عليها في القوانين المرعية الاجراء .\n مفاعيل الحجز المادة ‐ 73\n ‐ 1يترتب على الحجز تجميد المال المحجوز بأجمعه تحت يد المكلف المحجوز عليه والشخص الثالث المحجوز لديه\n وذلك من تاريخ تبلغ الحجز ،ويعتبر في هذه الحالة المكلف أو المحجوز لديه حارسا على الأموال المحجوزة .\n ‐2يمنع على الشخص الثالث المحجوز لديه تسليم المال المحجوز أو دفعه إلى دائنه أو إجراء المقاصة معه على الدين .\n آما يمنع على المحجوز عليه تسلم المال المحجوز أو قبض الدين أو إسقاطه أو إنقاص قيمته ،أو منح مهلة لمدينه ومن\n التصرف بالمال المحجوز .\nعلى المكلف المحجوز عليه أو الشخص الثالث المحجوز لديه إدارة المال المحجوز إدارة الشخص الحريص على مصالح\n الخزينة وسائر المدينين .\n ليس من شأن الحجز أن يوقف سريان الفوائد على المحجوز لديه ،طالما ان المال محجوز بحوزته .\n ‐3إذا وقع الحجز على سندات وأسهم اسمية وعلى قيم منقولة اسمية أخرى ،فإنه يمنع على المكلف أو المحجوز لديه\n التصرف بها أو بفوائدها أو عائداتها .\n ‐4في حال التصرف بالمال المحجوز خلافا لأحكام هذه المادة ،تطبق أحكام قانون العقوبات بحق المخالفين .\n ‐5يمكن للإدارة الضريبية ،بناء على طلب من المكلف ،أن تحصر الحجز بجزء من المال يكون آافيا لتسديد الدين .\n يطبق امتياز الخزينة على الجزء الذي حصر فيه الحجز .\n دخول الاماآن لتنفيذ الحجز المادة ‐ 74\n على الموظف المولج بإلقاء الحجز على أموال المكلف أو تنفيذ الحجز لدى شخص ثالث أن ينتقل إلى أماآن وجود\n الأشياء والأموال لأجل إلقاء الحجز عليها ،وعليه أن لا يدخل بيت المكلف أو المحجوز لديه إلا بعد إعلان صفته"}, {"o": 51, "l": "المادة 64", "b": "الرسمية بحضور مختار المحلة .ويمكن الاستعانة عند الاقتضاء بقوى السلطة العامة .\n الحجز على العقار المادة ‐ 75\n ‐ 1يجري الحجز على العقار وفق الإجراءات التالية :\n أ -على الإدارة الضريبية ،أن تبلغ أمين السجل العقاري ،المختص ،قرار الحجز آي يقيده في الصحيفة العينية للعقار .\n ب -في حال لم يكن العقار خاضعا لنظام السجل العقاري ،على الإدارة الضريبية أن تبلغ قرار الحجز الى مختار المحلة\n الذي عليه أن يقيد الحجز حالا في الدفتر الموجود لديه أو في دفتر ينشئه لهذه الغاية وصورة أخرى إلى أمين السجل\n العقاري المختص الذي يجب عليه أن يقيد الحجز حالا في سجل خاص يتخذه لديه لكل قريه أو بلدة أو منطقة عقارية .\n ج -إذا آان العقار قيد التحديد والتحرير ،تبلغ صورة عن قرار الحجز إلى القاضي العقاري لقيد الحجز على محضر\n التحديد والتحرير .\n د -على المرجع الذي تولى قيد الحجز في سجلاته بموجب هذه المادة أن يعيد وثيقة التبليغ إلى الإدارة الضريبية موقعا\n عليها منه بجانب خاتمه الرسمي ومع ذآر تاريخ التبليغ .\n 24\n\f ‐2للإدارة الضريبية المختصة أن تأذن بناء على طلب ذوي العلاقة بجني المحصولات وبيعها بالطريقة المناسبة وإيداع\n الثمن في صندوق الخزينة .\n ثانيا :بيع الاموال المحجوزة بالمزاد العلني\n بيع الاموال المحجوزة المادة ‐ 76\n تباع الأموال المحجوزة بالمزاد العلني وفقا للإجراءات المنصوص عليها في هذا القانون ،باستثناء الأموال المتداولة\n في الأسواق المالية المحلية والدولية ،فتباع مباشرة في تلك الأسواق .\n لجنة البيع المادة ‐ 77\n تتولى البيع بالمزاد العلني في آل محافظة لجنة تشكل بمرسوم ،قوامها :\n ‐قاض يعين بناء على اقتراح وزير العدلية )رئيسا )\n ‐أمين السجل العقاري في مرآز المحافظة في حالة بيع عقارات محجوزة )عضوا)\n ‐مندوب عن غرفة الصناعة والتجارة في المحافظة )عضوا)"}, {"o": 52, "l": "المادة 64", "b": "‐موظف تابع للوحدة الإدارية المختصة بمهام التحصيل الجبري من الفئة الثالثة )عضوا مقررا)\n تأخذ اللجنة قراراتها بالأآثرية وفي حال تعادل الأصوات يكون صوت الرئيس مرجحا .\n صلاحية لجنة البيع المادة ‐ 78\n ‐ 1تتولى لجنة البيع المنصوص عليها في"}, {"o": 53, "l": "المادة 77", "b": "المادة 77من هذا القانون تخمين وبيع الأموال المحجوزة بالمزاد العلني .\n ‐2تباشر لجنة البيع مهامها فور إحالة ملف إلقاء الحجوزات على أموال المكلف المتخلف عن الدفع إليها من قبل مدير\n المالية العام .\n ‐3تجتمع اللجنة بدعوة من رئيسها خلال خمسة عشر يوما من تاريخ إحالة الملف إليها آحد أقصى ،ولا تعتبر الجلسة\n قانونية إلا إذا حضرها الرئيس وجميع الأعضاء .وفي حال لم تجتمع اللجنة خلال خمسة عشر يوما بدون عذر شرعي\nيكون إجتماعها قانونيا بدعوة من الرئيس وحضوره وبمن يحضر من الأعضاء ،ويتعرض المتغيب لملاحقات تأديبية من\n قبل الجهة التي يمثلها .\n ‐4يمكن للجنة البيع ،عند الاقتضاء ،دعوى المكلف المحجوز عليه إلى حضور جلساتها .\n ترتيب بيع الاموال المحجوزة المادة ‐ 79\n ‐ 1تحدد لجنة البيع ترتيب بيع الأموال المحجوزة بموجب محضر ووفقا للائحة تعدها ،بحيث تباع بالأولوية الأموال\n التي يكون حرمان المكلف منها أخف ضررا عليه .\n‐2إذا آانت الأموال المحجوزة عرضة للتلف ،فيجب أن يقرر رئيس لجنة البيع ،بناء على طلب ذوي العلاقة أو الحارس\n القضائي في حال وجوده ،بيعها دون التقيد بالضرورة بالإجراءات المنصوص عليها في القانون وذلك بالطريقة التي\n تتناسب ومصلحة الخزينة .\n‐3يباع حق جني المحاصيل الزراعية بالمزايدة ،غير أنه يجوز لرئيس لجنة البيع تفويض أمر جنيها إلى الحارس ،أو أن\n تتولى اللجنة هذا الأمر بالطريقة المناسبة إذا آان النضوج بلغ حدا يخشى معه إصابة المزروعات أو الثمار بضرر،\n فتباع حينئذ الثمار أو المزروعات المجتناة وفق ما تقرره لجنة البيع ،ويستوفي الحارس أو الخزينة ما يكون قد جرى\n تحملة من نفقات جني المحاصيل الزراعية ما يكون قد أنفق على هذا الإجتناء .\n 25\n\f‐4إذا تناول الحجز مصوغات أو سبائك من ذهب أو فضة أو من معدن نفيس أو مجوهرات أو أحجار آريمة ،فيجب أن"}, {"o": 54, "l": "المادة 77", "b": "توزن وتعين أوصافها بدقة وتقدر بمعرفة خبير وتنقل في حرز مختوم إلى مكان تحدده اللجنة وتختمه بالشمع الأحمر .\n ‐5إذا آان الحجز واقعا على أموال محفوظة في خزينة آان قد أستأجرها المكلف من أحد المصارف أو على أموال\n معروضة في معرض عام ،فعلى الموظف المولج بالتنفيذ أن يعين في الحال مدير المصرف أو مدير المعرض حارسا\n لها وتختم الخزنة بالشمع الأحمر إلى أن يتمكن من فتحها وجرد موجوداتها بحضور المحجوز عليه وبحضور مختار\n المحلة .\n تنتهي الحراسة عند استلام الإدارة الضريبية الأموال المحجوزة .\n تحديد القيمة التخمينية للاموال المادة ‐ 80\n تحدد القيمة التخمينية للأموال المنقولة وغير المنقولة الموضوعة في المزايدة ،بواسطة لجنة البيع المنصوص عليها\n في"}, {"o": 55, "l": "المادة 77", "b": "المادة 77من هذا القانون والتي لها أن تستعين بخبراء محلفين لهذه الغاية .\n تحدد قيمة الأموال المتداولة في الأسواق المالية المحلية والدولية بالقيمة المتداولة بها في تلك الأسواق .\n لائحة شروط البيع المادة ‐ 81\n ‐ 1تضع لجنة البيع لائحة بشروط البيع خلال مهلة عشرة أيام من تاريخ وضع لائحة تعداد وترتيب الأموال موضوع\n الحجز المنصوص عليها في البند ) (1من"}, {"o": 56, "l": "المادة 79", "b": "المادة 79من هذا القانون .\n ‐2تبين لائحة الشروط المعلومات التالية :\n أ -أنواع الأموال الموضوعة في المزايدة ومواصفاتها ومحل وجودها .\n ب -القيمة المخمنة للأموال المذآورة ،والسعر الأدنى الذي يجب أن يتخذ أساسا للمزايدة ،على أن يكون معادلا ثلثي\n القيمة المخمنة .\n ج -مقدار الكفالة التي تمكن من الاشتراك بالمزايدة وشروطها .\n د -شروط الدفع .\n هـ -غير ذلك من المعلومات والشروط التي تقتضيها المزايدة .\n ‐3ترسل لجنة البيع خلال ثلاثة أيام من تاريخ وضع لائحة الشروط آتابا إلى المكلف المتخلف عن الدفع للإطلاع على\n هذه اللائحة ولبيان ملاحظاته عليها وتقديمها إلى لجنة البيع ضمن مهلة خمسة أيام من تاريخ التبليغ .\n ‐4بعد انقضاء مهلة الأيام الخمسة المنصوص عليها في البند الثالث من هذه المادة ،تنظر لجنة البيع في الملاحظات\n المقدمة من المكلف ،ويجري على اساسها عند الاقتضاء تعديل لائحة الشروط ،ويكون قرارها بشأن تصديق لائحة\n الشروط نهائيا دون الحاجة الى موافقة أي جهة أخرى أو إلى أي تبليغ .\n الاعلان عن المزايدة المادة ‐ 82\n‐ 1تعلن لجنة البيع عن المزايدة في الجريدة الرسمية وفي صحيفتين يوميتين وعلى الموقع الإلكتروني لوزارة المالية،\nشرط أن لا تقل مهلة الإعلان عن خمسة عشر يوما قبل التاريخ المحدد للمزايدة ،وتلصق نسخة عن الإعلان على لائحة\n الإعلانات لدى الإدارة الضريبية وفي المحافظات بموجب محضر يفيد تاريخ اللصق .\n ‐2يكون في الإعلان :\n أ -هوية المنفذ والمكلف المنفذ عليه ومقام آل منهما .\n ب -موضوع المزايدة ومقدار المبالغ المطلوب تسديدها .\n ج -قيمة التخمين وبدل الطرح والنفقات الواجب دفعها علاوة على البدل آما تقدرها لجنة البيع .\n د -بيان العقار أو العقارات المحجوزة في حال وجودها وبدل الطرح المعين لكل منها وتاريخ تسجيل الحجز في السجل\n 26"}, {"o": 57, "l": "المادة 79", "b": "العقاري أو السجل الخاص المتعلق بالعقارات غير الخاضعة لنظام السجل العقاري أو دفتر المختار أو دفتر التحديد\n والتحرير لدى القاضي العقاري .\n السجل العقاري أو دفتر المختار أو دفتر التحديد والتحرير لدى القاضي العقاري .\n هـ -مكان إجراء المزايدة وموعدها بالشهر واليوم والساعة .\n و -المكان الذي يمكن فيه الاطلاع على لائحة الشروط .\n ز -غير ذلك من المعلومات التي تقتضيها المزايدة .\n الغاء المزايدة المادة ‐ 83\nيحق للمحجوز عليه الذي طرحت أمواله للبيع أن يطلب إلغاء المزايدة ،شرط أن يسدد آامل المبالغ المتوجبة عليه قبل\n موعد افتتاح جلسة المزايدة .\n الاشتراك في المزايدة المادة ‐ 84\n ‐ 1تجري المزايدة بصورة علنية في المكان والموعد المحددين لها .\n ‐2يترتب على آل من يرغب الاشتراك في المزايدة أن يودع باسم رئيس الإدارة الضريبية قبل المباشرة بالمزايدة لدى\n صندوق الخزينة أو أحد المصارف ،مبلغا موازيا لبدل الطرح العائد للأموال موضوع الطرح المحدد في لائحة الشروط\n المنصوص عليها في"}, {"o": 58, "l": "المادة 81", "b": "المادة 81من هذا القانون ،أو أن يقدم آفالة مصرفية تضمن هذا المبلغ .\n‐3يجوز لكل من اشترك في المزايدة ،قام بموجب الإيداع أو الكفالة ولم يكن المزايد الأخير ،أن يسحب المال المودع أو\n الكفالة في اليوم الذي يلي تاريخ انتهاء جلسة المزايدة .\n المحظورات المادة ‐ 85\n يحظر الإشتراك في المزايدة مباشرة أو بالواسطة على :\n أ -رئيس وأعضاء لجنة البيع،\n ب -موظفي وزارة المالية .\n ج ‐أحد أقرباء الأشخاص المذآورين في البندين )أ( و)ب( من هذه المادة الذي تربطه مع المشترك في المزايدة قرابة\n لغاية الدرجة الرابعة .\n ويعتبر البيع لاغيا في الحالات أعلاه ويحال الموظف المخالف على المجلس التأديبي .\n اجراءات جلسة المزايدة المادة ‐ 86\n ‐ 1تعقد لجنة البيع جلسة المزايدة علنا وتبدأ بالمناداة بالبيع وبقيمة بدل الطرح .\n ‐2آل زيادة تسقط الزيادة التي سبقتها .\n تأجيل البيع المادة ‐ 87\n يتم تأجيل البيع في الحالات التي يوقف فيها التحصيل الجبري وفقا لأحكام"}, {"o": 59, "l": "المادة 65", "b": "المادة 65من هذا القانون .\n 27\n\f وقف البيع المادة ‐ 88\n يوقف البيع لأحد الأسباب الآتية:\n أ ‐صدور قرار عن مرجع قضائي مختص يقضي بوقف التنفيذ .\n ب -ارتكاز التنفيذ على سند مدعى تزويره .\n ج -وفاة المكلف المحجوز لديه قبل جلسة المزايدة إذا أبلغت هذه الوفاة إلى الإدارة الضريبية ،ويستمر وقف البيع لمدة\n ثلاثة أشهر من تاريخ الوفاة .\nيعلن عن متابعة إجراءات التنفيذ ضمن مهلة خمسة عشر يوما من تاريخ انتهاء مدة الأشهر الثلاثة وذلك بواسطة الجريدة\n الرسمية وصحيفتين محليتين وعلى الموقع الإلكتروني الخاص بوزارة المالية ،آما ويبلغ الورثة الموعد الجديد للمزايدة .\n متابعة اجراءات البيع المادة ‐ 89\n تتابع لجنة البيع أعمالها في بيع أموال المحجوز عليه وفقا لترتيب بيع الأموال الذي وضعته استنادا إلى"}, {"o": 60, "l": "المادة 79", "b": "المادة 79من\n هذا القانون إلى أن يصبح حاصل البيع آافيا لتسديد المبالغ المترتبة على المكلف .\n بيع الاموال المادة ‐ 90\n ترسو المزايدة فيما يتعلق بالأموال المنقولة وغير المنقولة ،على من يقدم أفضل الأسعار ،وتصبح نهائية بعد موافقة\n لجنة البيع عليها .\n تنفيذ قرار المزايدة النهائي المادة ‐ 91\n ‐ 1يترتب على صدور قرار المزايدة النهائي :\nأ -قيام المشتري بالموجبات الملقاة على عاتقه ،وعلى الأخص دفع الثمن والرسوم والنفقات دونما الحاجة لإنذار أو طلب،\n وذلك خلال مدة عشرين يوما تبدأ بعد انتهاء المهلة المنصوص عليها في البند ) (2من هذه المادة .تودع هذه المبالغ في\n صندوق الخزينة أمانة لصالح لجنة البيع .\n ب -اعتبار المشتري مالكا للأموال المنقولة وغير المنقولة فور انتهاء المهلة المنصوص عليها في البند ) (2من هذه\n المادة ،وإعطاء المكلف مهلة شهر من تاريخ انتهاء المهلة المذآورة لإخلاء العقار في حال آان المكلف يشغله ،واستلام\n موجوداته .\n ‐2يحق للمكلف المنفذ عليه في خلال عشرة ايام من صدور قرار المزايدة النهائي ،أن يودع صندوق الخزينة مبلغا آافيا\n لإيفاء جميع الضرائب والمصاريف ،ويترتب على هذا الإيداع زوال قرار المزايدة النهائي ورفع الحجز .\n ‐3على الإدارة الضريبية ،بعد انقضاء المهلة المعينة في الفقرة السابقة ودفع المشتري الثمن والرسوم ،وبناء على تقرير\n لجنة البيع وتأآيدها إيداع الثمن أن تطلب تسجيل قرار المزايدة النهائي باسم المشتري أو باسم أي شخص يختاره في\n السجل العقاري أو في دفتر المختار أو في السجل الخاص المتعلق بالعقارات غير الخاضعة لنظام السجل العقاري أو في\n محضر التحديد والتحرير الكائن لدى القاضي العقاري .\n ‐4يترتب على التسجيل المنصوص عليه في الفقرة السابقة ،نقل الملكية بالنسبة للغير وترقين قيود الرهن والتأمين\n والامتياز المدونة على العقار لصالح الخزينة ."}, {"o": 61, "l": "المادة 79", "b": "‐5لا يقبل الاعتراض على قرار المزايدة النهائي ،إنما يقبل الاستئناف أمام مجلس شورى الدولة في خلال خمسة أيام من\n تاريخ صدوره للأسباب التالية :\n أ -وجود عيب جوهري في إجراءات المزايدة أو في صيغة القرار.\n ب -صدور القرار بالرغم من وجوب وقف تنفيذه .\n 28\n\f ج -مخالفة القانون في منازعة فرعية تناولها قرار الإحالة ،إذا آان من شأنها التأثير في صحة الإجراءات .\n حالة عدم تقدم مزايدين بالسعر المخمن لاموال مطروحة للبيع المادة ‐ 92\n ‐ 1إذا طرحت الأموال المحجوزة للبيع ولم يتقدم لها مزايدون بالسعر المخمن ،أعيد طرحها مرة ثانية في خلال مهلة\n ثلاثين يوما بعد تخفيض السعر المخمن بنسبة عشرة بالمئة )%).10\n ‐2وإذا لم تسفر المزايدة الثانية عن نتيجة ،أعيد طرحها مرة ثالثة بالشروط ذاتها وبعد تخفيض السعر المخمن بنسبة\n عشرة بالمئة ) (%10إضافية على السعر المخفض .\n ‐3وإذا لم تسفر المزايدة الأخيرة عن نتيجة :\nأ -تنقل ملكية العقارات على اسم الدولة بثمن الطرح الأخير ،وتسجل لدى الدوائر العقارية خلال مهلة عشرة أيام تبدأ بعد\n انتهاء المهلة المنصوص عليها في البند ) (2من"}, {"o": 62, "l": "المادة 91", "b": "المادة 91من هذا القانون .\n ب -تنقل ملكية الأموال المنقولة إلى الدولة بثمن الطرح الأخير ،وتتصرف بها وفقا للقوانين المرعية الاجراء .\n نقل ملكية العقار الى اسم الدولة المادة ‐ 93\n ‐ 1في حال نقل ملكية العقار إلى اسم الدولة ،وفقا للبند ) (3من"}, {"o": 63, "l": "المادة 92", "b": "المادة 92من هذا القانون ،يفتح بقيمة ثمنه وبقرار من\n وزير المالية اعتماد في الموازنة لتسديد المبالغ المتوجبة للخزينة ،ويدفع عند الاقتضاء ما يزيد عن هذه المبالغ لصاحب\n العقار .\n ‐2في حال انتقلت ملكية عقار أو عقارات إلى اسم الدولة بالطريقة المذآورة في البند الأول من هذه المادة ،فلا يمكن\n بيعها قبل مرور سنة على تسجيلها في السجل العقاري .\n ‐3يحق لمالك العقار المسجل على اسم الدولة ،أن يسترده في خلال سنة من تاريخ تسجيله ،شرط :\nأ -أن يسدد آامل الضرائب المتوجبة عليه مع فائدة تحسب بمعدل ) (%75،0شهريا من مجموع هذه المبالغ ويعتبر آسر\n الشهر شهرا آاملا .\n ب -أن يسدد الضريبة المترتبة على العقار عن المدة التي آان فيها مسجلا باسم الدولة .\n ج -أن يدفع إلى الخزينة المبالغ التي تكون قد أنفقتها على العقار خلال المدة المذآورة لأجل صيانته وتحسينه مع فائدة\n تحسب بمعدل ) (%75،0شهريا من مجموع هذه المبالغ ويعتبر آسر الشهر شهرا آاملا .\n وعلى الخزينة أن تعيد إلى صاحب العقار الريع الذي تكون قد استفادت منه خلال المدة التي آان مسجلا فيها على\n اسمها .\n تمنع المزايدة الاخير عن تنفيذ تعهده المادة ‐ 94\n ‐ 1إذا تمنع المزايد الأخير عن تنفيذ تعهده ،تصادر الكفالة المقدمة منه أو المبلغ المودع ،ويصار إلى إجراء مزايدة\n ثانية ،فإذا تساوى السعر الأفضل المقدم في المزايدة الثانية مع السعر الذي رست به المزايدة الأولى ،أو تجاوزه ،تعاد\n الكفالة المصادرة أو المبلغ المودع إلى صاحبها بعد أن تحسم منها نفقات المزايدة الثانية .\n ‐2وإذا جاء أفضل الأسعار المقدم في المزايدة الثانية أقل من السعر الذي رست به المزايدة الأولى ،فتستعمل الكفالة أو\n المبلغ المودع على التوالي لتغطية نفقات المزايدة الثانية والفرق بين السعرين ،وإذا زادت قيمة الكفالة أو المبلغ المودع"}, {"o": 64, "l": "المادة 92", "b": "عن النفقات والفرق ،يعاد الفرق الى المزايد صاحب الكفالة أو المبلغ المودع المصادرين .\n النفقات المادة ‐ 95\nيتحمل المكلف جميع نفقات الحجز والإعلان والخبرة والمزايدة ،وتحسم هذه النفقات من حاصل البيع قبل تسديد المبالغ\n 29\n\f المتوجبة للخزينة .\n توزيع الثمن المادة ‐ 96\n ‐ 1إذا آان الثمن المحصل من بيع الأموال المحجوزة آافيا لتسديد الضرائب المتوجبة والنفقات المتعلقة بالتحصيل\n الجبري ،فعلى الإدارة الضريبية أن تسدد ديونها خلال مهلة أقصاها عشرة أيام من تاريخ دفع الثمن وتسلم ما تبقى منه\n للمكلف المدين .\n ‐2إذا لم يكن الثمن آافيا لإيفاء حقوق الخزينة على وجه آامل ،لوحق المكلف المدين بالفرق .\n ‐3على الإدارة الضريبية أن تضع خلال عشرة أيام من تاريخ تسلمها الثمن مشروعا للتوزيع معتمدا ترتيب الأولوية\n على الوجه الآتي :\n أ -نفقات التنفيذ .\n ب -حقوق الخزينة المقترنة بحق الإمتياز مع مراعاة مراتب الديون على اختلافها .\n ج -المبلغ المتبقي للمكلف في حال وجوده .\n الفصل الثاني عشر\n الاعتراضات\n تقديم الاعتراض امام الادارة الضريبية المادة ‐ 97\n‐ 1يحق لكل صاحب علاقة أن يعترض على التكاليف بالضريبة والقرارات الضريبية الخاصة المتعلقة به إذا رأى فيها\n خطأ أو زيادة أو إجحافا بحقه أو مخالفة للقانون ،وذلك ضمن مهلة شهرين من تاريخ تبلغه التكليف أو القرار ،أو من\n تاريخ الدفع في حال لم تصدر الإدارة الضريبية المختصة قرارا بالدفع أو في حال قام المكلف بدفع الضريبة أو\n الغرامات قبل تبلغه هذا القرار ،وذلك تحت طائلة رد الاعتراض شكلا .\n ‐2يقدم الاعتراض أمام الإدارة الضريبية بموجب استدعاء خطي يوقعه صاحب العلاقة أو من ينوب عنه قانونا ،ويجب\n أن يضمن أسباب الاعتراض ومطالب المعترض مرفقا به نسخا عن المستندات التي تبرر هذا الاعتراض وإلا يرد\n الإعتراض شكلا .\n البت في الاعتراض من قبل الادارة الضريبية المادة ‐ 98"}, {"o": 65, "l": "المادة 92", "b": "‐ 1على الإدارة الضريبية أن تدرس جميع النقاط الواردة في الاعتراض وان تبت فيه خلال مهلة ستة أشهر من تاريخ\n استلامها الاعتراض .\n يحق للوحدة المختصة بدرس الاعتراض أن تقدم الى رئيس الإدارة الضريبية طلبا معللا لتمديد المهلة المذآورة في هذا\n البند ثلاثة أشهر إضافية ،وذلك لمرة واحدة فقط .\n ‐2يمكن أن يأتي قرار الإدارة الضريبية المختصة مخالفا أو مصدقا جزئيا أو آليا للقرار المعترض عليه .\nفي سياق درس الإعتراض ،يمكن أن تعيد الإدارة الضريبية النظر بالتكليف في حال اآتشاف وقائع أو عناصر جديدة أو\n مكتومة متعلقة بموضوع الإعتراض .\n‐3في حال مرور المهلة الأساسية والإضافية للبت في الاعتراض المنصوص عليها في البند ) (1من هذه المادة دون ان\n يصدر عن الإدارة الضريبية أي قرار بشأنه ،يعتبر عندها سكوتها بمثابة قرار ضمني بقبول الاعتراض.\n تبلغ نسخ عن القرارات الضمنية بالقبول الى مدير المالية العام لإتخاذ ما يلزم بحق المقصرين من موظفي إدارته عند\n الإقتضاء...\n ‐4يجب أن يكون البت بنتيجة درس الاعتراض خطيا ومعللا .\n 30\n\f حق الطعن بقرارات الادارة الضريبية المادة ‐ 99\n ‐ 1يجوز الطعن بقرارات الإدارة الضريبية الصادرة وفقا لأحكام المادتين 97و 98من هذا القانون والقاضية برد\n الاعتراض آليا أو جزئيا أمام المحكمة الإدارية خلال مهلة شهرين من تاريخ تبلغه قرار الإدارة الضريبية نتيجة درس\n الاعتراض وإلا يرد طلب الطعن شكلا .\n ‐2إلى حين إنشاء وتشكيل المحاآم الإدارية ،يجوز الطعن في قرارات الإدارة الضريبية أمام لجان الاعتراضات التي\nتنشأ وتشكل في آل محافظة بموجب مرسوم يتخذ في مجلس الوزراء بناء على اقتراح وزير المالية ووزير العدل ،وذلك\n وفقا للأصول المنصوص عليها في"}, {"o": 66, "l": "المادة 100", "b": "المادة 100وما يليها من هذا القانون .\n لجان الاعتراضات المادة ‐ 100\n ‐ 1تتألف آل من لجان الاعتراضات المنصوص عليها في"}, {"o": 67, "l": "المادة 99", "b": "المادة 99من هذا القانون من :\n ‐1قاض عامل أو قاض شرف عدلي أو إداري أو مالي من الدرجة الرابعة على الأقل )رئيسا ).\n ‐2مراقب ضرائب رئيسي من غير الوحدة المختصة بالتكليف )عضوا ).\n ‐3مندوب من غرفة التجارة والصناعة المختصة يختاره رئيس الغرفة المذآورة )عضوا ).\n ‐4موظف من الإدارة الضريبية التي قامت بدرس الاعتراضات أو قامت بالتكليف ينتمي الى الفئة الثالثة على الأقل\n مقررا لا يحق له التصويت .\n ويمكن للجنة الاستعانة بخبراء من اصحاب الاختصاص .\n تعتمد هذه اللجان الأصول المتبعة أمام القضاء المستعجل وتتخذ قراراتها بالأآثرية .\n ‐2يوضع تحت تصرف آل لجنة بصفة أمين سر ،مراقب ضرائب من الدائرة المختصة .\n ‐3على المقرر إبلاغ قرار اللجنة إلى الإدارة الضريبية وإلى المكلف خلال ثلاثين يوما من تاريخ صدوره .\n الاستئناف امام مجلس شورى الدولة المادة ‐ 101\n ‐ 1يحق لكل من المكلف والإدارة الضريبية استئناف قرار المحكمة الإدارية أو لجنة الاعتراضات أمام مجلس شورى\n الدولة وفقا لأصول المحاآمات لديه وذلك خلال مهلة شهر من تاريخ تبلغ القرار .وتعتبر هذه المهلة مهلة إسقاط بالنسبة\n إلى الإدارة الضريبية والمكلف على حد سواء .\n ‐2يتوقف قبول الاستئناف الذي يقدمه المكلف على إيداع تأمين يوازي خمسة بالمئة ) (%5من مقدار المبالغ المعترض\nعليها من ضريبة وغرامات باستثناء غرامة التأخير في الدفع .وآل طلب طعن غير مرفق بإيصال يثبت دفع التأمين يرد\n شكلا .\n عند صدور القرار النهائي ،في حال قبول الطلب ،يستعمل هذا التأمين لتسديد الضريبة المتوجبة ،ويعاد الرصيد الى\n المكلف في حال وجوده .\n في حال الرفض ،يصادر التأمين المسدد وفقا لاحكام هذه المادة .\n احكام مشترآة المادة ‐ 102\n ‐ 1يستمر سريان غرامة التأخير في تسديد الضريبة المنصوص عليها في"}, {"o": 68, "l": "المادة 55", "b": "المادة 55من هذا القانون طيلة مدة\n الاعتراض على أن لا تزيد تلك المدة عن إثني عشر شهرا من تاريخ تقديم الاعتراض أمام الإدارة الضريبية ضمن\n المهلة المنصوص عليها في المادة ، 97وإلا يتوقف سريان الغرامة المذآورة من تاريخ انتهاء هذه المدة.\n ‐2في حال القبول الجزئي أو الكلي للاعتراض من قبل الإدارة الضريبية أو المحاآم الإدارية أو لجان الاعتراضات أو\n 31\n\f مجلس شورى الدولة ،يحق للمكلف الذي سبق ودفع المبالغ المفروضة عليه الحصول :\n أ -على الرصيد المدفوع منه زيادة .\n ب -على الفائدة القانونية المتوجبة عن هذا الرصيد .\n الباب الرابع\n المخالفات والغرامات\n الفصل الاول\n احكام عامة\n زوال مسؤولية المكلف المادة ‐ 103\n ‐ 1تزول مسؤولية المكلف عن المخالفات الضريبية الحاصلة بسبب قوة قاهرة أو ظروف استثنائية عن الفترة\n الضريبية التي حصل خلالها سبب القوة القاهرة ،وذلك بالنسبة للغرامات المتعلقة بالمخالفات التالية :\n أ -التأخير في تقديم تصاريح مباشرة العمل وطلبات التسجيل إلى الإدارة الضريبية .\n ب -عدم إبراز السجلات القانونية والمستندات الثبوتية .\n ج -عدم تأدية الضرائب وعدم تقديم البيانات الدورية والتصاريح السنوية ضمن المهل القانونية .\n ‐2يتوجب على المكلف ،للاستفادة من أحكام البند الأول من هذه المادة ،إبلاغ الإدارة الضريبية بحالة القوة القاهرة أو\nالظروف الاستثنائية ضمن مهلة شهر واحد من تاريخ حصولها ،شرط إثباتها بمستندات صادرة عن جهات رسمية ،آما\n يتوجب عليه أيضا المبادرة إلى تصحيح وضعه الضريبي عن طريق إعادة تكوين سجلاته وتقديم التصاريح القانونية\n وتأدية الضرائب والرسوم المتوجبة عليه خلال مهلة شهرين من تاريخ زوال القوة القاهرة أو الظروف الاستثنائية .\n غرامات القوانين الضريبية المادة ‐ 104\n تلغى الغرامات المنصوص عليها في القوانين الضريبية وتستبدل بالغرامات المنصوص عليها في هذا القانون ."}, {"o": 69, "l": "المادة 55", "b": "الغرامة على فرق الضريبة المادة‐ 105\n عند حصول مخالفة تتناول مستندا أو عدة مستندات مشترآة بين عدة ضرائب ،تنفذ الغرامة الأعلى على فرق\n الضريبة .تحدد دقائق تطبيق هذه المادة بقرار يصدر عن وزير المالية .\n المخالفات المالية الجزائية المادة ‐ 106\nتلاحق المخالفات المالية الجزائية وفقا لأحكام المرسوم الاشتراعي رقم 156تاريخ 1983/9/16وتعديلاته ،وتفرض\nالعقوبات المتوجبة عليها من قبل المحاآم بناء على طلب وزارة المالية دون ما حاجة إلى سبق إخطار المكلف لتصحيح\n تصريحه .\n 32\n\f الفصل الثاني\n الغرامات\n الجزء الاول\n الغرامات بصورة عامة\n التأخر او عدم تقديم طلب التسجيل المادة ‐ 107\n‐ 1تفرض على آل شخص لم يقدم طلب تسجيله لدى الإدارة الضريبية ضمن المهل القانونية ،آما هو منصوص عليه\n في البند واحد من"}, {"o": 70, "l": "المادة 32", "b": "المادة 32من هذا القانون ،أو في القوانين الضريبية ،غرامة قدرها :\n ‐ 2.000.000ل.ل) .مليونا ليرة لبنانية( للشرآات المساهمة .\n ‐ 1.000.000ل.ل).مليون ليرة لبنانية( لشرآات الأشخاص والشرآات المحدودة المسؤولية وللمؤسسات المستثناة من\n الضريبة .\n ‐ 300.000ل.ل) .ثلاثمائة الف ليرة لبنانية( للأفراد ولباقي المكلفين.\n ‐2تفرض على آل شخص لم يبلغ الإدارة الضريبية عن أي تعديل بالمعلومات المنصوص عليها في البند الثاني من"}, {"o": 71, "l": "المادة 32", "b": "المادة 32من هذا القانون ،غرامة قدرها :\n ‐ 200.000ل.ل) .مئتا الف ليرة لبنانية( للشرآات المساهمة.\n ‐100.000ل.ل) .مئة الف ليرة لبنانية( لشرآات الأشخاص والشرآات المحدودة المسؤولية وللمؤسسات المستثناة من\n الضريبة .\n ‐ 50.000ل.ل) .خمسون الف ليرة لبنانية( للأفراد ولباقي المكلفين .\n إذا آانت التعديلات المبينة في البند 2من"}, {"o": 72, "l": "المادة 32", "b": "المادة 32من هذا القانون تتعلق بعدة ضرائب ،تطبق الغرامة مرة واحدة .\n التأخر او عدم التصريح عن التوقف النهائي عن العمل المادة ‐ 108\nتفرض على آل شخص لم يبلغ الإدارة الضريبية عن توقفه النهائي عن العمل ضمن المهل القانونية آما هو منصوص\n عليه في"}, {"o": 73, "l": "المادة 33", "b": "المادة 33من هذا القانون ،وفي القوانين الضريبية ،غرامة قدرها :\n ‐ 2.000.000ل.ل) .مليونا ليرة لبنانية( للشرآات المساهمة .\n‐ 1.000.000ل.ل) .مليون ليرة لبنانية )لشرآات الأشخاص والشرآات المحدودة المسؤولية وللمؤسسات المستثناة من\n الضريبة.\n ‐ 300.000ل.ل) .ثلاثماية الف ليرة لبنانية )للأفراد ولباقي المكلفين .\n التأخر او عدم تقديم التصريح الضريبي المادة ‐ 109\n تفرض على آل مكلف لم يقدم التصريح المنصوص عليه في البند واحد من"}, {"o": 74, "l": "المادة 38", "b": "المادة 38من هذا القانون ،غرامة قدرها\n خمسة بالمئة ) (%5من قيمة الضريبة المتوجبة وفقا للتصريح أو للربح المحدد من قبل الإدارة الضريبية عن آل شهر\n تأخير )أو آسر الشهر( على أن لا تتجاوز الغرامة مئة بالمئة ) (%100من قيمة الضريبة المتوجبة عن آل تصريح،\n ولا تقل عن :\n ‐ 750.000ل.ل) .سبعماية وخمسون الف ليرة لبنانية( للشرآات المساهمة .\n‐ 500.000ل.ل) .خمسماية الف ليرة لبنانية( لشرآات الاشخاص والشرآات المحدودة المسؤولية وللمؤسسات المستثناة\n من الضريبة .\n ( ‐ 100.000مئة الف ليرة لبنانية )للأفراد ولباقي المكلفين .\n 33\n\f التصاريح الضريبية غير الصحيحة المادة ‐ 110\n تفرض على آل شخص يصرح بأقل من الضريبة الواجب التصريح عنها ،غرامة قدرها عشرين بالمئة ) (%20من\n قيمة الفرق بين الضريبة الصافية المتوجبة والضريبة الصافية المصرح عنها ،على أن لا تقل الغرامة عن :\n ‐ 750.000ل.ل) .سبعماية وخمسون الف ليرة لبنانية( للشرآات المساهمة .\n ‐ 500.000ل.ل).خمسماية الف ليرة لبنانية( لشرآات الأشخاص والشرآات المحدودة المسؤولية وللمؤسسات المستثناة\n من الضريبة .\n ‐ 100.000ل.ل) .مائة الف ليرة لبنانية( للأفراد ولباقي المكلفين .\n الاغفال عن التصريح بمعلومات المادة ‐ 111\nتفرض ،على آل شخص أغفل عن التصريح بمعلومات عند تعبئة التصاريح والبيانات الواجب تقديمها وفقا لأحكام هذا\n القانون والقوانين الضريبية الخاصة ،ولم ينتج عن هذا الإغفال ضريبة إضافية غرامة قدرها عن آل تصريح :\n ‐ 200.000ل.ل) .مئتا الف ليرة لبنانية( للشرآات المساهمة .\n ‐100.000ل.ل) .مئة الف ليرة لبنانية( لشرآات الأشخاص والشرآات المحدودة المسؤولية وللمؤسسات المستثناة من\n الضريبة .\n ‐ 50.000ل.ل) .خمسون الف ليرة لبنانية( للأفراد ولباقي المكلفين .\n الاغفال عن تقديم تقرير مفوض المراقبة المادة ‐ 112"}, {"o": 75, "l": "المادة 38", "b": "تفرض على شخص لم يقدم تقرير مفوض المراقبة وفقا لأحكام القوانين الضريبية الغرامة المتعلقة بعدم تقديم أو التأخر\n عن تقديم التصريح المنصوص عليها في"}, {"o": 76, "l": "المادة 109", "b": "المادة 109من هذا القانون .\n المخالفات المتعلقة بالفواتير المادة ‐ 113\n ‐ 1تفرض على آل مكلف لم يصدر فاتورة متى آان ذلك إلزاميا وفقا للقانون ،غرامة قدرها إثنان بالمئة ) (%2من\n قيمة العملية موضوع الفاتورة .\n ‐2تفرض على آل مكلف لم يظهر على الفواتير أو المستندات المماثلة التي يكون ملزما قانونا بإصدارها ،رقمه\n الضريبي أو غيرها من المعلومات الشكلية التي لا تؤثر على التحقق من صحة الضريبة المتوجبة ،غرامة قدرها 0،5%\n من قيمة العملية موضوع الفاتورة .\n عدم مسك السجلات والمستندات المحاسبية المادة ‐ 114\n تفرض على آل من لم يمسك السجلات والمستندات المحاسبية المنصوص عليها في"}, {"o": 77, "l": "المادة 29", "b": "المادة 29من هذا القانون أو في\nالقوانين الضريبية ،غرامة قدرها خمسون بالمئة ) (%50من الضريبة الصافية غير المصرح عنها ،على أن لا تقل عن :\n ‐750.000ل.ل) .سبعماية وخمسون الف ليرة لبنانية( للشرآات المساهمة،\n‐ 500.000ل.ل) .خمسماية الف ليرة لبنانية( لشرآات الأشخاص والشرآات المحدودة المسؤولية وللمؤسسات المستثناة\n من الضريبة،\n ‐ 100.000ل.ل) .مئة الف اليرة لبنانية( للأفراد ولباقي المكلفين .\n 34\n\f عرقلة اجراءات المراقبة الضريبية المادة ‐ 115\n تفرض على آل من يمتنع عن ابراز السجلات أو المستندات المثبتة لصحة التصريح ،أو الامتناع عن تدوين بعض\n العمليات عليها وفقا للاصول ،غرامة قدرها خمسون بالمئة ) (%50من قيمة الضريبة المتوجبة غير المدفوعة على أن\n لا تقل عن :\n ‐ 750.000ل.ل) .سبعماية وخمسون الف ليرة لبنانية( للشرآات المساهمة.\n‐ 500.000ل.ل) .خمسماية الف ليرة لبنانية )لشرآات الأشخاص والشرآات المحدودة المسؤولية وللمؤسسات المستثناة\n من الضريبة .\n ‐ 100.000ل.ل) .مئة الف ليرة لبنانية( للأفراد ولباقي المكلفين .\n مسؤولية الاشخاص المنوطة بهم مهمة اقتطاع الضريبة المتوجبة والتصريح عنها المادة ‐ 116\n تفرض على آل من أغفل اقتطاع الضريبة والتصريح عنها ،أو من خالف أحكام البند ) (4من"}, {"o": 78, "l": "المادة 14", "b": "المادة 14من هذا\n القانون ،غرامة قدرها خمسة بالمئة ) (%5من قيمة الضريبة المتوجبة عن آل شهر تأخير على أن لا تتجاوز مقدار\n الضريبة وأن لا تقل عن :\n ‐ 750.000ل.ل) .سبعماية وخمسون الف ليرة لبنانية )للشرآات المساهمة .\n‐ 500.000ل.ل) .خمسماية الف ليرة لبنانية( لشرآات الأشخاص والشرآات المحدودة المسؤولية وللمؤسسات المستثناة\n من الضريبة .\n ‐ 100.000ل.ل( .مئة الف ليرة لبنانية( للأفراد ولباقي المكلفين .\n منع تنفيذ اجراءات التحصيل الجبري المادة ‐ 117\n تفرض غرامة قدرها خمسة بالمئة ) (%5شهريا من قيمة الضريبة المطلوب تحصيلها جبريا على المكلف أو أي\nشخص آخر يحول دون تمكين الإدارة الضريبية من القيام بتنفيذ إجراءات التحصيل الجبري المنصوص عليها في الفصل\n الحادي عشر من الباب الثالث من هذا القانون ،على أن لا تتجاوز مقدار الضريبة المطلوب تحصيلها وأن لا تقل عن :\n ‐ 750.000ل.ل) .سبعماية وخمسون الف ليرة لبنانية( للشرآات المساهمة .\n‐ 500.000ل.ل) .خمسماية الف ليرة لبنانية( لشرآات الاشخاص والشرآات المحدودة المسؤولية وللمؤسسات المستثناة\n من الضريبة .\n ‐ 100.000ل.ل) .مئة الف ليرة لبنانية )للأفراد ولباقي المكلفين .\n 35\n\f الجزء الثاني\n الغرامات الخاصة\n ‐1المخالفات والغرامات المنصوص عليها في\n القانون الصادر بتاريخ 1962/9/17\n )قانون الاملاك المبنية(\n التأخر او عدم تقديم التصريح عن تأجير دور السكن القائم في مناطق الاصطياف المادة ‐ 118\n تفرض على آل من يخالف أحكام"}, {"o": 79, "l": "المادة 19", "b": "المادة 19من قانون الأملاك المبنية المتعلقة بالتصريح عن تأجير دور السكن القائم\n في مناطق الاصطياف في موسم الاصطياف غرامة قدرها خمسة بالمئة )%) 5من قيمة الضريبة المتوجبة على\nالإيرادات الحاصلة خلال فترة التأجير المذآورة ،على أن لا تقل الغرامة عن 200.000ل.ل) .مئتي الف ليرة لبنانية ).\n التأخر او عدم تقديم التصريح عن التغيير الحاصل على البناء المادة ‐ 119\n تفرض على آل من يخالف أحكام"}, {"o": 80, "l": "المادة 23", "b": "المادة 23من قانون الأملاك المبنية المتعلقة بإعلام الإدارة الضريبية المختصة عن\n آل ما يطرأ على الأبنية )تغيير وجهة استعمالها ،إشغالها أو تأجيرها ،الخ( ،غرامة قدرها خمسة بالمئة ) (%5من قيمة\n الضريبة السنوية المتوجبة عن آل سنة مع اعتبار آسور السنة سنة آاملة .\n عدم تسجيل العقود او تسجيل عقدا صوريا المادة ‐ 120\n‐ يعاقب آل من خالف أحكام قانون الأملاك المبنية المتعلقة بتسجيل العقود بغرامة تعادل خمسة بالمئة ) (5%من مقدار\n الضريبة السنوية المتوجبة عن آل سنة تستمر فيها المخالفة مع اعتبار آسور السنة سنة آاملة .\n‐يعاقب آل من خالف أحكام قانون الأملاك المبنية المتعلقة بتسجيل العقود الصورية بغرامة تعادل عشرة بالمئة )(%10\n من مقدار الضريبة السنوية المتوجبة عن آل سنة تستمر فيها المخالفة مع اعتبار آسور السنة سنة آاملة .\n التأخر او عدم التصريح عن نشوء الحق بالضريبة المادة ‐ 121\n تفرض على آل من خالف أحكام"}, {"o": 81, "l": "المادة 50", "b": "المادة 50من قانون الأملاك المبنية المتعلقة بالتصريح عن نشوء الحق بالضريبة\n )إنجاز الأبنية أو أقسامها ،إعادة التأجير ،التحوير والترميم ،زوال أسباب الإعفاء( غرامة قدرها عشرة بالمئة )(%10\n من قيمة الضريبة السنوية المتوجبة عن آل سنة تستمر فيها المخالفة مع اعتبار آسور السنة سنة آاملة .\n ‐2الغرامات الخاصة بالمرسوم الاشتراعي رقم 144تاريخ ) 1959/6/12قانون ضريبة الدخل(\n 36\n\f عدم اتمام المؤسسة لعملية التوظيف التي خصص جزء من الارباح من اجلها المادة ‐ 122\n تفرض ،في حال مخالفة أحكام الفقرة ) (5من البند\" أولا\" من"}, {"o": 82, "l": "المادة 5", "b": "المادة 5مكرر من قانون ضريبة الدخل المتعلقة بعدم\n توظيف المبالغ المقتطعة من الأرباح أو الإخلال بأي من الشروط المحددة للاستفادة من الإعفاء ،غرامة قدرها واحد\n بالمئة ) (%1من قيمة المبالغ المقتطعة غير الموظفة عن آل شهر على أن يعتبر آسر الشهر شهرا آاملا ،وذلك ابتداء\n من السنة اللاحقة لسنة الأعمال التي جرى اقتطاع تلك المبالغ من أرباحها .\n عدم مسك سجل الاجراء او رفض اطلاع الادارة الضريبية عليه المادة ‐ 123\n تفرض على من لا يمسك سجل الأجراء وفقا لأحكام"}, {"o": 83, "l": "المادة 51", "b": "المادة 51من قانون ضريبة الدخل ،أو يرفض اطلاع الإدارة\n الضريبية عليه ،غرامة قدرها 25.000ل.ل) .خمسة وعشرون الف ليرة لبنانية( عن آل اسم أهمل تدوينه في هذا\n السجل .\n عدم تسجيل الاجراء لدى الادارة الضريبية ضمن المهل القانونية المادة ‐ 124\n تفرض عن آل مخالفة للأحكام المتعلقة بموجب تسجيل الأجراء لدى الإدارة الضريبية ،غرامة مقطوعة قدرها\nخمسون الف ليرة لبنانية عن آل مستخدم أو أجير لا يتم تسجيله خلال المهل المحددة ،أو إعطاء معلومات خاطئة عنه .\n عدم تنظيم البيان الدوري بالرواتب والاجور وعدم تقديمه للادارة الضريبية المادة ‐ 125\nتفرض على المخالف لأحكام الفقرة )) 5من"}, {"o": 84, "l": "المادة 63", "b": "المادة 63من قانون ضريبة الدخل المتعلقة بتنظيم البيان الدوري بالرواتب\nوالأجور وتقديمه إلى الإدارة الضريبية المختصة ضمن المهلة القانونية المحددة لكل من الدفعات الدورية ،غرامة قدرها\nخمسة بالمئة ) (%5من قيمة الضريبة المتوجبة على أن لا تتجاوز هذه الغرامة 1.000.000ل.ل) .مليون ليرة لبنانية(\n وأن لا تقل عن 100.000ل.ل) .مئة ألف ليرة لبنانية( عن آل فترة لم يقدم البيان الدوري العائد لها .\n عدم تطابق التصريح المقدم الى الادارة الضريبية مع التصريح المقدم الى الصندوق الوطني المادة ‐ 126\n للضمان الاجتماعي\n تفرض عند مخالفة أحكام"}, {"o": 85, "l": "المادة 52", "b": "المادة 52من قانون ضريبة الدخل لجهة عدم تطابق التصريح المقدم من قبل صاحب العمل\n الى الإدارة الضريبية مع التصريح المقدم منه إلى الصندوق الوطني للضمان الاجتماعي فيما يتعلق بأسماء المستخدمين\n ومجموع الرواتب والأجور والتعويضات المدفوعة لهم غرامة قدرها 200.000ل.ل) .مئتا الف ليرة لبنانية( عن آل\n تصريح .\n عدم تنظيم الجداول بالقسائم والاوراق المالية المادة ‐ 127\nتفرض على الشخص الذي لم ينظم الجداول بالقسائم أو الأوراق المالية وفقا لأحكام"}, {"o": 86, "l": "المادة 79", "b": "المادة 79من قانون ضريبة الدخل،\n غرامة قدرها 300.000ل.ل( .ثلاثماية الف ليرة لبنانية ).\n عدم مسك السجلين العائدين لدفع او بيع او شراء القسائم او غيرها من الاوراق المالية المادة ‐ 128\n 37\n\f تفرض ،في حال عدم مسك السجلين المنصوص عليهما في"}, {"o": 87, "l": "المادة 80", "b": "المادة 80من قانون ضريبة الدخل والمتعلقين بتسجيل\n معاملات دفع أو بيع أو شراء القسائم أو غيرها من الأوراق المالية الواجب اقتطاع الضريبة عنها ،غرامة توازي\n 300.000ل.ل) .ثلاثماية الف ليرة لبنانية ).\n عدم تنظيم خلاصة عن السجل رقم 1وعدم تسديد الضريبة المقتطعة المادة ‐ 129\nتفرض على مقتطع الضريبة الذي يخالف أحكام"}, {"o": 88, "l": "المادة 81", "b": "المادة 81من قانون ضريبة الدخل المتعلقة بتنظيم خلاصة عن السجل\nرقم ،1غرامة قدرها 000،300ل.ل) .ثلاثماية الف ليرة لبنانية( .وفي حال التأخر عن تسديد الضريبة المقتطعة ضمن\nالمهل القانونية تفرض غرامة التأخير بالدفع على المبالغ غير المسددة المنصوص عليها في"}, {"o": 89, "l": "المادة 55", "b": "المادة 55من هذا القانون .\n ‐3الغرامات الخاصة بالمرسوم الاشتراعي رقم 146تاريخ ) 1959/6/12قانون رسم الانتقال)\n تسليم المدين للترآة ما في حوزته خلافا لاحكام القانون المادة ‐ 130\n إذا سلم أحد المدينين لترآة شيئا مما في حوزته خلافا لأحكام"}, {"o": 90, "l": "المادة 25", "b": "المادة 25من قانون رسم الانتقال عد مسؤولا تجاه\n الخزينة على الرسم المترتب على ما تخلى عنه .وإذا آانت الشرآة غير خاضعة لرسم الانتقال فرضت على المخالف\n غرامة مقدارها 150.000ل.ل) .مئة وخمسون الف ليرة لبنانية ).\n مخالفة اصول فتح الخزائن او الصناديق المادة ‐ 131\n يعتبر المخالف لأحكام"}, {"o": 91, "l": "المادة 28", "b": "المادة 28من قانون رسم الانتقال المتعلقة بأصول فتح الخزائن أو الصناديق المؤجرة بعد وفاة\n المستأجر ،مسؤولا تجاه الخزينة عن الرسم المترتب على الأموال المودعة في تلك الخزائن أو الصناديق .\n التأخر او عدم تقديم دائن الترآة بيانا بمقدار الدين المادة ‐ 132\n إذا لم يقدم دائن الترآة بيانا بمقدار الدين المنصوص عليه في"}, {"o": 92, "l": "المادة 29", "b": "المادة 29من قانون رسم الانتقال ضمن المهلة المحددة\n فرضت عليه غرامة تعادل قيمة الرسم الذي قد يترتب على الورثة بسبب عدم حسم هذا الدين من أساس الترآة .\n وإذا آانت الترآة غير خاضعة لرسم الانتقال فرضت على الدائن المخالف غرامة مقدارها 200.000ل.ل) .مئتا الف\n ليرة لبنانية ).\n تحرير الترآات دون حضور مندوب عن الدوائر المالية المختصة المادة ‐ 133\n في حال جرى تحرير الترآات دون حضور مندوب عن الدوائر المالية المختصة خلافا لأحكام"}, {"o": 93, "l": "المادة 30", "b": "المادة 30من قانون\nرسم الانتقال ،يحق للدوائر المالية المختصة أن تعمد إلى إعادة تحرير أية ترآة أو فرض غرامة على المحرر المخالف\n تعادل قيمة الرسم الذي قد يترتب على الفرق بين التحريرين .\nوإذا آانت الترآة غير خاضعة لرسم الانتقال فرضت على المحرر المخالف غرامة مقدارها 200.000ل.ل) .مئتا الف\n ليرة لبنانية ).\n 38\n\f التأخر او عدم تقديم التصاريح ومرفقاتها او تقديم باقي المستندات المادة ‐ 134\n في حال لم يقدم أصحاب العلاقة التصريح ومرفقاته أو التصريح عن باقي المستندات ضمن المهل المحددة في"}, {"o": 94, "l": "المادة 21", "b": "المادة\n 21من قانون رسم الانتقال ،عوقبوا بغرامة تعادل ثلاثة بالمئة ) (%3عن مخالفة عدم التصريح أو التأخير بتقديمه\n وإثنان بالمئة ) (%2عن مخالفة عدم تقديم المستندات أو التأخير بتقديمها عن آل شهر تأخير أو آسر الشهر ،من قيمة\n الرسم الذي يترتب على الأموال أو الحقوق أو القيم غير المصرح عنها ضمن المهل المحددة ،على أن لا تتعدى الغرامة\n عن آل من هاتين المخالفتين قيمة خسمين بالمئة ) (%50من الرسم الذي تفرض على أساسه وان لا تقل حتى ولو لم\n يترتب أي رسم عن مئة الف ليرة ،عن آل من هاتين المخالفتين لكل واقعة بما فيها الواقعات الحاصلة قبل صدور هذا\n القانون والتي لم يتم تصفية الرسم المتوجب عليها .\n ‐4الغرامات الخاصة المتعلقة بالمرسوم الاشتراعي رقم 67تاريخ ) 1967/8/5قانون رسم الطابع المالي)"}, {"o": 95, "l": "المادة 135", "b": "المادة135\n يفرض على آل من يرتكب أيا من المخالفات التالية غرامة تعادل خمسة أضعاف الرسم أو الجزء من الرسم الذي\n تعرضت الخزينة لخسارته من جراء المخالفة :\n ‐1عدم إلصاق طوابع بقيمة الرسم المتوجب أو إلصاق طوابع تقل قيمتها عن قيمة الرسم المتوجب .\n ‐2عدم وضع وسمة بقيمة الرسم المتوجب أو وضع وسمة تقل قيمتها عن قيمة الرسم المتوجب .\n ‐3عدم استيفاء وإخفاء قسم من الرسم الذي يتوجب على المؤسسات الخاضعة لطريقة التأدية الدورية استيفاؤه من\n أصحاب العلاقة أو إخفاء ما استوفي منه فعلا ،آليا أو جزئيا ،وعدم التصريح عنه للدائرة المالية المختصة لدى تأدية\n حاصل الرسم المذآور إلى صندوق الخزينة .\n اهمال تعطيل الطوابع الملصقة على الصكوك والكتابات المادة ‐ 136\n يفرض على آل من يهمل تعطيل الطوابع الملصقة على الصكوك والكتابات أو يعطلها بصورة مخالفة لأحكام"}, {"o": 96, "l": "المادة 25", "b": "المادة\n 25من قانون رسم الطابع المالي غرامة قدرها خمسون بالمئة ) (%50من قيمة الطوابع غير المعطلة أو المعطلة\n بصورة غير قانونية .\n التأخر في تأدية الرسم نقدا الى صندوق الخزينة المادة ‐ 137\nيفرض على آل من يتأخر في تأدية الرسم نقدا الى صندوق الخزينة إلى ما بعد المهلة المحددة ،وذلك آلما آانت تأديته\n على هذا الشكل مفروضة بمقتضى قانون رسم الطابع المالي ،غرامة تعادل خمسة أضعاف الرسم المذآور .\n التأخر او عدم مسك السجلات القانونية المادة ‐ 138\n ‐ 1تفرض في حال التأخر أو عدم مسك السجل المنصوص عليه في"}, {"o": 97, "l": "المادة 32", "b": "المادة 32من قانون رسم الطابع المالي وآذلك\nالسجل المنصوص عليه في"}, {"o": 98, "l": "المادة 52", "b": "المادة 52من قانون رسم الطابع المالي غرامة قدرها خمسون بالمئة ) (%50من قيمة الرسم\n المتوجب نتيجة تلك المخالفة .\n ‐2تفرض في حال عدم تدوين المعلومات التي يفرض القانون تدوينها في السجلات المذآورة في البند الأول من هذه\n المادة ،غرامة مقطوعة قدرها 250.000ل.ل) .مئتان وخمسون الف ليرة لبنانية( .\n 39\n\f بيع الطوابع المالية دون ترخيص المادة ‐ 139\n تفرض على آل من يبيع الطوابع المالية دون ترخيص ،غرامة قدرها 250.000ل.ل) .مئتان وخمسون الف ليرة\n لبنانية( ،وتصادر الطوابع الموضوعة برسم البيع وتصبح حقا مكتسبا للخزينة دون أن يكون لصاحب العلاقة أي حق\n بالبدل أو التعويض .\n لوزير المالية أن يقرر إقفال المحل ،عندما تحصل المخالفة في محل غير مجاز ،لمدة تتراوح بين ثلاثة أيام وشهر واحد\n إذا تكررت المخالفة في غضون ثلاث سنوات .\n تشويه الوسمة الى حد جعل قيمتها مجهولة المادة ‐ 140\n يفرض على آل من يكتب على الوسمة أو يضع عليها أي طبع أو آتابة أو رسم أو إشارة من أي نوع آان مما يؤدي\n الى عدم معرفة قيمتها ،غرامة مقطوعة قدرها 250.000ل.ل) .مئتان وخمسون الف ليرة لبنانية ).\n مخالفة الاحكام المتعلقة بالترخيص بصنع الآلات الواسمة واستيرادها وبيعها المادة ‐ 141\n يفرض على آل من يخالف أحكام"}, {"o": 99, "l": "المادة 38", "b": "المادة 38من قانون رسم الطابع المالي المتعلقة بالترخيص بصنع الآلات الواسمة\n واستيرادها وبيعها والاتجار بها ،غرامة قدرها 250.000ل.ل) .مئتان وخمسون الف ليرة لبنانية( ،وتصادر الآلات\n الواسمة المخالفة وتصبح حقا مكتسبا للخزينة دون أن يكون لصاحب العلاقة أي حق بالبدل أو التعويض .\n اساءة استعمال الآلات الواسمة وارتكاب المخالفات المادة ‐ 142\n يلغى الترخيص باستعمال الآلة الواسمة ،دون أن يكون لصاحب العلاقة أي حق بالتعويض ،إذا أساء المرخص له\n استعمال الآلة المذآورة أو ارتكب إحدى المخالفات أو الإساءات المنصوص عليها في"}, {"o": 100, "l": "المادة 31", "b": "المادة 31أو أهمل التقيد\n بأحكام المواد 32و 34و 35من قانون رسم الطابع المالي .\n عدم الاحتفاظ بالصكوك والكتابات الخاضعة للرسم طيلة المدة القانونية المادة ‐ 143\nيفرض على آل من لم يحتفظ بالصكوك والكتابات الخاضعة للرسم طيلة مدة الحفظ المنصوص عليها في"}, {"o": 101, "l": "المادة 99", "b": "المادة 99من\n قانون رسم الطابع المالي ،غرامة مقطوعة قدرها 500.000ل.ل) .خمسماية الف ليرة لبنانية( .\n استعمال ،بيع او محاولة بيع ،عن علم مسبق ،طوابع مالية سبق استعمالها المادة ‐ 144\n يعاقب آل من استعمل عن علم سابق أو باع أو حاول أن يبيع طوابع مالية سبق استعمالها ،بالسجن من خمسة عشر\n يوما إلى شهرين وبغرامة قدرها 250.000ل.ل) .مئتان وخمسون الف ليرة لبنانية( أو بإحدى هاتين العقوبتين .\n تقليد الوسمة الخاصة التي توضع في الآلات الواسمة المادة ‐ 145\nيلاحق وفقا لأحكام المادتين 450و 451من قانون العقوبات ،آل من قلد أو حاول أن يقلد الوسمة الخاصة التي توضع\n في الآلات الواسمة المنصوص عليها في"}, {"o": 102, "l": "المادة 40", "b": "المادة 40من قانون رسم الطابع المالي وآذلك آل من قلد أو حاول أن يقلد\n دمغة تلك الوسمة .\n 40\n\f تقليد او تزوير الطوابع المالية او استعمال طوابع مالية مزورة او مقلدة عن سابق علم المادة ‐ 146\n يلاحق وفقا لأحكام المادتين 450و 451من قانون العقوبات آل من قلد أو زور أو حاول أن يقلد أو يزور الطوابع\n المالية أو استعمال الطوابع المقلدة أو المزورة عن علم سابق .\n تدوين معلومات آاذبة او مغلوطة او اغفال تدوين معلومات صحيحة في السجلات المادة ‐ 147\n يلاحق وفقا لأحكام المادتين 461و 462من قانون العقوبات آل من دون في السجل المنصوص عليه في"}, {"o": 103, "l": "المادة 32", "b": "المادة 32أو\n في"}, {"o": 104, "l": "المادة 52", "b": "المادة 52من قانون رسم الطابع المالي معلومات آاذبة أو مغلوطة أو أغفل تدوين معلومات صحيحة آان ينبغي\n تدوينها .\n منع بالقوة او محاولة منع الموظفين المكلفين بضبط المخالفات من القيام بأعمالهم او معاملتهم المادة ‐ 148\n بعنف او بشدة او التعرض لهم بالتحقير والقدح والذم\n يلاحق وفقا لأحكام المواد 381وما يليها من قانون العقوبات آل من منع بالقوة أو حاول منع الموظفين المكلفين\nبضبط مخالفات قانون رسم الطابع المالي من القيام بأعباء وظيفتهم أو عاملهم بالعنف أو الشدة أو تعرض لهم بالتحقير أو\n القدح أو الذم بأي شكل آان .\n ‐5الغرامات الخاصة بالقانون رقم 379تاريخ( 14/12/2001قانون الضريبة على القيمة المضافة)\n اصدار فاتورة دون وجه حق المادة ‐ 149\n آل شخص غير مسجل لدى الضريبة على القيمة المضافة يصدر فاتورة من غير حق ،يعاقب بغرامة توازي ثلاثة\n أضعاف الضريبة المدونة على تلك الفاتورة .\n اصدار فاتورة مخالفة للقانون المادة ‐ 150\n تفرض على آل شخص خاضع للضريبة على القيمة المضافة يصدر فاتورة أو مستند مماثل مخالفا لأحكام"}, {"o": 105, "l": "المادة 38", "b": "المادة\n 38من قانون الضريبة على القيمة المضافة لجهة ذآر الضريبة المتوجبة أو وصف العملية غرامة قدرها خمسة\n وعشرون ) (%25من الضريبة المتوجبة على العملية موضوع الفاتورة .\n المخالفات المتعلقة بالاستيراد والتصدير المادة ‐ 151\n يجري في عمليات استيراد وتصدير السلع التحقق من المخالفات لأحكام قانون الضريبة على القيمة المضافة وضبطها\n وتحصيلها وتسويتها وفقا لأحكام المنصوص عليها في التشريع الجمرآي .\n 41\n\f الباب الخامس\n احكام انتقالية وختامية\n اعفاء من رسوم الطوابع المالية المادة ‐ 152\nتعفى من رسوم الطوابع الأميرية التصاريح والاعتراضات والبيانات وسوى ذلك من الأوراق والمستندات المنصوص\n عليها في هذا القانون أو في القوانين الضريبية ،التي تقدم إلى مختلف الإدارات العامة .\n تخفيض الغرامات المادة ‐ 153\n عدل نص المادة ،153بموجب"}, {"o": 106, "l": "المادة 2", "b": "المادة 2من القانون رقم 54تاريخ 2008/12/27واصبح على الوجه التالي:\n خلافا لأي نص آخر ،تخفض بنسبة تسعين بالمئة ) (%90جميع الغرامات المتوجبة على الضرائب والرسوم التي\n تحققها وتحصلها مديرية المالية العامة الصادرة أو التي ستصدر أو التي يتم التصريح عنها وتسديد الضريبة المتوجبة\n وفقا لنظام الدفع المسبق ،الناتجة عن مخالفات حاصلة خلال الفترة الممتدة لغاية تاريخ نشر هذا القانون ،شرط ان تسدد\n الضرائب والرسوم والغرامات المخفضة في مهلة اقصاها ، 2009/4/30على ان تسري الفائدة شهرية بنسبة % 5،1\n ابتداء من ،2009/2/1ولغاية تاريخ التسديد مع اعتبار آسر الشهر شهرا آاملا .\n تعتبر الغرامات المسددة قبل العمل بهذا القانون حقا مكتسبا للخزينة ولا يمكن استردادها إلا اذا آانت نتيجة خطأ مادي\n في التكليف .\n المبالغ الهالكة المادة ‐ 154\n تعتبر هالكة المبالغ المتوجبة على المكلفين بالضريبة بما فيها الغرامات اللاحقة بها التي لا تتجاوز قيمتها 20.000\n ل.ل) .عشرون الف ليرة لبنانية( ،عن آل فترة ضريبية وتعفى الوحدات المالية المختصة من إصدار جداول تكليف أو\n أوامر قبض أو إشعارات دفع بتلك المبالغ وتحصيلها .\n احكام القوانين الاخرى الملغاة المادة ‐ 155\n تلغى اعتبارا من تاريخ نفاذ هذا القانون ،جميع النصوص القانونية المخالفة له أو التي لا تتفق مع مضمونه ،سواء\n آانت عامة أو خاصة .\n دقائق تطبيق القانون المادة ‐ 156\nتحدد دقائق تطبيق هذا القانون ،فيما يتعلق بالمواد التي لم تلحظ المرجع المختص لتحديد دقائق تطبيقها ،بمراسيم تتخذ\n في مجلس الوزراء بناء على اقتراح وزير المالية .\n تاريخ نفاذ القانون المادة ‐ 157\n ينشر هذا القانون في الجريدة الرسمية ويطبق ابتداء من .2009/1/1\n 42\n\f قرار رقم 1/453\n صادر في 22نيسان2008\n تحديد دقائق تطبيق\n احكام القانون رقم 44\n تاريخ11/11/2008\n )(قانون الاجراءات الضريبية(\n ان وزير المالية،"}, {"o": 107, "l": "المادة 2", "b": "بناء على المرسوم رقم 18تاريخ( 11/07/2008تشكيل الحكومة)،\n بناء على القانون رقم 44تاريخ ( 11/11/2008قانون الاجراءات الضريبية)،\n بناء على اقتراح مدير المالية العام،\n وبعد استشارة مجلس شورى الدولة )الرأي رقم 157/2008‐2009تاريخ ،)2009/03/26\n يقرر ما يأتي:\n المادة الاولى -تعريف المصطلحات\n يقصد بالعبارات التالية اينما وردت في هذا القرار ما يلي :\n ‐1القانون :قانون الاجراءات الضريبية.\n ‐2الضريبة :اي ضريبة أو رسم باستثناء الرسوم الجمرآية والعقارية ،تتولى وزارة المالية تحقيقها وتحصيلها ،ومنها :\n أ -ضريبة الدخل\n ب -ضريبة الأملاك المبنية\n ج -رسم الانتقال\n د ‐ضريبة التحسين\n هـ -الضريبة على القيمة المضافة\n و -الضرائب غير المباشرة والرسوم المماثلة لها\n ز -الضرائب والرسوم التي قد تستحدث\n ما لم ينص القانون على خلاف ذلك ،تشمل آلمة \"الضريبة\" اينما وردت في هذا القرار اساس الضريبة وملحقاتها ،اي\n الغرامات والفوائد ونفقات التحصيل الجبري المتعلقة بالضريبة.\n ‐3المكلف :آل شخص ملزم بحكم القوانين الضريبية بموجبات ضريبية ،وتسري احكام هذا القرار المطبقة على\n المكلف ،على مقتطع الضريبة ايضا الا في الحالات التي ينص القانون على خلاف ذلك.\n‐4الفترة الضريبية :الفترة الزمنية التي تتضمن الواقعة أو الوقائع المنشئة للضريبة ،والتي عند انتهائها يتوجب التصريح\n عن الضريبة أو تأديتها خلال مهلة محددة وفقا للنصوص القانونية لكل ضريبة .\n‐5الادارة الضريبية :الوحدة المختصة في وزارة المالية -مديرية المالية العامة -المناط بها اعمال ادارة وتحقق ومراقبة\n الضريبة وتحصيلها ،وذلك وفقا للصلاحيات المحددة قانونا .\n ‐6الشخص :الشخص الطبيعي والمعنوي ،ما لم يحدد القانون احدهما .\n ‐7مقتطع الضريبة :الشخص الذي يتوجب عليه قانونا اقتطاع الضريبة عند المنبع من المبالغ المستحقة لشخص آخر\n )المكلف الأساسي( وتسديدها للخزينة .\n 43"}, {"o": 108, "l": "المادة 2", "b": "‐8الضريبة الاضافية :الضريبة الناتجة عن تدارك آل آتمان أو نقص في الضريبة المتوجبة .\n ‐9الشرآات المساهمة :الشرآات المغفلة وشرآات التوصية بالأسهم.\n ‐10الأراضي اللبنانية أو لبنان :الأراضي والأجواء والمياه الاقليمية اللبنانية .\n‐11في ما يخص المواد المتعلقة باستعمال النظام الضريبي الالكتروني ،يقصد بالكلمات والتعابير الواردة المعاني التالية :\n \" ‐الوزارة\" :وزارة المالية.\n \" ‐النظام\" :النظام الضريبي الالكتروني وهو نظام ادارة وارسال التصاريح والبيانات الضريبية الى وحدات وزارة\n المالية المختصة عبر الانترنت.\n \" ‐التصريح\" :التصريح الالكتروني وهو عبارة عن آافة التصاريح وطلبات الاسترداد والبيانات الضريبية الممكن\n ارسالها الى الوزارة عبر النظام.\n \" ‐المستخدم\" :مستخدم النظام وهو المكلف )شرآة/مؤسسة فردية/صاحب مهنة/جمعية/نقابة (...الحاصل على المفاتيح\n الالكترونية لاستخدام النظام أو من فوضه بذلك.\n \" ‐العمليات الالكترونية\" :جميع العمليات المتوفرة على النظام )على سبيل المثال التصريح عن الضرائب الدورية\n والسنوية أو الاستعلام عن التصاريح المقدمة سابقا ).\n \" ‐الضريبة\" :اية ضريبة أو رسم يشملها النظام .\n \" ‐تعهد\" :تعهد بالالتزام بأصول وشروط استخدام النظام يوقعه مستخدم النظام .\n تحديد دقائق تطبيق\n احكام البند 2من"}, {"o": 109, "l": "المادة 10", "b": "المادة 10من القانون\n المتعلقة بشرعية استعمال الحق"}, {"o": 110, "l": "المادة 2", "b": "المادة2\n في حال تمت عملية بين اشخاص مترابطين يحق للادارة الضريبية ان تعيد تقييم قيمة العملية المنفذة بهدف تحديد\n المبالغ الخاضعة للضريبة للفترة الضريبية العائدة لها ،ولها من اجل ذلك اعتماد القيمة السوقية العادلة للعملية .\n يقصد بالقيمة السوقية العادلة ،قيمة العملية آما لو تمت بين اشخاص مستقلين عن بعضهم البعض وضمن شروط تنافسية\n آاملة مقارنة مع عمليات مشابهة حاصلة بتاريخ تنفيذ العملية موضوع الضريبة ."}, {"o": 111, "l": "المادة 3", "b": "المادة3\n يعتبر الأشخاص الطبيعيون مترابطين في حال آان بينهم سلطة الاشراف والتوجيه أو صلة تبعية آأن يكون احدهم\n اجيرا لدى الآخر أو صلة وصاية بين الوصي والقاصر أو فاقد الاهلية ،أو في حال آانوا شرآاء متضامنين تجاه موجب\n ما ."}, {"o": 112, "l": "المادة 4", "b": "المادة4\n يعتبر الشخص الطبيعي والشخص المعنوي مترابطين عندما يكون لأحدهما سلطة الاشراف والتوجيه على الآخر .\n يعتبر الأشخاص المعنويون مترابطين عندما يكون لشخص معنوي سلطة الاشراف والتوجيه على شخص أو عدة\n اشخاص معنويين آخرين .\n يكون لأحد الأشخاص )طبيعي أو معنوي( سلطة التوجيه والاشراف على شخص أو على مؤسسة أو على عدة اشخاص\n آخرين أو مؤسسات عندما يتمتع بسلطة ادارية على الآخرين من شأنها تقرير مسار عمل الشخص الآخر من النواحي\n 44\n\f المالية والاقتصادية والتنظيمية .\n تعتبر المعايير التالية قرينة على وجود سلطة اشراف وتوجيه :\n أ -بالنسبة الى شرآات الأموال ،حيازة شخص طبيعي أو معنوي لغالبية رأس مال الشرآة التابعة له والتي تمكنه من\n التمتع بغالبية حقوق التصويت فيها ،أو من تسمية اآثر من نصف اعضاء مجلس ادارتها أو المدراء فيها .أو في حال\n آان الشخص الطبيعي أو المعنوي مفوضا من قبل مجلس ادارة الشرآة في ما يتعلق بتقرير مسار عمل الشرآة من\n النواحي المالية والاقتصادية والتنظيمية حتى ولو آان لا يمتلك لغالبية رأس مال الشرآة .\n ب -بالنسبة الى شرآات الأشخاص ،امتلاك شخص لأآثر من %50من حصص آل شرآة أو الحق بالمشارآة بأآثر\n من %50من ارباحها.\nج -بالنسبة الى الأشخاص الطبيعيين امتلاك شخص لعدة مؤسسات فردية أو امتلاك عدة اشخاص لأآثر من مؤسسة على\n ان تقتصر صلة القرابة التي تربطهم على الزوج أو الزوجة أو الأولاد القاصرين أو فاقدي الأهلية .\n من اجل احتساب نسبة حيازة الأسهم أو الحصص في الشرآات أو تملك المؤسسات الفردية ،يعتبر الزوج والزوجة\n والأشقاء والشقيقات والأولاد غير القاصرين وآذلك الأولاد القاصرين أو فاقدي الأهلية آأنهم شخص واحد ."}, {"o": 113, "l": "المادة 5", "b": "المادة5\n في حال قامت الادارة الضريبية بتعديل قيمة العمليات وشروطها بين اشخاص مترابطين ،يمكن اعادة النظر في\n المفاعيل الضريبية المتعلقة بالطرف المترابط الآخر للعملية بناء لطلب هذا الطرف في حال آان له مصلحة بذلك .\n تحديد دقائق تطبيق\n احكام البند 4من"}, {"o": 114, "l": "المادة 18", "b": "المادة18\n من القانون\n المتعلقة بتسديد الضريبة المتوجبة\n في حال الغياب وانعدام الاهلية"}, {"o": 115, "l": "المادة 6", "b": "المادة6\n تنتقل الموجبات الضريبية:\n ‐عند اعتبار المكلف مفقودا أو غائبا بحسب القانون ،الى ممثله القانوني،\n ‐عند فاقد الأهلية ،الى ممثله الشرعي أو القانوني أو الى الوصي المعين من قبل المحكمة ."}, {"o": 116, "l": "المادة 7", "b": "المادة7\n يتوجب على الشخص الذي يمثل فاقد الأهلية أو الغائب ،اعلام الوحدة الضريبية المختصة ،التي آان المكلف مسجلا\nلديها أو آان مكتوما ويدخل ضمن نطاق صلاحياتها ،بوفاته أو بتغيير حالته ،وذلك خلال مهلة شهرين من تاريخ حصول\n الواقعة ،وتقديم تصريح عن الضريبة المتوجبة على المكلف عن الفترة الممتدة من تاريخ نهاية الفترة الضريبية السابقة\n التي تم التصريح عنها حتى تاريخ نشوء الواقعة ،وتسديد هذه الضريبة .\n يعتبر غائبا أو فاقد الأهلية آل شخص صدر حكم بغيبته أو بفقدانه الأهلية .\n 45"}, {"o": 117, "l": "المادة 8", "b": "المادة8\n يتضمن الاعلام المشار اليه في"}, {"o": 118, "l": "المادة 7", "b": "المادة 7من هذا القرار المعلومات التالية :\n ‐اسم المكلف ورقمه الشخصي لدى وزارة المالية،\n ‐اسماء المؤسسات والشرآات التي يملك حصصا أو مساهمات فيها وارقام تسجيلها لدى وزارة المالية،\n ‐نوع الواقعة )غياب أو انعدام الأهلية( وتاريخها،\n ‐اسم وعنوان من يمثل المكلف وصفته ،ورقم تسجيله لدى وزارة المالية في حال وجوده،\n ‐توقيع مقدم الاعلام وصفته ."}, {"o": 119, "l": "المادة 9", "b": "المادة9\n يرفق بالاعلام المقدم للادارة الضريبية المختصة المستندات التالية :\n أ -في ما خص الغياب :\n ‐صورة عن الحكم بالغيبة.\n ب -في ما خص فقدان الأهلية :\n ‐صورة عن الحكم الصادر بفقدان اهلية المكلف ."}, {"o": 120, "l": "المادة 10", "b": "المادة10\nفي حال عدم آفاية اموال المكلف الغائب أو المفقود أو فاقد الأهلية لتسديد الضريبة المتوجبة ،يمكن لممثله القانوني أو\n الشرعي أو الوصي المعين تقديم طلب خطي الى الادارة الضريبية لشطب الجزء من الضريبة المتوجبة الذي يزيد عن\n مجموع اموال المكلف شرط تقديم المستندات الثبوتية التالية :\n ‐آشوفات مصرفية وخلاصة عن حساباته الدائنة والمدينة،\n ‐افادة من الدوائر العقارية بجميع العقارات التي يملكها،\n ‐افادة من السجل التجاري عن ملكيته لمؤسسات أو حصص أو مساهمات في شرآات،\n ‐افادة من مصلحة تسجيل السيارات والآليات ومن ادارة المرافئ عن ملكيته للسيارات والمرآبات،\n ‐تعهد من الموقع بعدم وجود اي مبالغ نقدية أو مجوهرات أو اسهم لحامله وما شابه .\n ويمكن للادارة الضريبية طلب ابراز اي مستند تراه مناسبا لاثبات عدم ملاءة المكلف ."}, {"o": 121, "l": "المادة 11", "b": "المادة11\n يجري شطب المبالغ الزائدة بموجب قرار يصدر عن وزير المالية بناء لاقتراح مدير المالية العام وبعد انهاء رئيس\nالادارة الضريبية المستند على دراسة تجريها هذه الادارة .وتتولى الدائرة الضريبية المختصة ابلاغ ممثل المكلف بقرار\n قبول أو رفض الطلب ."}, {"o": 122, "l": "المادة 12", "b": "المادة12\n يعتبر قرار الشطب لاغيا في حال :\n ‐استعاد المكلف اهليته أو عاد الغائب أو المفقود .عندها يتوجب على المكلف أو على ممثله ابلاغ مديرية الواردات\n ومديرية الضريبة على القيمة المضافة آل في ما يعنيها بذلك للرجوع عن قرار شطب الضريبة ،وذلك دون ان تسري\n الفائدة والغرامة عن الفترة التي آان الشخص خلالها غير متمتع بالأهلية أو آان مفقودا .\n 46\n\f يعد سريان الفائدة والغرامة من تاريخ استعادة الأهلية أو عودة المفقود .\n ‐تبين لاحقا بأن قرار شطب الضريبة آان مستندا الى اسباب غير جدية أو خاطئة نتيجة تزوير أو اخفاء معلومات أو\n مستندات ثبوتية أو نتيجة اغفال التصريح عن بعض المعلومات أو نتيجة عدم معرفتها .وتسري الفائدة والغرامة على\n الضريبة المتوجبة من تاريخ استحقاقها .\n تحديد دقائق تطبيق\n احكام"}, {"o": 123, "l": "المادة 24", "b": "المادة 24من القانون\n المتعلقة بابلاغ الادارة الضريبية\n عن تأسيس المؤسسات\n وتعديلاتها والانتساب الى النقابات"}, {"o": 124, "l": "المادة 13", "b": "المادة13\n على رؤساء الأقلام في المحاآم التجارية والمدنية المختصة ،وريثما يوضع مشروع الربط الالكتروني موضع التنفيذ،\n ابلاغ مديرية الواردات عن التسجيلات المدونة في السجل التجاري أو السجل المدني وجميع الوقوعات المتعلقة\n بالأشخاص الطبيعيين والمعنويين وذلك بموجب بيانات المعلومات المحددة ادناه وفقا لما يلي :\n ‐خلال مهلة اقصاها 2009/6/30عن التسجيلات والوقوعات المدونة لديها لغاية .2008/12/31\n‐خلال مهلة اقصاها شهر من تاريخ نشر هذا القرار عن التسجيلات والوقوعات المدونة لديها من 2009/01/01ولغاية\n نشر هذا القرار.\n ‐خلال مهلة اقصاها العاشر من آل شهر عن التسجيلات والوقوعات المسجلة لديها خلال الشهر الذي سبقه ،وذلك\n اعتبارا من تاريخ نشر هذا القرار .\n ‐أو بناء لطلب الادارة الضريبية في حالات معينة.\n تتضمن البيانات المطلوبة ما يلي :\n ‐1بيان معلومات بالتجار والمحلات التجارية والمؤسسات التجارية الفردية المسجلة خلال الفترة ،يتضمن المعلومات\n التالية :\n ‐اسم التاجر وشهرته ،تاريخ ومكان الولادة ،رقم ومكان السجل .\n ‐المحلات التجارية والمؤسسات التجارية الفردية التي يملكها ،وشهرتها التجارية،\n ‐عنوان المرآز الرئيسي لكل محل أو مؤسسة،\n ‐رقم السجل التجاري وتاريخ التسجيل،\n ‐عدد فروع آل مؤسسة أو محل تجاري وعنوان آل فرع،\n ‐رقم الهاتف،\n ‐النشاط،\n ‐براءات الاختراع والاآتشافات والامتيازات والمارآات المسجلة وسواها من الحقوق المحفوظة .\n ‐2بيان معلومات بالشرآات والمؤسسات التجارية والمدنية المسجلة خلال الفترة ،يتضمن المعلومات التالية :\n ‐اسم الشرآة وشهرتها التجارية،\n ‐رقم السجل التجاري أو السجل المدني وتاريخ التسجيل،\n ‐الشكل القانوني،\n ‐اسماء الشرآاء أو المساهمين ،عدد الأسهم أو الحصص المملوآة ،تاريخ التملك،\n ‐عدد الفروع،\n ‐رأس المال،\n ‐مدة الشرآة،\n ‐عنوان المرآز الرئيسي وعنوان آل فرع،\n 47\n\f ‐رقم الهاتف،\n ‐النشاط،"}, {"o": 125, "l": "المادة 13", "b": "‐اسم المفوض بالتوقيع عن الشرآة،\n ‐براءات الاختراع والاآتشافات والامتيازات والمارآات المسجلة وسواها من الحقوق المحفوظة.\n ‐المؤسسات التجارية المملوآة من شرآات .\n ‐3بيان المعلومات الطارئة على السجلات ،يتضمن :\n ‐معلومات بالوقوعات )تعديلات ،تفرغ أو بيع ،تصفية ،افلاس ،دمج ،تحويل...).\n ‐معلومات بأسماء الأشخاص الطبيعيين والمعنويين الذين تم شطبهم من السجل التجاري أو المدني وتاريخ شطب آل\n شخص ."}, {"o": 126, "l": "المادة 14", "b": "المادة14\n على النقابات والهيئات الخاصة المسؤولة عن تسجيل الأشخاص الذين يمارسون مهنا غير تجارية ،أن تودع مديرية\n الواردات بيانات المعلومات التي تتعلق بكافة التسجيلات والتعديلات وقرارات الشطب والاحالات على التقاعد المحددة\n ادناه وفقا لما يلي :\n ‐خلال مهلة اقصاها 2009/03/31عن التسجيلات والتعديلات وقرارات الشطب والاحالة على التقاعد المدونة لديها\n لغاية31/12/2008.\n ‐خلال مهلة اقصاها شهر من تاريخ نشر هذا القرار عن التسجيلات والتعديلات وقرارات الشطب والاحالات على\n التقاعد المدونة لديها من 2009/01/01ولغاية نشر هذا القرار.\n‐خلال مهلة اقصاها العاشر من آل شهر عن التسجيلات والتعديلات وقرارات الشطب والاحالات على التقاعد المدونة\n لديها خلال الشهر الذي سبقه ،وذلك اعتبارا من تاريخ نشر هذا القرار .\n ‐أو بناء لطلب الادارة الضريبية في حالات معينة.\n يجب ان تتضمن هذه البيانات المعلومات التالية:\n ‐الاسم الكامل )الاسم ،اسم الأب ،الشهرة ،اسم الأم)،\n ‐تاريخ الولادة ،مكان الولادة ،رقم السجل مكان السجل،\n ‐تاريخ الانتساب الى النقابة ،رقم الانتساب،\n ‐الاختصاص،\n ‐العنوان الشخصي )محافظة ،قضاء ،منطقة ،حي ،شارع ،مبنى ،المنطقة العقارية ،ورقم العقار)،\n‐عنوان العمل )في حال آان موظفا أو يمارس المهنة لحسابه الخاص() ،تحديد :محافظة ،قضاء ،منطقة ،حي ،شارع،\n مبنى ،المنطقة العقارية ورقم العقار(،\n ‐رقم الهاتف،\n ‐التعديلات وتواريخها،\n ‐تاريخ الشطب،\n ‐تاريخ التقاعد ."}, {"o": 127, "l": "المادة 15", "b": "المادة15\n على دوائر الأحوال الشخصية ،ابلاغ مديرية الواردات عن الوفيات المسجلة لديها وعن آل حالة اعلان وفاة شخص\n آان بحكم المفقود ،وذلك بموجب بيان المعلومات المحددة فيما يلي ،اعتبارا من تاريخ نفاذ القانون ،على ان يتم الابلاغ\nدوريا آل ثلاثة اشهر في موعد لا يتعدى الخامس عشر من الشهر الذي يلي فترة الثلاثة اشهر المعنية أو بناء لطلبها في\n حالات معينة .\n 48\n\f يجب ان يتضمن هذا البيان ما يلي :\n ‐الاسم الكامل )الاسم ،اسم الأب ،الشهرة ،اسم الأم)،\n ‐تاريخ الولادة ،مكان الولادة ،رقم السجل ،مكان السجل،\n ‐مكان السكن قبل الوفاة أو قبل اعلان الوفاة،\n ‐تاريخ الوفاة أو تاريخ اعلان الوفاة،\n ‐مكان الوفاة ."}, {"o": 128, "l": "المادة 16", "b": "المادة16\n على مديرية الواردات ايداع آل من الادارات والنقابات والهيئات الخاصة المشار اليها في هذا القرار لائحة بأسماء\n الأشخاص الحقيقيين والمعنويين الذين سبق لها وابلغت الادارة الضريبية المعلومات المتعلقة بهم ،تتضمن ارقامهم\n الضريبية ."}, {"o": 129, "l": "المادة 17", "b": "المادة17\nيتم ايداع بيانات المعلومات المنصوص عليها في هذا القرار الادارة الضريبية على اقراص مدمجة) ، (CDأو عبر منح\n مديرية الواردات الحق بالولوج إلى قاعدة المعلومات العائدة للادارات العامة والنقابات والهيئات الخاصة لاستخراج\n المعلومات المطلوبة عن الأشخاص الطبيعيين والمعنويين المعنيين .\n تحديد دقائق تطبيق\n احكام"}, {"o": 130, "l": "المادة 26", "b": "المادة 26من القانون\n المتعلقة بالاستفسارات الضريبية"}, {"o": 131, "l": "المادة 18", "b": "المادة18\n يحق لكل شخص حقيقي أو معنوي ،أو من يمثله قانونا يرغب المباشرة بعمل أو عملية ما ان يتقدم بطلب استفسار\n خطي من الدائرة أو الفرع المختص بخدمات المكلفين ،وذلك قبل المباشرة بالعمل المنوي تأسيسه أو قبل تنفيذ العملية\n بغية التأآد من آيفية المعالجة الضريبية بالنسبة لكافة الضرائب والرسوم التي تحققها مديرية المالية العامة ."}, {"o": 132, "l": "المادة 19", "b": "المادة19\n يجب ان تتوفر في طلب الاستفسار المنصوص عليه في"}, {"o": 133, "l": "المادة 26", "b": "المادة 26من القانون الشروط التالية :\n ‐ان يكون مقدما قبل اآتمال الواقعة المراد الاستفسار حولها وان يتناول امورا واقعية لا افتراضية.\n ‐ان يكون مقدما من قبل صاحب العلاقة أو من يمثله قانونا .\n ‐ان يتم السؤال عن نقاط قانونية محددة متعلقة بعملية معينة .\n‐ان يتضمن جميع العناصر والوقائع الضرورية التي تخول الادارة الضريبية اتخاذ القرار الملائم في ما يتعلق بالمعالجة\n الضريبية .\n 49"}, {"o": 134, "l": "المادة 20", "b": "المادة20\n يجب ان يحتوي طلب الاستفسار على المعلومات التالية :\n ‐اسم طالب الاستفسار وعنوانه ومحل اقامته المختار،\n ‐الرقم الضريبي في حال وجوده،\n ‐تحديد الموضوع المراد الاستفسار عنه بشكل واضح ،اي على سبيل المثال لا الحصر الوقائع ونوع العملية والنقاط\n القانونية المتعلقة بها والتاريخ المحدد لتنفيذها وآلفتها المتوقعة .\n ‐تحديد الأطراف المعنية بالعملية أو العقد وعلاقتها ببعضها ،ويجب ان يرفق به آافة المستندات الثبوتية المتعلقة به\n والتوآيل القانوني في حال وجوده ."}, {"o": 135, "l": "المادة 21", "b": "المادة21\n يفرض على آل طالب استفسار رسم تحدد شروطه ومقداره بموجب مرسوم يتخذ بناء على اقتراح وزير المالية .\n لا يقبل طلب الاستفسار الا اذا آان مرفقا بايصال يثبت تسديد الرسم المتوجب ."}, {"o": 136, "l": "المادة 22", "b": "المادة22\n يحق للادارة الضريبية ،في سياق درسها للطلب ،ان تطلب من صاحب العلاقة خطيا معلومات اضافية أو مستندات\n تتعلق بموضوع الاستفسار ،وعليه أن يقدم هذه المعلومات والمستندات خلال مهلة عشرة ايام من تاريخ مطالبته بها والا\n تعمد الادارة الضريبية الى اجابة المكلف على مسؤوليته وفقا للمستندات المقدمة منه ،وتشير في جوابها اليه الى\n المستندات التي طلبتها منه ولم يبرزها ."}, {"o": 137, "l": "المادة 23", "b": "المادة23\nيتوجب على الادارة الضريبية ان تبت في الطلب وتجيب صاحب العلاقة بموجب آتاب خطي موجها اليه مباشرة حتى\n ولو آان طلب الاستفسار مقدما من قبل ممثله القانوني ،على اسئلته ضمن مهلة اقصاها شهرين من تاريخ تقديم\nالمعلومات والمستندات اللازمة للبت بالطلب ،وعليها ان تبلغه النتيجة وفقا لأصول التبليغ المنصوص عليها في القانون ."}, {"o": 138, "l": "المادة 24", "b": "المادة24\nتلزم الادارة الضريبية بالجواب الصادر عنها اذا تقيد طالب الاستفسار عند التنفيذ بهذا الجواب وآان هذا الجواب مبنيا\n على وقائع واضحة وصحيحة مقدمة من صاحب العلاقة ."}, {"o": 139, "l": "المادة 25", "b": "المادة25\n في حال تم مراجعة وتدقيق تصاريح المكلف واعماله من قبل الادارة الضريبية ،وتبين لها ان جوابها لم يطبق عند\n تنفيذ العملية موضوع الاستفسار ،حق لها ان تصدر التكاليف اللازمة وتفرض الغرامات المتوجبة اذا جاء التطبيق من\n قبل المكلف مخالفا للنصوص القانونية.\n يحق للمكلف الاعتراض على هذه التكاليف وفقا لأصول الاعتراض المنصوص عليها في الفصل 12من قانون\n الاجراءات الضريبية .\n 50"}, {"o": 140, "l": "المادة 26", "b": "المادة26\n لا تطبق الأجوبة الصادرة عن الادارة الضريبية ولا تكون الزامية الا بالنسبة للعملية المطلوب الاستفسار عنها ،آما\nتبقى هذه الأجوبة محكومة بسريان القوانين التي جاءت على ضوئها بحيث تصبح الادارة الضريبية بحل من جوابها عند\n تعديل النص القانوني الذي بنت هذا الجواب على اساسه .\n تحديد دقائق تطبيق\n احكام المادتين 29و 30من القانون\n المتعلقتين بمسك وحفظ السجلات\n والمستندات المحاسبية"}, {"o": 141, "l": "المادة 27", "b": "المادة27\n يقصد بالأشخاص المكلفين بضريبة الدخل على غير أساس الربح الحقيقي المشار اليهم في البند 2من"}, {"o": 142, "l": "المادة 29", "b": "المادة 29من\n القانون المكلفين على اساس الربح المقطوع والمكلفين على اساس الربح المقدر ."}, {"o": 143, "l": "المادة 28", "b": "المادة28\n ان السجلات المحاسبية الواجب مسكها بصورة الزامية هي :\n أ -بالنسبة للمكلفين على اساس الربح الحقيقي :\n ‐سجل اليومية الذي تسجل فيه العمليات التي تتعلق بنشاط المكلف يوما فيوما وفقا لتسلسلها التاريخي والرقمي ويمكن\n للمكلف الذي يحول نوع عمله دون ذلك ان يسجل فيه تلك العمليات بصورة اجمالية مرة في الشهر على الأقل شرط ان\nيحصل على موافقة خطية مسبقة بذلك من الدائرة المالية المختصة وان يحفظ جميع الوثائق التي تمكن من مراقبة صحة\n تلك الأعمال يوما فيوما .\n ‐سجل الأستاذ لفتح الحسابات ومتابعتها .\n ‐سجل الجردة حيث تسجل فيه عناصر الجرد والميزانية وحساب النتيجة .\n‐سجل الرواتب والأجور حيث تسجل فيه اسماء المستخدمين والعمال والمياومين وغيرهم من الأجراء ،ومقدار رواتبهم\n واجورهم ونوع عملهم ،وتاريخ مباشرتهم العمل ،وتاريخ ترآهم العمل أو صرفهم منه.\n آما تلزم الشرآات المساهمة وشرآات التوصية بالأسهم اضافة إلى السجلات المذآورة اعلاه ،بمسك سجل الأسهم\nالاسمية الذي يتضمن آافة المعلومات والتفاصيل المتعلقة بهذه الأسهم منذ تأسيس الشرآة )شراء ،تفرغ ،زيادة ،الغاء...\n وآافة التعديلات التي تطرأ على الأسهم الاسمية ).\n ب -بالنسبة للمكلفين على اساس الربح المقطوع :\n ‐سجل اليومية تقيد فيه الواردات والنفقات يوما فيوما لتسلسلها التاريخي والرقمي .\n ‐سجل الأصول الثابتة وفقا للنماذج المبينة في الملحق رقم 6من المرسوم رقم 4665تاريخ (1981/12/26التصميم\n المحاسبي العام).\n ‐سجل الرواتب والأجور في حال وجود مستخدمين .\n ج -بالنسبة للمكلفين على اساس الربح المقدر\n ‐سجل اليومية يقيد فيه مجموع الواردات والنفقات يوما فيوما.\n ‐سجل الأصول الثابتة في حال وجودها.\n ‐سجل الرواتب والأجور في حال وجود مستخدمين .\n 51\n\f د -بالنسبة للمؤسسات المستثناة من الضريبة على الدخل :"}, {"o": 144, "l": "المادة 28", "b": "تلزم المؤسسات المستثناة من الضريبة على الدخل المتخذة شكل شرآات ،بمسك السجلات المطلوب مسكها من المكلفين\n على اساس الربح الحقيقي .\n اما المؤسسات المستثناة من الضريبة على الدخل من غير الشرآات فيمكنها ان تمسك السجلات المطلوب مسكها من\n المكلفين على اساس الربح الحقيقي ،أو ان تكتفي بمسك محاسبة نقدية تتألف بصورة الزامية من السجلين المطلوب\n مسكهما من المكلفين على اساس الربح المقطوع اضافة إلى سجل الرواتب والأجور.\n هـ -بالنسبة للمؤسسات العامة والبلديات واتحادات البلديات :\n يتوجب على المؤسسات العامة والبلديات واتحادات البلديات ،مسك سجل الرواتب والأجور فقط ."}, {"o": 145, "l": "المادة 29", "b": "المادة29\n يتوجب على المكلفين الخاضعين للضريبة على القيمة المضافة ،مسك سجلات اليومية والجردة والأستاذ ."}, {"o": 146, "l": "المادة 30", "b": "المادة30\n يمكن للمؤسسة ان تستعمل سجلات يومية مساعدة وسجلات استاذ مساعدة وفقا لمتطلباتها وحاجاتها .ويتم ،بصورة\n دورية ،تجميع المعطيات المسجلة في اليوميات المساعدة في سجلي يومية واستاذ مرآزيين ."}, {"o": 147, "l": "المادة 31", "b": "المادة31\n على آل مؤسسة ان تقوم بجرد عناصر موجوداتها ومطلوباتها مرة واحدة في السنة على الأقل ،وان توقف جميع\n حساباتها بهدف تحديد نتيجة اعمالها ووضع ميزانيتها ."}, {"o": 148, "l": "المادة 32", "b": "المادة32\n يمكن مسك السجلات والمستندات المحاسبية ،لغايات فرض الضرائب والرسوم بدون تختيمها أو التأشير عليها ،وذلك\n بأية وسيلة أو طريقة ملائمة من ِشأنها ان تضمن صحة القيود وتلبي مقتضيات التدقيق المحاسبي ،ومن بينها مسك\n السجلات والمستندات المحاسبية وحفظها الكترونيا عبر اعتماد المكلف انظمة محاسبية ممكننة تتوفر فيها الشروط التي\n تؤمنها الطريقة التقليدية لا سيما لجهة ان تكون الآلات التي يستخدمها المكلف لهذه الغاية مجهزة بما يمكن الادارة\nالضريبية من آشف اية قيود تعديلية تطرأ على تلك السجلات أو اية اضافات لاحقة والتحقق من صحة التسجيل والحفظ،\n ويجب ان يضع المكلف بتصرف الادارة الضريبية دليل استخدام تلك الأنظمة عند الحاجة ."}, {"o": 149, "l": "المادة 33", "b": "المادة33\n يقصد بحفظ السجلات والمستندات المحاسبية بواسطة الحاسوب الآلي أو اي من التقنيات الحديثة الأخرى ،حفظ تلك\n السجلات والمستندات الكترونيا عبر اعتماد المكلف انظمة محاسبية ممكننة تثبت العمليات المحاسبية وتعالجها وتصدر\n المستندات والبيانات المطلوبة ورقيا عند طلبها من قبل الادارة الضريبية .\n 52"}, {"o": 150, "l": "المادة 34", "b": "المادة34\n يمكن للمكلفين الذين يبيعون نقدا بواسطة آلة تسجيل النقد ) (cash registerأو الذين يبيعون بالفاتورة ،ان يحفظوا\n الفواتير والايصالات وغيرها من المستندات المثبتة لتلك المبيعات بطريقة الكترونية ،شرط ان تكون الآلات التي\n يستعملونها لهذه الغاية مجهزة لاصدار تلك الفواتير والايصالات والمستندات ورقيا على اآثر من نسخة وفقا لتسلسل\nتاريخي ورقمي وفقا لحدوثها الزمني وبطريقة تحول دون اضافة اية قيود عن طريق الحشو أو الغاء أية قيود أو اجراء\n اية اضافات لاحقة بما يمكن الادارة الضريبية من التحقق من صحة التسجيل والحفظ.\nعلى المكلفين الذين يريدون حفظ المستندات المشار اليها اعلاه بطريقة الكترونية ان يحصلوا من الادارة الضريبية على\n موافقة خطية مسبقة بهذا الخصوص ."}, {"o": 151, "l": "المادة 35", "b": "المادة35\nعلى المكلف الذي يستبدل نظام المكننة المستخدم من قبله ان يحفظ السجلات والمستندات القديمة التي لا يسمح القانون\n باتلافها طيلة المدة القانونية ،وعليه الاستمرار في حفظ السجلات والمستندات المحاسبية الممكننة حتى ولو تم طباعتها\n وحفظها ورقيا .\n في جميع الأحوال ،على المكلف الاحتفاظ بنسخة اضافية الكترونية ) (Backupعن المعلومات المحفوظة في النظام\n الممكنن وعن دليل الاستخدام ."}, {"o": 152, "l": "المادة 36", "b": "المادة36\nيمكن للمكلف التعاقد مع طرف ثان بهدف مسك وحفظ السجلات والمستندات المحاسبية الكترونيا شرط ان يتم حفظها\nفي مرآز عمله أو في محل اقامته ،ويبقى بالتالي مسؤولا امام الادارة الضريبية ولا تنتقل حقوقه وواجباته المتعلقة بتلك\n السجلات والمستندات الى الطرف الثاني ."}, {"o": 153, "l": "المادة 37", "b": "المادة37\nتفرض على المكلف الذي يخالف احكام المادتين 29و 30من القانون المتعلقتين بحفظ السجلات والمستندات المحاسبية\n غرامة"}, {"o": 154, "l": "المادة 114", "b": "المادة 114من القانون .\n تحديد دقائق تطبيق\n احكام البند 1من"}, {"o": 155, "l": "المادة 32", "b": "المادة32\n من القانون\n المتعلقة بالتسجيل\n لدى الادارة الضريبية"}, {"o": 156, "l": "المادة 38", "b": "المادة38\n يتوجب على آل من يباشر عملا خاضعا للضريبة أو ملزما وفقا للقانون بموجبات ضريبية ،ومن ضمنهم الأشخاص\nالمعفيين من ضريبة الدخل على الأرباح التجارية والصناعية وغير التجارية ،ان يحيط الدائرة الضريبية المختصة علما\n بذلك ،بموجب طلب تسجيل ،خلال مهلة شهرين من تاريخ مباشرة العمل وذلك مع مراعاة احكام التسجيل في مديرية\n الضريبة على القيمة المضافة .\n يقدم طلب اعطاء العلم المذآور اعلاه وفقا لأحد النماذج التالية:\n 53\n\f ‐تصريح مباشرة العمل في ما يتعلق بضريبة الدخل\n ‐طلب تسجيل مستخدم/اجير في ما يتعلق بالضريبة على الرواتب والأجور\n ‐طلب التسجيل في مديرية الضريبة على القيمة المضافة عندما يكون هذا التسجيل الزاميا\n ‐تصريح مباشرة العمل ،في حال توجبها قانونا ،في ما يتعلق بضرائب نوعية اخرى ."}, {"o": 157, "l": "المادة 39", "b": "المادة39\n يتوجب التصريح عن مباشرة العمل على المكلفين المبينين ادناه :\n أ -شرآات الأموال :الشرآات المساهمة ،الشرآات المحدودة المسؤولية ،شرآات التوصية بالأسهم ،شرآات الهولدنغ،\n شرآات الأوف شور.\n ب -شرآات الأشخاص :شرآات التضامن ،شرآات التوصية البسيطة والشرآات المدنية.\n ج -الأشخاص الحقيقيون :يعتبر من الأشخاص الحقيقيين آل شخص يقوم بصورة فردية أو بالتعاون مع آخرين :\n ‐بمهن تجارية أو صناعية ،على سبيل المثال :حدادة وميكانيك السيارات ،المكتبات ،محلات البقالة ،الخ...\n ‐بأعمال غير تجارية أو غير صناعية )مهن حرة( ،على سبيل المثال :المحامي ،الطبيب ،الخ...\n ‐بكل عمل يدر ريعا غير خاضع لضريبة اخرى على الدخل وغير مصنف اعلاه.\n د -المؤسسات المستثناة من الضريبة على الأرباح التجارية والصناعية وغير التجارية )الباب الأول( وهم على سبيل\n المثال لا الحصر:\n الجامعات ،الجمعيات ،المدارس ،الخ...\n هـ -المؤسسات المعفاة بصورة مؤقتة من ضريبة الدخل على الأرباح )الباب الأول( :مثال المؤسسات الصناعية التي\n اعفيت بشروط معينة .\n وتعتبر جميع الفئات المذآورة اعلاه مسؤولة في ما خص التصريح عن مباشرة عمل العاملين لديها ."}, {"o": 158, "l": "المادة 40", "b": "المادة40\n تحدد تواريخ مباشرة العمل وفقا لما يلي :\n أ -شرآات الأموال :تاريخ تسجيل الشرآة في السجل التجاري .\n ب -شرآات الأشخاص :تاريخ التسجيل في السجل التجاري.\n ج -الأشخاص الحقيقيون :تاريخ مباشرة العمل التي تحدد بالاستناد إلى احد المعايير التالية :\n ‐1تاريخ اول عمل من شأنه ان ينتج ريعا خاضعا للضريبة على الأرباح )الباب الأول ).\n ‐2تاريخ التسجيل في السجل التجاري.\n ‐3تاريخ صدور اي مستند يثبت حصول عملية تجارية ،مثلا :فاتورة أو إيصال .\n ‐4تاريخ استخدام اجير .\n ‐5تاريخ استئجار أو استعمال مكان لمزاولة المهنة أو العمل .\n ‐6تاريخ اذن مزاولة المهنة أو التسجيل في النقابة لأصحاب المهن الحرة ،باستثناء :\n ‐المحامين :اعتبارا من تاريخ انتقال قيدهم إلى الجدول العام .\n ‐الصيادلة :اعتبارا من تاريخ التسجيل في السجل التجاري .\n في حال تعددت المعايير ،يؤخذ بتاريخ المعيار الحاصل اولا .\n د -المؤسسات المستثناة من الضريبة على الأرباح:\n‐1شرآات اموال -شرآات اشخاص -مؤسسات فردية :حسب التواريخ المحددة في الفقرات أ -ب -ج من هذه المادة .\n ‐2جمعيات -مدارس ‐ جامعات -مستشفيات تملكها جمعيات لا تتوخى الربح :تاريخ الترخيص أو العلم والخبر.\n هـ -الأجراء :اعتبارا من تاريخ الاستخدام .\n 54"}, {"o": 159, "l": "المادة 41", "b": "المادة41\n يقدم تصريح مباشرة العمل الى الوحدة الضريبية المختصة وفقا للنموذج المعد من قبل وزارة المالية لكل نوع من\n الأنواع المذآورة في"}, {"o": 160, "l": "المادة 39", "b": "المادة 39من هذا القرار ."}, {"o": 161, "l": "المادة 42", "b": "المادة42\n يرفق بالتصريح عن مباشرة العمل المستندات التالية :\n أ -شرآات الأموال :\n 1.صورة عن نظام الشرآة المسجل لدى السجل التجاري.\n 2.صورة عن شهادة التسجيل في السجل التجاري.\n 3.صورة عن الإذاعة التجارية .\n 4.صورة عن العلم والخبر من وزارة الاقتصاد والتجارة لفروع الشرآات الأجنبية العاملة في لبنان .\n 5.صورة عن عقد الايجار أو سند الملكية أو عقد الاستثمار أو إفادة من المالك بأن الإشغال هو على سبيل التسامح\n مرفقة بصورة عن سند الملكية )أو علم وخبر للعقارات غير الممسوحة).\n 6.صورة عن بطاقة الهوية أو إخراج قيد لكل مساهم أو شريك غير معرف على نظام الضرائب .\n 7.صورة عن شهادة تسجيل للمساهم من الأشخاص المعنويين .\n 8.أي مستند آخر تطلبه الإدارة الضريبية للتأآد من صحة المعلومات المصرح عنها من قبل المكلف .\n ب -شرآات الأشخاص:\n 1.صورة مصدقة عن عقد الشراآة.\n 2.صورة عن شهادة التسجيل في السجل التجاري.\n 3.صورة عن الإذاعة التجارية .\n 4.صورة عن العلم والخبر من وزارة الاقتصاد والتجارة لفروع الشرآات الأجنبية العاملة في لبنان.\n 5.صورة عن بطاقة الهوية أو إخراج قيد إفرادي للعازب أو عائلي للمتزوج لكل شريك غير معرف على نظام\n الضرائب.\n 6.صورة عن عقد الايجار أو سند الملكية أو عقد الاستثمار أو إفادة من المالك بأن الإشغال هو على سبيل التسامح\n مرفقة بصورة عن سند الملكية )أو علم وخبر للعقارات غير الممسوحة ).\n 7.أي مستند آخر تطلبه الادارة الضريبية للتأآد من صحة المعلومات المصرح عنها من قبل المكلف.\n ج -الأفراد والمؤسسات الفردية والمهن الحرة :\n 1.صورة عن شهادة التسجيل في السجل التجاري للمسجلين.\n 2.صورة عن بطاقة الهوية أو إخراج قيد إفرادي للعازب أو عائلي للمتزوج.\n3.صورة عن إذن مزاولة المهنة وصورة عن بطاقة التسجيل في النقابة أو إفادة انتساب ،للملزمين بالانتساب إلى نقابة ."}, {"o": 162, "l": "المادة 42", "b": "‐4صورة عن عقد الايجار أو سند الملكية أو عقد الاستثمار أو إفادة من المالك بأن الإشغال هو على سبيل التسامح\n مرفقة بصورة عن سند الملكية )أو علم وخبر للعقارات غير الممسوحة ).\n 5.أي مستند آخر تطلبه الادارة الضريبية للتأآد من صحة المعلومات المصرح عنها من قبل المكلف .\n د -الأشخاص المعفيون من الضريبة على الأرباح :\n 1.صورة عن نظام المؤسسة أو الشرآة.\n 2.صورة عن الترخيص الصادر عن المرجع الصالح.\n 3.صورة عن عقد الايجار أو سند الملكية أو عقد الاستثمار أو إفادة من المالك بأن الإشغال هو على سبيل التسامح\n مرفقة بصورة عن سند الملكية )أو علم وخبر للعقارات غير الممسوحة).\n 55\n\f 4.أي مستند آخر تطلبه الإدارة الضريبية للتأآد من صحة المعلومات المصرح عنها من قبل المكلف.\n ‐5الأجير:\n 1.نسخة عن إخراج قيد عائلي للأجير المتزوج .\n 2.نسخة عن إخراج قيد فردي أو صورة عن الهوية للأجير العازب.\n 3.نسخة عن جواز السفر للعامل الأجنبي ."}, {"o": 163, "l": "المادة 43", "b": "المادة43\nيتوجب على المكلف اعتبارا من تاريخ إعلامه رقم تسجيله الخاص بالضريبة ،الالتزام بجميع الموجبات التي يفرضها\n القانون ونصوصه التطبيقية عليه بدءا من تاريخ مباشرته العمل ،وتسري بحقه ولصالحه مفاعيل التسجيل آافة ."}, {"o": 164, "l": "المادة 44", "b": "المادة44\n ‐ 1تفرض على آل شخص لم يقدم طلب تسجيله لدى الادارة الضريبية ضمن المهل القانونية ،الغرامة المنصوص\n عليها في البند 1من"}, {"o": 165, "l": "المادة 107", "b": "المادة 107من القانون وقدرها :\n ‐ 2.000.000ل.ل( .مليونا ليرة لبنانية( للشرآات المساهمة،\n‐ 1.000.000ل.ل) .مليون ليرة لبنانية( لشرآات الأشخاص وللشرآات المحدودة المسؤولية وللمؤسسات المستثناة من\n الضريبة،\n ‐ 300.000ل.ل) .ثلاثماية ألف ليرة لبنانية( للأفراد ولباقي المكلفين .\n ‐2تفرض على آل صاحب عمل لا يقوم بتسجيل أجرائه لدى الادارة الضريبية ،غرامة مقطوعة قدرها خمسون ألف\n ليرة لبنانية عن آل مستخدم أو أجير لا يتم تسجيله خلال المهل المحددة ،أو إعطاءه معلومات خاطئة عنه ."}, {"o": 166, "l": "المادة 45", "b": "المادة45\n يتوجب على المكلف ،الذي تتوفر فيه شروط مباشرة العمل ولا نية له بمزاولة العمل فعليا ،أن يتقدم بطلب التسجيل\n خلال المهلة المحددة مرفقا بتصريح عدم المزاولة الفعلية للعمل.\n آما عليه أن يقدم هذا التصريح سنويا إلى الوحدة الضريبية المختصة وذلك ضمن المهلة القانونية العائدة لتقديم تصريح\n ضريبة الدخل.\n يقدم تصريح عدم مزاولة العمل لدى الوحدة الضريبية المختصة ،وفقا للنموذج المعد من قبل وزارة المالية.\n يعفى المكلفون الذي يقدمون سنويا تصريح عدم المزاولة الفعلية للعمل من موجب مسك السجلات القانونية وتقديم\n تصاريح ضريبة الدخل والبيانات المالية الملحقة بها ،إلى حين مزاولة العمل الفعلي وعندها تطبق الاجراءات الخاصة\n بمباشرة العمل ."}, {"o": 167, "l": "المادة 46", "b": "المادة46\n عندما يتضمن التصريح عن مباشرة العمل نشاطا خاضعا لأآثر من نوع ضريبة يعتبر هذا التصريح تصريحا عن\n آافة أنواع الضرائب في ما عدا الضريبة على القيمة المضافة.\n عندما يقوم شخص حقيقي بإضافة نشاط في نفس مكان العمل المصرح به للدائرة الضريبية المختصة أو يقوم بنفس\nالنشاط في مكان عمل آخر ،يتوجب عليه تعديل المعلومات المتعلقة به ضمن مهلة الشهرين المنصوص عليها في البند 2\n من"}, {"o": 168, "l": "المادة 32", "b": "المادة 32من القانون وفق للنموذج المعد من قبل وزارة المالية .\n عندما يقوم شخص حقيقي بنشاط جديد في مكان عمل آخر ،يتوجب عليه التصريح عن مباشرة عمل جديد وذلك ضمن\n 56\n\fمهلة الشهرين المنصوص عليها في"}, {"o": 169, "l": "المادة 38", "b": "المادة 38من هذا القرار ،وذلك مع مراعاة أحكام القرار رقم 1/368تاريخ 4نيسان\n 2002المتعلق بالأشخاص الذين يديرون أو يقومون بذات الوقت بأعمال أو أنشطة متشابهة أو مترابطة في مؤسسات\n متعددة في ما خص الضريبة على القيمة المضافة.\n عندما تقوم شرآة بمباشرة نشاط جديد أو نفس النشاط في مرآز عمل آخر ،يعتبر ذلك بمثابة فرع للشرآة وليس مباشرة\n عمل جديد ويتوجب عليها تقديم تصريح تعديل معلومات ."}, {"o": 170, "l": "المادة 47", "b": "المادة47\n مع مراعاة الأحكام القانونية التي تنص على إعفاء بعض العاملين في بعض المنظمات والهيئات من الضريبة على\n الرواتب والأجور ،تنتقل موجبات صاحب العمل غير المقيم الى المستخدم المقيم الخاضع للضريبة على الرواتب\n والأجور في ما خص هذه الضريبة .\n تحديد دقائق تطبيق\n احكام البند 1من"}, {"o": 171, "l": "المادة 33", "b": "المادة33\n من القانون\n المتعلقة بالتوقف عن العمل"}, {"o": 172, "l": "المادة 48", "b": "المادة48\n أ -يعتبر المكلف انه متوقف نهائيا عن العمل في الحالات التالية :\n ‐التوقف بسبب الوفاة.\n ‐التوقف الذي يستتبع قيام المكلف أيا آان شكله القانوني بإجراءات التصفية الذاتية لأصوله الثابتة والمتداولة وسداد\n التزاماته وإتمام إجراءات الشطب من السجل التجاري أو السجل المدني للمسجلين في أحد هذين السجلين .\n‐التوقف الذي يستتبع قيام المكلف الملزم بالانتساب الى نقابة لممارسة المهنة ،بإجراءات شطب اسمه من سجل النقابة أو\n إجراءات تحويل اسمه الى جدول المتقاعدين أو غير الممارسين.\n ‐التوقف الناتج عن حكم قضائي بسبب الافلاس أو أي سبب آخر الذي يستتبع ،قيام وآيل التفليسة أو المصفي القضائي\n بإتمام إجراءات التصفية الجبرية للأصول الثابتة والمتداولة للمكلف وسداد التزاماته وإتمام اجراءات الشطب من السجل\n التجاري ،ويعتبر تاريخ اعلان الإفلاس ،تاريخ المفلس عن العمل.\n ب -يعتبر المكلف انه متوقف مؤقتا عن العمل ،في حال الانقطاع عن العمل دون أن يستتبع ذلك الانقطاع القيام\n بالاجراءات المشار اليها في الفقرة أ من هذه المادة ،لا سيما لجهة احتفاظه برقم تسجيله في السجل التجاري أو في\n السجل المدني أو في سجل النقابة أو عدم تحويل اسمه الى جدول المتقاعدين أو غير الممارسين .وبالتالي ،يتوجب عليه\n تقديم تصريح التوقف المؤقت عن العمل خلال مهلة شهرين من تاريخ التوقف ،وذلك وفقا لنموذج تعده وزارة المالية.\n ج -يعتبر المستخدم الذي يترك عمله ،متوقفا عن العمل بالنسبة لصاحب العمل ،ويتوجب على هذا الأخير تقديم لائحة\n بأسماء المستخدمين الذين ترآوا العمل لديه الى الادارة الضريبية مع التصريح السنوي الخاص بالضريبة على الرواتب\n والأجور وفقا لنموذج تعده وزارة المالية ."}, {"o": 173, "l": "المادة 49", "b": "المادة49\n تحدد واجبات المكلفين المتوقفين عن العمل بشكل نهائي وفقا لما يلي :\n ‐1شرآات الأشخاص وشرآات الأموال بما فيها شرآات الأوف شور والشرآات القابضة )هولدنغ ):\n ‐تقديم تصريح التوقف عن العمل( النموذج م (6مرفقا به المحضر الذي تقرر خلاله التوقف عن العمل بالنسبة لشرآات\n الأموال وعقد فسخ الشراآة وحل الشرآة بالنسبة لشرآات الأشخاص .\n 57\n\f ‐تقديم آافة التصاريح الضريبية عن الفترة من أول آانون الثاني ولغاية تاريخ التوقف عن العمل وتأدية آافة الضرائب\n المتوجبة في مهلة شهرين من تاريخ هذا التوقف.\n‐تقديم تقرير مفوض المراقبة في مهلة 3أشهر من تاريخ التوقف عن العمل بالنسبة للشرآات الملزمة بتقديمه ،وفي مهلة\n شهرين من تاريخ التوقف إذا آانت أعمال التصفية قد أنجزت بتاريخ التوقف .\n ‐إذا آانت الشرآة المتوقفة عن العمل شرآة أشخاص وآان أحد الشرآاء فيها مستمرا في العمل منفردا أو في شرآة\n أشخاص أخرى ،يتوجب عليه التصريح عن حصته من نتيجة الشرآة المتوقفة عن العمل ضمن تصريحه السنوي.\n ‐إذا آانت الشرآة بعد توقفها عن العمل لا تزال تملك أصولا ثابتة أو مخزونا ،تحول على نظام الضرائب الى وضع\n \"شرآة قيد التصفية\" ،وتحدد لها سنة مالية خاصة تبدأ من تاريخ التوقف عن العمل وتنتهي في اليوم المقابل من السنة\n التالية.\n ‐إذا تجاوزت مدة التصفية هذه السنة المالية الخاصة وجب على المصفي أن يضع الميزانية السنوية وتأدية الضرائب\n المتوجبة عن تلك السنة خلال المهلة القانونية للتصريح ) 3أشهر أو 5أشهر بحسب الشكل القانوني للشرآة( وذلك من\n تاريخ إنتهاء السنة المالية الخاصة ،وتقديم تقرير مفوض المراقبة ضمن المهلة القانونية .\n ‐إذا أنجزت أعمال التصفية ،ووافقت الجمعية العمومية في الشرآات المساهمة وجمعية أصحاب الحصص في الشرآات\n المحدودة المسؤولية وفي شرآات الأشخاص على نتيجة التصفية يبقى متوجبا تقديم التصريح بعدم مزاولة العمل سنويا"}, {"o": 174, "l": "المادة 49", "b": "الى حين شطبها من السجل التجاري .\n ‐إعلام الوحدة المالية المختصة عند شطب الشرآة من السجل التجاري.\n ‐2الأشخاص الحقيقيون المكلفون على أساس الربح الحقيقي أو المقطوع ويملكون مؤسسة تجارية مسجلة في السجل\n التجاري:\n ‐تقديم تصريح التوقف عن العمل )النموذج م).6\n ‐تقديم آافة التصاريح الضريبية عن الفترة من أول آانون الثاني ولغاية تاريخ التوقف عن العمل وتأدية آافة الضرائب\n المتوجبة في مهلة شهرين من تاريخ هذا التوقف ،إلا إذا آان المكلف مستمرا في العمل بصفة فردية أو بصفة شريك في\n شرآة أشخاص فيتوجب عليه التصريح عن حصته من نتيجة المؤسسة المتوقفة عن العمل ضمن تصريحه السنوي حيث\n هو مستمر في ممارسة عمله.\n ‐يبقى متوجبا تقديم التصريح بعدم مزاولة العمل سنويا الى حين شطب المؤسسة من السجل التجاري.\n ‐إعلام الوحدة المالية المختصة عند شطب المؤسسة من السجل التجاري.\n ‐3الأشخاص الحقيقيون المكلفون على أساس الربح الحقيقي أو المقطوع )أصحاب المهن الحرة أو أصحاب المؤسسات\n التجارية غير المسجلة في السجل التجاري ):\n ‐تقديم تصريح التوقف عن العمل( النموذج م).6\n ‐تقديم آافة التصاريح الضريبية عن الفترة من أول آانون الثاني ولغاية تاريخ التوقف عن العمل وتأدية آافة الضرائب\n المتوجبة في مهلة شهرين من تاريخ هذا التوقف ،إلا إذا آان المكلف مستمرا في العمل بصفة فردية أو بصفة شريك في\n شرآة أشخاص فيتوجب عليه التصريح عن حصته من نتيجة المؤسسة المتوقفة عن العمل ضمن تصريحه السنوي حيث\n هو مستمر في ممارسة عمله.\n ‐4أصحاب المهن الحرة الملزمون بالانتساب الى نقابة :\n ‐إذا آان التوقف عن العمل بسبب إشغال وظيفة في القطاع العام أو الخاص) ( تحظر عليهم ممارسة نشاطهم الخاضع\n لضريبة الباب الأول ،فلا يتوجب عليهم تقديم التصريح السنوي بعدم مزاولة العمل بعد التوقف."}, {"o": 175, "l": "المادة 49", "b": "‐إذا آان التوقف عن العمل بسبب السفر يتوجب عليهم تقديم تصريح عدم مزاولة العمل سنويا ضمن المهلة القانونية .\n ‐5المكلفون على أساس الربح المقدر :\n ‐تقديم تصريح التوقف عن العمل( النموذج م). 6\n ‐تسديد الضرائب المتوجبة عليهم .\n ‐تقديم آافة التصاريح الضريبية في حال وجودها.\n ‐6التوقف عن العمل بسبب وفاة المكلف الشريك في شرآة أشخاص أو الذي آان يمارس العمل بصورة مستقلة :\n ‐تقديم تصريح التوقف عن العمل للمتوفى )النموذج م (6من قبل الورثة مع التصريح عن حصة المتوفى من نتيجة\n 58\n\f أعمال الشرآة ضمن مهلة شهرين من تاريخ الوفاة وآذلك تقديم آافة التصاريح الضريبية عن الفترة الممتدة من نهاية\n الفترة الضريبية السابقة التي تم التصريح عنها ولغاية تاريخ الوفاة اذا آان مكلفا على أساس الربح المقطوع أو الربح\n المقدر.\n ‐7الأشخاص المعفيون من الضريبة على الأرباح من غير الشرآات :\n ‐تقديم تصريح التوقف عن العمل )النموذج م).6\n‐تقديم آافة التصاريح الضريبية عن الفترة من أول آانون الثاني ولغاية تاريخ التوقف عن العمل وتأدية آافة الضرائب\n المتوجبة في مهلة شهرين من تاريخ هذا التوقف ."}, {"o": 176, "l": "المادة 50", "b": "المادة50\n تطبق أحكام هذا القرار على الورثة ،الذين يتوجب عليهم أن يقدموا المعلومات والبيانات اللازمة لفرض الضريبة في\n مدة شهرين من تاريخ الوفاة.\n آما تطبق أحكام هذا القرار على المصفين القضائيين ووآلاء التفليسة عند وقوع الافلاس ،وعندئذ تبدأ المهلة من تاريخ\n صدور القرار بتعيينهم ."}, {"o": 177, "l": "المادة 51", "b": "المادة51\n يرفق بتصريح التوقف عن العمل المعلومات والمستندات المثبتة لصحته واللازمة لتحديد الربح الخاضع للضريبة\n وعلى الأخص المستندات التالية :\n ‐في حال البيع :عقد البيع أو التنازل عن المأجور .\n ‐في حال الإفلاس :حكم الأفلاس .\n ‐حلول الأجل المحدد للشرآة أو إرادة الشرآاء/المساهمين :\n ‐نظام الشرآة الذي يبين مدة الشرآة في حال آان التوقف بسبب حلول الأجل المعين للشرآة .\n ‐محضر قرار الشرآاء بالتوقف عن العمل في حالة شرآات الأشخاص.\n ‐محضر الجمعية العمومية غير العادية بالتوقف عن العمل في حالة شرآات الأموال.\n ‐في حال التصفية :تقرير المصفي.\n ‐في حال الوفاة :وثيقة وفاة.\n ‐في حال استملاك آامل المؤسسة :قرار الاستملاك.\n ‐في حال الإندماج :عقد الإندماج.\n ‐في حال الأشخاص المعفيين من الضريبة على الأرباح من غير الشرآات :\n ‐قرار سحب العلم والخبر.\n ‐النظام التأسيسي إذا آان يتضمن أجلا معينا ،وآان التوقف بسبب حلول هذا الأجل.\n ‐القرار المتخذ بالتوقف عن العمل ."}, {"o": 178, "l": "المادة 52", "b": "المادة52\nعلى الإدارة الضريبية أن تنجز التدقيق بملف المكلف المتوقف نهائيا عن العمل خلال فترة أربعة أشهر من تاريخ تبلغ\n تصريح التوقف عن العمل والمرفق بكامل المستندات والمعلومات اللازمة لتحديد الربح الخاضع للضريبة .\n 59"}, {"o": 179, "l": "المادة 53", "b": "المادة53\n يتوجب على المكلف الذي يتقدم بتصريح توقف نهائي عن العمل الاستمرار بتقديم تصريح عدم المزاولة سنويا ضمن\n مهلة التصريح السنوي ،وذلك بعد إنجاز عملية التصفية ولغاية الشطب من السجل التجاري أو المدني أو النقابة.\n آما يتوجب على المكلف الذي يقدم تصريح توقف مؤقت عن العمل ،تقديم تصريحه السنوي ضمن المهلة القانونية\n بالنسبة للسنة الأولى التي تم فيها الانقطاع عن العمل ،على أن يبقى ملزما بتقديم تصريح عدم المزاولة سنويا ،ضمن\n مهلة التصريح السنوي ،طيلة فترة انقطاعه عن العمل ،وذلك لحين إعلام الإدارة الضريبية بمعاودة ممارسة العمل.\n ويلزم هذا المكلف بالاحتفاظ بكافة الدفاتر والسجلات المحاسبية التي آان يستعملها بتاريخ التوقف المؤقت عن العمل\n وذلك لاستعمالها عند معاودة العمل .إن الأرصدة الافتتاحية عند معاودة العمل يجب أن تكون مطابقة لأرصدة الحسابات\n بتاريخ التوقف عن العمل ."}, {"o": 180, "l": "المادة 54", "b": "المادة54\n مع مراعاة الأحكام القانونية التي تنص على المسؤولية التضامنية ،إن تقديم تصريح التوقف عن العمل لا يلغي\n مسؤولية المكلف عن تأدية الضرائب المتوجبة عليه عن فترة ممارسته النشاط الخاضع للضريبة سواء تحققت هذه\n الضرائب أو أصبحت برسم التحصيل قبل التوقف أو بعده ."}, {"o": 181, "l": "المادة 55", "b": "المادة55\nتفرض على آل شخص لم يبلغ الإدارة الضريبية عن توقفه المؤقت أو النهائي عن العمل ضمن المهل القانونية الغرامة\n المنصوص عليها في"}, {"o": 182, "l": "المادة 108", "b": "المادة 108من القانون.\n وتفرض على المكلف الملزم بتقديم تصريح عدم المزاولة سنويا ،وذلك في حال التأخر أو عدم تقديم هذا التصريح،\n الغرامة المنصوص عليها في"}, {"o": 183, "l": "المادة 109", "b": "المادة 109من القانون ."}, {"o": 184, "l": "المادة 56", "b": "المادة56\n عندما يكون النشاط الذي آان يزاوله المكلف قبل توقفه عن العمل خاضعا لأآثر من نوع ضريبة ،يعتبر تصريح\n التوقف عن العمل شاملا لمختلف أنواع تلك الضرائب ،ويتوجب على الوحدة المالية التي قدم تصريح التوقف عن العمل\n لديها أن تعلم الوحدات المالية الأخرى بذلك التصريح.\n وبالتالي ،يعتبر تصريح التوقف النهائي عن العمل الذي يتقدم به المكلف الى الوحدة المالية المختصة التابعة لمديرية\n الواردات ،بمثابة طلب إلغاء تسجيله لدى مديرية الضريبة على القيمة المضافة .ويتوجب على مديرية الواردات إبلاغ\n مديرية الضريبة على القيمة المضافة بهذا الطلب ."}, {"o": 185, "l": "المادة 57", "b": "المادة57\nإن تقديم تصريح التوقف عن العمل لا يعفي المكلف من موجب تقديم التصاريح والبيانات الدورية العائدة للمدة الفاصلة\nبين اليوم الأخير من الفترة التي تناولها التصريح السابق بنتيجة الأعمال واليوم الذي توقف فيه عن العمل .آما وإن تقديم\n التصاريح والبيانات الدورية العائدة للمدة الفاصلة بين اليوم الأخير من الفترة التي تناولها التصريح السابق بنتيجة\n الأعمال واليوم الذي توقف فيه المكلف عن العمل ،لا يعفي المكلف من تقديم تصريح التوقف عن العمل.\n في ما يتعلق بضريبة الأملاك المبنية ،إن التصريح عن التوقف النهائي عن العمل لا يمكن اعتباره صريحا عن شغور\n 60\n\f البناء في حال آان المكلف يشغل عقارا يملكه باسمه أو باستثماره .\n تحديد دقائق تطبيق\n احكام"}, {"o": 186, "l": "المادة 34", "b": "المادة 34من القانون\n المتعلقة باعطاء رقم ضريبي موحد"}, {"o": 187, "l": "المادة 58", "b": "المادة58\n تعطي الادارة الضريبية المكلف عند تسجيله لديها رقما ضريبيا واحدا لجميع أنواع الضرائب بما فيها الرسوم\n الجمرآية والعقارية وذلك وفقا للإجراءات المحددة في هذا القرار ."}, {"o": 188, "l": "المادة 59", "b": "المادة59\n أ -تعطي الادارة الضريبية رقما ضريبيا شخصيا ) (TINواحدا :\n ‐لكل شخص حقيقي يتقدم بمعاملة لديها أو يباشر عملا بصفة فردية أو بصفة شريك في شرآة أشخاص أو يساهم أو\n يملك حصصا في شرآة أموال.\n‐لكل مستخدم يمارس عملا مأجورا ،ويكون موجب التسجيل على رب العمل إذا آان مقيما وعلى المستخدم عندما يكون\n رب عمله غير مقيم .\n ‐يعطى المكلفون الواردون أعلاه بطاقة ضريبية صادرة عن وزارة المالية.\n ب -تعطي الإدارة الضريبية رقم ضريبي شخصي ) (TINللمهنة أو المؤسسة أو الشرآة أو لأي شخص آخر سواء أآان\n يتمتع بالشخصية المعنوية أو لا يتمتع بها عندما تأخذ صفة آيان مستقل من الناحية الضريبية )شرآة محاصة ،شرآة\n فعلية (...ويسلم لهم شهادة تسجيل في وزارة المالية.\n ج -تعطي الادارة الضريبية رقم ضريبي شخصي ) (TINلكل إدارة عامة ومؤسسة عامة وبلدية واتحاد بلديات وغيرها\n من الهيئات والجمعيات ،وتسلم لهم شهادة تسجيل من وزارة المالية.\n د -يتوجب على آل شرآة أو صاحب مهنة أو مؤسسة اعتماد الرقم الضريبي الشخصي ) (TINالخاص بها لدى التعامل\nمع الغير بهذه الصفة ،آما يتوجب على آل شخص حقيقي إبراز الرقم الضريبي الشخصي الخاص به ) (TINلدى تعامله\n مع الدوائر الرسمية ."}, {"o": 189, "l": "المادة 60", "b": "المادة60\n يتوجب على الإدارات العامة تزويد مديرية المالية العامة بلوائح تتضمن أسماء العاملين المدنيين لديها )موظفين،\n متعاقدين ،مياومين (...ولوائح تتضمن تعيين العاملين المدنيين الجدد أو بنقل العاملين إلى إدارة عامة أخرى في مهلة\n أقصاها:\n ‐شهرين من تاريخ نشر هذا القرار بالنسبة للعاملين القدامى المسجلين لديها لغاية .2008/12/31\n ‐أسبوع من تاريخ مباشرة العمل بالنسبة للعاملين الجدد.\n على أن تتضمن هذه اللوائح:\n ‐الاسم الكامل )الاسم ،اسم الأب ،الشهرة ،اسم الأم)،\n ‐تاريخ الولادة ،مكان الولادة ،رقم السجل ،مكان السجل ،رقم الهوية،\n ‐تاريخ بدء العمل،\n ‐تاريخ النقل،\n ‐العنوان الشخصي،\n 61\n\f ‐رقم الهاتف الشخصي،\n ‐صفة العامل،\n ‐غيرها من المعلومات\n وذلك وفق النموذج المعد من قبل وزارة المالية ."}, {"o": 190, "l": "المادة 61", "b": "المادة61\nيتوجب على المؤسسات العامة والخاصة والبلديات واتحادات البلديات والهيئات والجمعيات وسائر الأشخاص الحقيقيين\nوالمعنويين أن يبلغوا الإدارة الضريبية أسماء جميع العاملين لديهم وفقا للنموذج المعد من قبل وزارة المالية ،وذلك خلال\n مهلة أقصاها :\n ‐شهرين من تاريخ نشر هذا القرار بالنسبة لجميع العاملين لديهم قبل نفاذ هذا القانون .\n ‐شهرين من تاريخ استخدام آل أجير جديد.\n وذلك وفق النموذج المعد من قبل وزارة المالية ."}, {"o": 191, "l": "المادة 62", "b": "المادة62\nيتوجب على الإدارة الضريبية فور ورود تلك المعلومات اليها إعطاء آل شخص رقما ضريبيا شخصيا ،وأن تعيد إلى\n الادارات العامة والمؤسسات العامة والأشخاص الحقيقيين والمعنويين لائحة بأسماء الموظفين تتضمن أرقامهم الضريبية\n الشخصية.\nتتولى الادارة الضريبية إصدار بطاقة ضريبية لكل من العاملين القدامى والجدد وايداعها الجهات المعنية تمهيدا لتوزيعها\n على أصحابها ."}, {"o": 192, "l": "المادة 63", "b": "المادة63\n يتوجب على جميع المؤسسات العامة والخاصة والبلديات واتحاد البلديات والهيئات والجمعيات وسائر الأشخاص\n الحقيقيين والمعنويين أن تعتمد رقم تسجيلها لدى وزارة المالية على آافة المستندات الصادرة عنها وأن تلتزم استعمال\n أرقام التسجيل المعطاة من وزارة المالية لمستخدميها والمتعاملين معها في مستنداتها آافة .\n تحديد دقائق تطبيق\n احكام"}, {"o": 193, "l": "المادة 38", "b": "المادة 38من القانون\n المتعلقة باصول وشروط التسجيل\n واستعمال النظام الضريبي الالكتروني\n الية التسجيل المادة ‐ 64\n 1.على المكلف الذي يرغب في التسجيل في الخدمة الالكترونية الولوج من خلال موقع وزارة المالية\n )(www.finance.gov.lbإلى الصفحة الضريبية والنقر على خدمة النظام الضريبي الالكتروني ،وتعبئة النموذج\n المعتمد للتسجيل وارساله الكترونيا.\n2.بعد التأآد من صحة المعلومات المدخلة ،تظهر صفحة تعلم المكلف باستلام وزارة المالية طلب التسجيل الذي يتضمن\n المستندات المطلوبة )لائحة مرفقة ربطا( لاستكمال عملية التسجيل .\n 3.تقوم وزارة المالية بإرسال رسالة إلكترونية إلى عنوان بريد المكلف الالكتروني ،وذلك من أجل تأآيد العنوان.\n 62\n\f 4.يتم إرسال رسالة الكترونية إلى بريد المكلف الالكتروني تتضمن رقم متابعة التسجيل الخاص به ،بالاضافة إلى\n إيصال المراجعة الذي يتضمن رقم المتابعة العائد للشرآة والمخصص لاستكمال آلية التسجيل في الخدمات الالكترونية.\n 5.يستلم المكلف إعلاما الكترونيا تحدد بموجبه دائرة قاعدة المكلفين المرآزية موعدا لزيارتها واستلام رقم التعريف\n الالكتروني\n )(e‐Pinوتورد فيه لائحة بالمستندات المطلوبة .\n 6.يقوم المكلف أو من يفوضه رسميا بالحضور إلى دائرة قاعدة المكلفين المرآزية في الموعد المحدد مصطحبا معه\n التعهد )نموذج مرفق ربطا( والمستندات المطلوبة( والتفويض الرسمي المعطى له من قبل المكلف( لاستلام المفاتيح\n الالكترونية ،وتقوم الدائرة عندئذ بالتحقق من صحتها قبل استلامها.\n7.يستلم المستخدم في مغلف خاص مقفل المفاتيح الشخصية الالكترونية ) (e‐Pinالتي تخوله الولوج إلى النظام الضريبي\n الالكتروني .\n آلية التصريح المادة ‐ 65\n ‐ 1يقوم المستخدم خلال المهل القانونية المحددة للتصاريح بتعبئة النماذج الواجب تقديمها والواردة في الصفحة"}, {"o": 194, "l": "المادة 38", "b": "المخصصة للتصاريح والبيانات الدورية أو السنوية وطلبات الاسترداد ويرسلها الكترونيا عبر النظام.\n ‐2فور استلام التصريح من قبل النظام ،يتم إرسال إيصال التصريح إلى بريد المستخدم الالكتروني مبينا عليه تاريخ\n الاستلام.\n ‐3يتوجب على المستخدم طباعة التصريح وايصال التصريح الالكتروني والاحتفاظ بهما بعد توقيعهما ،ويعتبر إيصال\n التصريح الالكتروني بمثابة إيصال رسمي باستلام التصريح ويعتبر التاريخ الوارد على الايصال بمثابة التاريخ الفعلي\n للتصريح .\n احكام عامة المادة ‐ 66\n ‐ 1على المستخدم المحافظة على المفاتيح الالكترونية الشخصية الممنوحة له بشكل دقيق وعدم البوح بها إلى أي\n شخص أو السماح له عن قصد أو إهمال بالاطلاع عليها .لا يترتب على الوزارة أية مسؤولية في حال استعمال هذا\nالنظام من قبل شخص أو عدة أشخاص حصلوا على المفاتيح الالكترونية بسبب إهمال المستخدم أو لأي سبب آخر يتعلق\n بالمستخدم.\n ‐2يعتبر استعمال المفاتيح الالكترونية الشخصية بمثابة توقيع المستخدم وله المفاعيل القانونية نفسها المترتبة على\n التوقيع ،ولا يحق له الاعتراض أو الطعن بالعمليات المنفذة بواسطتها في حال وقوع أي خلاف يتعلق بها.\n ‐3تعتبر العمليات التي تجري انطلاقا من استعمال المفاتيح الالكترونية الشخصية بمثابة إثبات نهائي وقاطع للعمليات\n التي يجريها المستخدم .\n ‐4يحق للوزارة وفقا لمقتضيات المصلحة العامة أن تستعيد الحق الذي منحته إلى المستخدم ساعة تشاء ،على أن تقوم\n بإبلاغه ذلك مع بيان الأسباب خلال مهلة ثلاثة أيام من تاريخ استعادة الحق.\n ‐5يحق للوزارة وفقا لمقتضيات المصلحة العامة أن تغير المفاتيح الالكترونية الشخصية ساعة تشاء ،على أن تقوم\nبإبلاغ المستخدم بذلك والطلب اليه الحضور لاستلام المفاتيح الجديدة في مهلة أقصاها ثلاثة أيام من تاريخ تغيير المفاتيح\n الالكترونية .\n 63\n\f تحديد دقائق تطبيق\n احكام"}, {"o": 195, "l": "المادة 42", "b": "المادة 42من القانون\n المتعلقة بمفهوم التكليف الضريبي"}, {"o": 196, "l": "المادة 67", "b": "المادة67\nإن المكلف الملزم باحتساب الضريبة المتوجبة عليه وفقا لنظام التكليف الذاتي يكون مسؤولا عن احتساب هذه الضريبة\n والتصريح عنها وتأديتها للخزينة ضمن المهل القانونية ،وذلك بموجب إشعار بالدفع المسبق ودون الحاجة الى إصدار\n إعلام ضريبي أو جدول تكليف من قبل الإدارة الضريبية ."}, {"o": 197, "l": "المادة 68", "b": "المادة68\n يخضع لنظام التكليف الذاتي الفئات التالية :\n ‐المكلفون بضريبة الدخل على أساس الربح الحقيقي والربح المقطوع في ما خص نتائج اعمالهم والضرائب التي يتم\n اقتطاعها من مستحقات الغير وتوريدها الى الخزينة.\n ‐المكلفون بضريبة الدخل على أساس الربح المقدر في ما خص الضرائب التي يتم اقتطاعها من مستحقات الغير\n وتوريدها الى الخزينة.\n ‐المكلفون الملزمون شخصيا بالتصريح عن أنفسهم وتأدية الضريبة المتوجبة عليهم ،وهم الأشخاص المقيمون الذين\n يعملون لدى رب عمل غير مقيم ،المستخدم الذي يعمل في عدة مؤسسات في آن واحد ،والمستخدم الذي يمارس في\n الوقت نفسه مهنة خاضعة لضريبة الباب الأول من قانون ضريبة الدخل أو يتقاضى من جهة أخرى معاش تقاعد أو\n تخصيصات لمدى الحياة.\n ‐الخاضعون للضريبة على القيمة المضافة.\n ‐الخاضعون لضريبة ال %5على بدلات الاقامة والطعام والشراب.\n ‐آل شخص مقيم في لبنان أدى تعامله مع شخص غير مقيم ليس له ممثلا في لبنان الى توجب الضريبة على القيمة\n المضافة وآذلك آل شخص مقيم في لبنان يستعمل فيه خدمة اآتسبها من جهة مقيمة خارج الأراضي اللبنانية.\n ‐مكلفو ضريبة الأملاك المبنية الذين تزيد إيراداتهم عن 20مليون ل.ل .في السنة عن آل عقار والملزمون بتقديم\n التصريح السنوي ."}, {"o": 198, "l": "المادة 69", "b": "المادة69\n في الحالات التي لا تندرج ضمن إطار المادة السابقة ،يكون المكلف مسؤولا عن تسديد الضريبة في مهلة محددة في\nالقانون من تاريخ حصول الواقعة )رسم الطابع المالي (...أو من تاريخ إصدار التكليف من قبل الادارة الضريبية )مكلفو\nالربح المقدر بالنسبة لارباحهم ،مكلفو ضريبة الاملاك المبنية الذين لا تزيد إيراداتهم عن 20مليون ل.ل .في السنة عن\n آل عقار ،مكلفو رسم الانتقال ...)."}, {"o": 199, "l": "المادة 70", "b": "المادة70\n في الحالات التي لم تلزم فيها القوانين الضريبية التكليف الذاتي بالضريبة ،تصدر الادارة الضريبية التكليف بموجب\n جداول تكليف أو أوامر قبض وتدونها في حساب المكلف عملا بأحكام البند الأول من"}, {"o": 200, "l": "المادة 42", "b": "المادة 42من القانون.\nتتولى فرض الضريبة التي تصدر بموجب جداول تكليف الدائرة المالية المختصة ويبرمها مدير الواردات أو من يفوضه\n بذلك.\n تتولى فرض الضريبة التي تصدر بموجب أوامر قبض الدائرة المالية المختصة ويبرمها رئيس الوحدة المالية المختصة\n 64\n\f أو من يفوضه بذلك ."}, {"o": 201, "l": "المادة 71", "b": "المادة71\n أولا -الضرائب التي يتم التكليف بها بموجب التكليف الذاتي :\n يعتبر التصريح المقدم من المكلف ،في الحالات التي ألزمت فيها القوانين الضريبية التكليف الذاتي بالضريبة ،مستند\n تكليف.\n ثانيا -الضرائب التي تصدر بموجب جداول تكليف:\n ‐أساسية :\n أ -ضريبة الدخل :هي الجداول التي تتضمن الضرائب المقدرة من الإدارة الضريبية لمكلفي الربح المقدر في ما يتعلق\n بسنة أعمال معينة.\n ب -ضريبة الأملاك المبنية :هي الجداول التي تتضمن الضرائب المتوجبة لكافة العقارات في منطقة محددة.\n ‐إضافية :وهي الجداول التي تصدرها الادارة الضريبية ،والتي تتضمن تكاليف متوجبة لم يقم المكلف بالتصريح عنها\nوتأديتها للخزينة بطريقة التكليف الذاتي والتكاليف الناتجة عن تعديل تصاريح المكلفين نتيجة درسها من الادارة الضريبية\n أو تعديل في المطرح الضريبي بالنسبة للضرائب التي تصدر بموجب جداول تكليف أساسية.\n ‐جداول تنزيل :وهي الجداول التي تنظم لتصحيح تكاليف صادرة بموجب جداول أساسية أو إضافية أو مؤداة بموجب\n تصريح وفقا لطريقة التكليف الذاتي بسبب وجود خطأ في التكليف أو بناء على إعتراض المكلف أو طلب إسترداد.\n ثالثا ‐الضرائب التي تصدر بموجب أوامر قبض:\n وهي أوامر القبض التي تتضمن التكاليف الناتجة عن دراسة تصاريح المكلف أو بناء على المعلومات المتوفرة للادارة\n الضريبية وفقا لأحكام"}, {"o": 202, "l": "المادة 42", "b": "المادة 42من القانون.\n ‐أوامر التنزيل :وهي التي تنظم لتصحيح تكاليف صادرة بموجب أوامر قبض أو مؤداة بموجب تصريح وفقا لطريقة\n التكليف الذاتي بسبب وجود خطأ في التكليف أو بناء على إعتراض المكلف أو طلب إسترداد ."}, {"o": 203, "l": "المادة 72", "b": "المادة72\n يراعى في تنظيم جداول التكليف وأوامر القبض الأصول التالية :\n ‐تخصص لتكاليف السنة الحالية لكل منطقة تكليف جداول مستقلة عن تكاليف السنوات السابقة.\n ‐تدرج التكاليف في الجداول وفقا لتسلسل أرقام العقارات فيما يتعلق بضريبة الأملاك المبنية الصادرة بموجب جداول\n أساسية وتسلسل تواريخ أوامر القبض فيما يتعلق برسم الانتقال.\n ‐تصدر جداول التكليف الاضافية وجداول التنزيل بضريبة الدخل لكل مكلف على حدة ،ويمكن للجدول أن يتضمن\n تكاليف عن عدة فترات ضريبية ،ويمنع إدراج عدة مكلفين بجدول إضافي أو جدول تنزيل واحد.\n ‐تصدر جداول التكليف الاضافية وجداول التنزيل بضريبة الأملاك المبنية لكل عقار على حدة ،ويمكن للجدول أن\n يتضمن تكاليف عن عدة فترات ضريبية ولعدة مكلفين.\n ‐تصدر أوامر القبض لكل مكلف على حدة ولكل فترة ضريبية على حدة.\n ‐عند تنظيم جداول التكليف وأوامر القبض يجب أن يشار في خانة الملاحظات الى تاريخ انتهاء مهلة الدفع وتسري\n غرامة التحصيل من اليوم التالي لانتهاء هذه المهلة.\n‐تنظم جداول التكليف الاضافية بضريبة الدخل على الأرباح التجارية والصناعية وغير التجارية )الباب الأول( للمكلفين\n من الأفراد أو الشرآاء في شرآات الأشخاص وفقا لارقامهم الضريبية الشخصية وليس لرقم المؤسسة الفردية أو\n الشرآة.\n‐تنظم جداول التكليف الاضافية بضريبة الدخل على الارباح عملا بأحكام المواد 41و 42و 43من قانون ضريبة الدخل\n في ما يتعلق بشرآات الاشخاص بإسم الشرآة ،أما المؤسسات الفردية فيصدر التكليف بإسم المكلف الشخصي ويقتضي\n 65\n\f إصدارها بصورة منفصلة عن جداول الأرباح التجارية والصناعية وغير التجارية )الباب الأول ).\n ‐تنظم جداول التكليف الاضافية بضريبة الدخل وفقا لأحكام"}, {"o": 204, "l": "المادة 45", "b": "المادة 45من قانون ضريبة الدخل فيما يتعلق بشرآات\n الأشخاص بإسم الشرآة ،أما المؤسسات الفردية فيصدر التكليف بإسم المكلف الشخصي وتصدر بصورة منفصلة عن\n جداول التكليف بضريبة الأرباح التجارية والصناعية وغير التجارية.\n ‐تنظم جداول التكاليف بضريبة الدخل على الرواتب والأجور بإسم الشرآة مهما آان شكلها القانوني أو المؤسسة\n الفردية ،أما فيما خص فرق الضريبة على الرواتب والأجور الذي يتوجب على المكلفين الملزمين بتقديم التصريح\n الشخصي )ر (8وفقا لأحكام"}, {"o": 205, "l": "المادة 53", "b": "المادة 53من قانون ضريبة الدخل فتنظم الجداول الاضافية وفقا لإسم المكلف ورقمه\n الضريبي الشخصي.\n ‐لدى تنظيم جداول التكليف بضريبة الدخل على الرواتب والأجور ،وعملا بمبدأ التكافل والتضامن ،يتم ربط التكليف\n الصادر بإسم الشرآة أو المؤسسة مع حساب الشرآاء الضريبي عبر رقم تسجيلهم الشخصي.\n‐عند تنظيم جداول التنزيل أو أوامر التنزيل يدون في خانة الملاحظات رقم جدول التكليف أو أمر القبض المراد التنزيل\n منه ونوعه وسنة التكليف أو الفترة الضريبية التي صدر فيها.\n ‐تنظم الجداول على نسختين إفراديتين )نسخة تحقق ونسخة تحصيل( ونسخة إجمالية تتضمن مجموع الايرادات\n الخاضعة للضريبة ومجموع الضريبة والغرامات الناتجة عنها.\n ‐توقع نسختا التحقق والتحصيل والجدول الإجمالي توقيعا حيا من المراقب والمراقب الرئيسي ورئيس الوحدة ويتم\n إيداعها رئيس الادارة الضريبة.\n ‐ ‐تنظم أوامر القبض على نسختين إفراديتين )نسخة تحقق ونسخة تحصيل).\n ‐ينظم بكل ضريبة تفرض بموجب جدول إضافي أو أمر قبض أو تنزل بموجب جدول تنزيل أو أمر تنزيل إعلام\n ضريبة شخصي على نسختين تدون فيه جميع المعلومات المدرجة فيه ،وتحمل هذه الاعلامات رقم مستند التكليف\n وتاريخ إبرامه ويتم إرسال نسخة من الاعلام الى المكلف وفقا للأصول وتحفظ الثانية في ملف المكلف\n ‐تنظم جميع جداول التكليف والتنزيل وأوامر القبض وأوامر التنزيل والتي يتعذر تنظيمها على الأنظمة الموضوعة من\n المرآز الالكتروني على الكومبيوتر )برنامج excelأو غيره( وفقا للأصول المبينة أعلاه ."}, {"o": 206, "l": "المادة 73", "b": "المادة73\n ترسل جداول التكليف وأوامر القبض بعد تنظيمها وفقا لما ورد أعلاه الى المرجع الصالح لإبرامها .تعاد جداول\n التكليف بعد إبرامها الى الوحدة المختصة التي قامت بتنظيمها لادراجها في حساب المكلف من قبل الدائرة المختصة ."}, {"o": 207, "l": "المادة 74", "b": "المادة74\nتودع الدائرة المختصة نسخ جداول التكليف الموقعة توقيعا حيا المشار اليها في"}, {"o": 208, "l": "المادة 73", "b": "المادة 73من هذا القرار وفقا لما يلي :\n ‐نسخة التحقق والنسخة الاجمالية :مديرية الواردات.\n ‐نسخة التحصيل :دائرة التحصيل المختصة.\n آما يمكن لدائرة التحصيل الحصول على نسخ تحصيل مبرمة الكترونيا من انظمة المكننة فور ادراجها في حساب\n المكلف.\n‐تقوم الدائرة المختصة وفور ادراج الجدول في حساب المكلف بطباعة نسخة تحقق مع نسخة اجمالية مبرمتين الكترونيا\n ومطابقتها مع النسخة الموقعة توقيعا حيا ومهرها بختم الدائرة واضافتها ضمن مستندات ملف الدرس.\n ‐تودع الدوائر المختصة مديرية الواردات بيان تحققات الدائرة الفصلية مرفقا به نسخة تحقق ونسخة اجمالية مبرمة\n الكترونيا عن آل جدول تكليف أو تنزيل ،تمهيدا لايداعه مديرية المحاسبة العامة وفقا للاصول المحددة بموجب المرسوم\n رقم. 3373/65\n 66"}, {"o": 209, "l": "المادة 75", "b": "المادة75\n تودع الدائرة المختصة نسخ اوامر القبض الموقعة توقيعا حيا المشار اليها في"}, {"o": 210, "l": "المادة 73", "b": "المادة 73من هذا القرار وفقا لما يلي :\n ‐نسخة التحقق :تحفظ في الدائرة المختصة.\n ‐نسخة التحصيل :دائرة التحصيل المختصة.\n تودع الدوائر المختصة مدير الواردات أو مدير الضريبة على القيمة المضافة ،آل في ما خصه ،بيان تحققات الدائرة\n الفصلية مرفقا به نسخة تحقق عن آل امر قبض مبرمة الكترونيا ،تمهيدا لايداعه مديرية المحاسبة العامة وفقا للاصول\n المحددة بموجب المرسوم رقم. 3373/65"}, {"o": 211, "l": "المادة 76", "b": "المادة76\nاذا تبين وجود اخطاء مادية في جداول التكليف أو اوامر القبض بعد ادراجها في حساب المكلف ،تتعلق حصرا بتدوين\n الارقام أو الاسماء أو باجراء عمليات حسابية أو بتكرار التكليف ،تتولى الدائرة المختصة اجراء التصحيحات اللازمة\nعلى انظمة المكننة بالتنسيق مع المرآز الالكتروني وتبلغ مدير الواردات أو مدير الضريبة على القيمة المضافة ،آل في\n ما خصه ،ودائرة التحصيل المختصة نسخا عن موافقة رئيس الوحدة التي تم التصحيح بموجبها ."}, {"o": 212, "l": "المادة 77", "b": "المادة77\n عند عدم تجاوب المكلف مع الموجبات التي تفرضها الادارة لجهة تقديم التصاريح أو مسك السجلات والمستندات\n المحاسبية القانونية أو اعطاء الادارة الضريبية المعلومات التي تفيد احتساب مطرح الضريبة ،تقوم الادارة باعلامه بانها\n ستعمد ،خلال مهلة شهر من تاريخ تبلغه هذا الاعلام ،الى تحديد المطرح الضريبي وذلك وفقا لاحكام البند 5من"}, {"o": 213, "l": "المادة 42", "b": "المادة\n 42من القانون وما يكون قد قدمه المكلف من تصاريح ومستندات خلال هذا الشهر.\nفي هذه الحالة وبالنسبة لمكلفي ضريبة الدخل ،تتولى لجنة الربح المقدر بموجب قرار معلل تحديد المطرح الضريبي بناء\n على اقتراح الوحدة الضريبية المختصة ،وتكون النتيجة إما صفرا أو ربحا يتوجب تكليفه بالضريبة في ما خص مكلفي\n الربح الحقيقي ،أو ربحا محددا استنادا الى معدلات الربح المقطوع في ما خص مكلفي الربح المقطوع ."}, {"o": 214, "l": "المادة 78", "b": "المادة78\n تلغى مناطق الجباية المحددة في المحافظات ويعتمد لبنان منطقة جباية وحيدة .\n تحديد دقائق تطبيق\n احكام"}, {"o": 215, "l": "المادة 49", "b": "المادة 49\n من القانون المتعلقة بنتائج تدقيق اعمال\n المكلفين الخاضعين لنظام التكليف الذاتي"}, {"o": 216, "l": "المادة 79", "b": "المادة79\n بعد انتهاء عملية التدقيق المنصوص عليها في"}, {"o": 217, "l": "المادة 44", "b": "المادة 44وما يليها من القانون ،تضع الادارة الضريبية المختصة\nتقريرا ،يتضمن النتائج الاولية للتدقيق في حال وجوب اجراء تعديلات على مطرح الضريبة ،اما اذا تبين لها عدم الحاجة\n الى اجراء أي تعديلات على المطرح الضريبي فتبلغ المكلف بذلك .\n 67"}, {"o": 218, "l": "المادة 80", "b": "المادة80\n يجب ان يكون التقرير الاولي بالنتائج معللا بحيث يتضمن :\n ‐تفصيل آل تعديل لمطرح الضريبة أو المبالغ المرفوض حسمها أو استردادها واسبابها مع قيمتها،\n ‐الاحكام القانونية والوقائع التي يرتكز عليها التكليف،\n ‐المخالفات ونسب وقيم الغرامات المترتبة على آل منها ."}, {"o": 219, "l": "المادة 81", "b": "المادة81\n تبلغ الوحدة الضريبية المختصة المكلف ،سواء آان من المكتومين أو من غير المكتومين ،النتائج الاولية للتدقيق ،على\n الشكل التالي :\n ‐في ما خص المكلف غير المكتوم ،تعتمد الاجراءات المنصوص عليها في المادتين 27و 28من القانون المتعلقتين\n بالتبليغ.\n‐في ما خص المكلف المكتوم ،يتم نشر اعلام الاقتراحات الاولية في جريدتين محليتين وعلى الموقع الالكتروني الخاص\n بوزارة المالية .\nيجب ان يتضمن الاعلام :الفترة الضريبية ،اسم المكلف وعنوانه ،الطلب الى المكلف مراجعة الوحدة الضريبية المختصة\n خلال مهلة ثلاثين يوما من تاريخ النشر من اجل النتائج الاولية ،وفي حال انقضت المهلة المذآورة ولم يراجع المكلف\n الدائرة الضريبية المختصة ،يعتبر التبليغ حاصلا بصورة صحيحة في نهاية مهلة الثلاثين يوما ."}, {"o": 220, "l": "المادة 82", "b": "المادة82\n من اجل تفادي سقوط الضرائب بعامل مرور الزمن ،يتوجب على الوحدة الضريبية المختصة:\n‐في ما خص المكلف غير المكتوم ،ان تودع النتائج الاولية للتدقيق بالبريد المضمون في مهلة اقصاها 12/31من السنة\n الرابعة بعد السنة التي تلي سنة الاعمال المعنية .\n ‐في ما خص المكلف المكتوم ،ان تنشر دعوة الاعلام في جريدتين محليتين وعلى الموقع الالكتروني الخاص بوزارة\n المالية في مهلة اقصاها 11/30من السنة السادسة بعد السنة التي تلي سنة الاعمال المعنية ."}, {"o": 221, "l": "المادة 83", "b": "المادة83\nعلى المكلف ابداء ملاحظاته على النتائج الاولية للتدقيق خطيا وارسالها الى الوحدة الضريبية المختصة خلال مهلة 30\n يوما من تاريخ تبلغه هذه النتائج.\n وفي حال آانت احدى سنوات الايرادات موضوع التدقيق سنة معرضة للسقوط بعامل مرور الزمن ،فان اعطاء هذه\n المهلة لا يؤدي إلى سقوط الضرائب موضوع هذه التكاليف بعامل مرور الزمن الا في حال تأخرت الوحدة الضريبية\n المختصة باصدار التكليف وايداعه البريد إلى ما بعد نهاية شهر من تاريخ تبلغها ملاحظات المكلف ."}, {"o": 222, "l": "المادة 84", "b": "المادة84\n في حال وافق المكلف من خلال ابداء ملاحظاته على التكليف الذي تتضمنه النتائج الاولية المبلغة اليه ،على الدائرة\n الضريبية المختصة اصدار التكليف النهائي في مهلة اقصاها شهر من تاريخ استلامها هذه الملاحظات.\n 68\n\f أما في حال لم يتقدم المكلف من الدائرة الضريبية المختصة بأية ملاحظات خلال مهلة الثلاثين يوما أو ارسل ملاحظاته\n بعد انقضاء هذه المهلة يعتبر ذلك بمثابة قبول ضمني من قبله للنتائج الاولية للتدقيق ،وعلى الوحدة الضريبية المختصة\n اصدار التكليف النهائي في مهلة اقصاها شهر من تاريخ انتهاء المهلة المنصوص عليها في"}, {"o": 223, "l": "المادة 85", "b": "المادة 85من هذا القرار"}, {"o": 224, "l": "المادة 85", "b": "المادة85\n في حال ابدى المكلف رأيا مخالفا لنتائج التدقيق الاولية ،يتوجب عليه تعليل رأيه والاشارة الى الاخطاء المادية\n والقانونية في حال وجودها ،آما يتوجب عليه ذآر النقاط القانونية أو المعلومات التي يريد الاستناد اليها وابراز\n المستندات الثبوتية لها.\n تدرس الوحدة الضريبية المختصة النقاط التي ادلى بها المكلف وفقا للمعطيات الجديدة التي يقدمها ولها ان تطلب منه\n خطيا أو شفهيا أي استيضاحات حول هذه النقاط ،وعليه اعطاءها المعلومات التي تطلبها منه ،خلال مهلة تحددها له ."}, {"o": 225, "l": "المادة 86", "b": "المادة86\n يمكن للوحدة الضريبية المختصة الرجوع آليا أو جزئيا عن نتائج التدقيق الاولية أو تعديلها اذا تبين لها ان المعطيات\n الجديدة تبرر ذلك ،آما يمكنها عدم الموافقة على جميع ملاحظات المكلف.\nويتوجب على الوحدة الضريبية المختصة اصدار التكليف النهائي ،خلال مهلة شهر من تاريخ استلامها هذه الملاحظات،\n على ان يتضمن هذا التكليف ردا معللا على ملاحظات المكلف ."}, {"o": 226, "l": "المادة 87", "b": "المادة87\n في ما خص المكلف المكتوم ،وفي حال لم يراجع الوحدة الضريبية المختصة خلال مهلة شهر من تاريخ نشر الاعلام\n المذآور في"}, {"o": 227, "l": "المادة 83", "b": "المادة 83من هذا القرار ،تعمد هذه الوحدة الى اصدار التكليف النهائي خلال مهلة شهر من تاريخ انتهاء\nمهلة ابداء الملاحظات على النتائج الاولية للتدقيق ،وتعمد الى تبليغ المكلف عن طريق النشر في جريدتين محليتين وعلى\nالموقع الالكتروني الخاص بوزارة المالية ،ويعتبر المكلف مبلغا اعتبارا من اول يوم عمل يلي تاريخ هذا النشر ،ويحق له\n بالتالي ان يتقدم بالاعتراض على التكليف خلال مهلة شهرين من تاريخ التبليغ ."}, {"o": 228, "l": "المادة 88", "b": "المادة88\n في حال آانت احدى سنوات الايرادات موضوع التدقيق هي سنة معرضة للسقوط بعامل مرور الزمن ،فان مهلة\n الشهر الاضافي لا تؤدي الى سقوط الضرائب موضوع التكاليف بعامل مرور الزمن الا في حال تأخرت الوحدة\n الضريبية المختصة باصدار التكاليف وايداعه البريد الى ما بعد نهاية شهر من تاريخ تبلغها ملاحظات المكلف ."}, {"o": 229, "l": "المادة 89", "b": "المادة89\n يتضمن تقرير التكليف النهائي المعلومات التالية :\n ‐1تاريخ بدء وانتهاء عملية التدقيق.\n ‐2الفترات التي شملتها عملية التدقيق.\n ‐3نوع التدقيق المنفذ )شامل ،موجه (...،والضرائب التي شملها.\n ‐4التعديلات الجارية على تصريح المكلف.\n ‐5الوقائع والنقاط القانونية المستند اليها التكليف.\n 69\n\f ‐6اسباب رفض ملاحظات المكلف على النتائج الاولية ،في حال وجودها.\n ‐7تحديد مطرح الضريبة واحتساب قيمتها والغرامات المتوجبة عن آل فترة تم تدقيقها.\n ‐8اسماء الموظفين المولجين بعملية التدقيق وتوقيعهم ."}, {"o": 230, "l": "المادة 90", "b": "المادة90\n يبلغ المكلف النتائج النهائية للتدقيق بموجب اعلام ضريبي.\n يتضمن الاعلام الضريبي ما يلي :\n 1.رقم وتاريخ الاعلام.\n 2.اسم المكلف وعنوانه.\n 3.رقمه الضريبي.\n 4.اسباب التعديلات والتكليف على ان تكون مفصلة لناحية المخالفات الحاصلة والمواد القانونية أو التعليمات الادارية\n التي ترعى هذه المخالفات.\n 5.المبالغ الخاضعة للضريبة مع تحديد الفترات الضريبية العائدة لها.\n 6.قيمة الضريبة والفوائد والغرامات المتوجبة.\n 7.طلب تسديد المبالغ المتوجبة ضمن المهلة القانونية وبيان طرق التسديد الجائز اعتمادها.\n 8.مهل الاعتراض على الضرائب المتوجبة.\n 9.توقيع الموظف المختص.\n 10.توقيع رئيس الادارة الضريبية.\n يرفق بهذا الاعلام مستند التحصيل الذي يتضمن الضرائب والغرامات المتوجبة في حال وجودها ."}, {"o": 231, "l": "المادة 91", "b": "المادة91\n تطبق احكام المواد اعلاه المتعلقة بنتائج تدقيق اعمال المكلفين على المكلفين الخاضعين لنظام التكليف الذاتي\n بالضريبة .\n تحديد دقائق تطبيق\n احكام"}, {"o": 232, "l": "المادة 57", "b": "المادة 57\n من القانون المتعلقة\n بطرق تسديد الضريبة"}, {"o": 233, "l": "المادة 92", "b": "المادة92\n تؤدى الضريبة المتوجبة وفقا لطريقة التكليف الذاتي دفعة واحدة ،اما الضريبة الاضافية فتؤدى دفعة واحدة أو\n بالتقسيط ،اذا اجاز القانون ذلك ،بناء على موافقة مدير المالية العام المسبقة ."}, {"o": 234, "l": "المادة 93", "b": "المادة93\nتسدد دفعات الضريبة اما نقدا أو بشك مصرفي مسحوب لصالح أمين صندوق الخزينة المرآزي أو بتحويل مصرفي .\n 70"}, {"o": 235, "l": "المادة 94", "b": "المادة94\n يتوجب على المكلف ،الملزم بالتصريح وفقا لطريقة التكليف الذاتي ،احتساب الضريبة المتوجبة عليه ويكون مسؤولا\n عن التصريح عنها وتأديتها ضمن المهل القانونية ،وذلك بموجب نموذج اشعار دفع معد من قبل وزارة المالية ."}, {"o": 236, "l": "المادة 95", "b": "المادة95\n تؤدى الضرائب والرسوم الخاضعة لطريقة التكليف الذاتي الدورية والسنوية ،فقط لدى أي من المصارف الخاصة أو\n فروعها العاملة في لبنان أو لدى أي من المكاتب التابعة لشرآة ليبان بوست أو أي شرآة اخرى تتعاقد معها وزارة\n المالية لهذا الغرض .\n أما الضرائب غير الخاضعة لطريقة التكليف الذاتي والضرائب الاضافية ،فتؤدى بموجب نموذج معد من وزارة المالية\n لدى أي من المصارف أو فروعها العاملة في لبنان أو لدى صناديق الخزينة المختصة أو لدى أي من المكاتب التابعة\n لشرآة ليبان بوست أو أي شرآة اخرى تتعاقد معها وزارة المالية لهذا الغرض ."}, {"o": 237, "l": "المادة 96", "b": "المادة96\n تعتبر الضريبة مسددة في اليوم الذي تسدد فيه قيمتها آاملة من قبل المكلف أو المقتطع ،ويعتبر التقسيط الموافق عليه\n بمثابة تسديد للضريبة .\nعند تسديد الضريبة بموجب حوالة مصرفية ،تعتبر الضريبة مدفوعة بتاريخ تنفيذ الحوالة المدون على الايصال الصادر\n عن المصرف ."}, {"o": 238, "l": "المادة 97", "b": "المادة97\n أولا -الضرائب والرسوم التي تؤدى فقط لدى المصارف أو فروعها أو لدى أي من مكاتب شرآة ليبان بوست أو لدى\n مكاتب أي شرآة اخرى تتعاقد معها وزارة المالية.\n ‐ضريبة الدخل المحتسبة وفقا لطريقة التكليف الذاتي :ضريبة الدخل على الارباح\n ‐الضريبة على الرواتب والاجور( التصريح الدوري السنوي( -الضريبة على رؤوس الاموال المنقولة وفوائد الديون\n التأمينية .\n ‐ضريبة الاملاك المبنية المحتسبة وفقا لطريقة التكليف الذاتي.\n ‐الضريبة على القيمة المضافة.\nثانيا -الضرائب والرسوم التي يمكن تأديتها لدى المصارف أو فروعها أو لدى أي من مكاتب شرآة ليبان بوست أو لدى\n مكاتب أي شرآة اخرى تتعاقد معها وزارة المالية أو لدى صناديق الخزينة :\n ‐الضريبة الاضافية.\n ‐الضرائب والرسوم التي تفرض بموجب امر قبض.\n ‐المبالغ المؤداة على حساب الضرائب المتوجبة.\n ‐الضريبة الصادرة بموجب جداول تكليف اساسية ."}, {"o": 239, "l": "المادة 98", "b": "المادة98\nفي حال قيام المكلف بتسديد الضريبة لدى صناديق الخزينة يقوم امين الصندوق بتسليم المكلف ايصالا بتسديد الضريبة\n وفقا لنموذج معد من وزارة المالية.\n 71\n\f اما الضرائب المسددة لدى المصارف أو فروعها أو لدى أي من مكاتب شرآة ليبان بوست أو لدى مكاتب أي شرآة\n اخرى تتعاقد معها وزارة المالية ،لحساب الخزينة ،فتحدد آلية معالجتها بقرار يصدر عن وزير المالية .\n تحديد دقائق تطبيق\n احكام"}, {"o": 240, "l": "المادة 59", "b": "المادة 59\n من القانون\n المتعلقة بتوزيع المبالغ المدفوعة"}, {"o": 241, "l": "المادة 99", "b": "المادة99\n تسدد المبالغ التي يؤديها المكلف على حساب الضرائب المتوجبة عليه نقدا أو بموجب شك مصرفي لصالح أمين\n صندوق الخزينة المرآزي ."}, {"o": 242, "l": "المادة 100", "b": "المادة100\nتدفع المبالغ التي يؤديها المكلف على حساب الضرائب المتوجبة عليه ،وفقا لنموذج معد من وزارة المالية ،في صندوق\nالخزينة أو لدى أي من المصارف أو فروعها أو لدى أي من مكاتب شرآة ليبان بوست أو أي شرآة اخرى تتعاقد معها\n وزارة المالية لهذا الغرض ويتم تسليمه ايصالا بايداع المبالغ ."}, {"o": 243, "l": "المادة 101", "b": "المادة101\n عند قيام المكلف بتأدية دفعة على حساب الضرائب المتوجبة عليه تزيد عن قيمة الضريبة الخاصة بفترة ضريبية\nواحدة ،تعتبر الدفعة تسديدا للفترة الضريبية المعنية والباقي دفعة على حساب ضرائب الفترات الضريبية الاخرى ،وذلك\n عملا باحكام البند 2من"}, {"o": 244, "l": "المادة 54", "b": "المادة 54من القانون ،على ان تحتسب غرامة التحصيل على الرصيد المتوجب ."}, {"o": 245, "l": "المادة 102", "b": "المادة102\n عند تسديد المكلف لاية مبالغ على حساب الضرائب المتوجبة عليه ،وعندما تكون قيمة تلك المبالغ غير آافية لتسديد\n آامل قيمة الضريبة المتوجبة ،توزع المبالغ المسددة من قبله وفقا للقاعدة التالية:\n اولا الفائدة ثم غرامات التأخير في الدفع المستحقة لغاية تاريخ الدفع ثم غرامات التحقق ان وجدت وبعدها مبالغ\n الضريبة ،وتتابع اجراءات التحصيل القانونية في ما خص رصيد المبالغ المتبقية على المكلف بعد عملية الدفع.\n وعند تسديد الرصيد المتبقي ،تحتسب غرامة التأخير في الدفع على الرصيد المتبقي اعتبارا من تاريخ عملية الدفع\n الاخيرة ."}, {"o": 246, "l": "المادة 103", "b": "المادة103\n في حال وجود تخفيض للغرامات مقرر من وزارة المالية ،يستفيد المكلف من تخفيض الغرامات الذي يكون ساريا\n بتاريخ تسديد آامل الضريبة )الضريبة +الفوائد +الغرامات ).\n أما في حال آان المبلغ المسدد اقل من الضريبة المتوجبة ،فيسجل هذا المبلغ امانة لدى الخزينة لحين تسديد آامل\nالضريبة المتوجبة ،على ان يستفيد المكلف من تخفيض الغرامات النافذ بتاريخ تسديد الضريبة المتوجبة في حال وجوده .\n 72"}, {"o": 247, "l": "المادة 104", "b": "المادة104\n في حال وجود ضريبة متوجبة معرضة للسقوط بعامل مرور الزمن يحق للادارة استعمال المبالغ المؤداة على حساب\n الضرائب المتوجبة لتحصيل هذه الضريبة دون التقيد بالتوزيع الوارد من المكلف .\n تحديد دقائق تطبيق\n احكام"}, {"o": 248, "l": "المادة 61", "b": "المادة 61من القانون المتعلقة\n بتقسيط دفع الضريبة"}, {"o": 249, "l": "المادة 105", "b": "المادة105\n مع مراعاة الاحكام المتعلقة بتقسيط رسم الانتقال الواردة في المرسوم الاشتراعي رقم ، 146/59يحق للمكلف التقدم\n من الادارة الضريبية بطلب تقسيط الضريبة الاضافية المتوجبة عليه مهما آان نوعها باستثناء الضرائب المقتطعة عند\n المنبع والضريبة على القيمة المضافة والضرائب غير المباشرة شرط ان تتجاوز قيمة المبلغ المطلوب تقسيطه\n 000,000,1ل.ل) .مليون ليرة لبنانية( للافراد و000,000,3ل.ل( .ثلاثة ملايين ليرة لبنانية( للشرآات ."}, {"o": 250, "l": "المادة 106", "b": "المادة106\n مع مراعاة صلاحية مدير المالية العام باصدار قرار يحدد بموجبه الشروط اللازمة للموافقة على طلبات تقسيط\n الضريبة ،تحدد اجراءات معالجة هذه الطلبات وفقا لما يلي :\n ‐1يتقدم المكلف أو من يمثله بطلب خطي لتقسيط الضريبة إلى دائرة التحصيل المختصة أو إلى اقسام خدمات المكلفين\n في الاقضية وفق نموذج معد من قبل وزارة المالية يبين فيه اسم المكلف ورقمه الضريبي وعنوانه آاملا والمبلغ\n الاجمالي المطلوب تقسيطه ونوع الضريبة.\n ‐2يرفق بطلب تقسيط الضريبة :\n‐تعهد من صاحب العلاقة ،وفق نموذج معد من قبل وزارة المالية ،بمراجعة دائرة التحصيل المختصة لتبلغ قرار الادارة\n في نهاية المهلة القانونية المحددة.\n ‐صورة عن الوآالة القانونية في حال توجبها.\n ‐صورة عن الاعلام الضريبي.\n ‐المستندات المثبتة لامتلاك اموال منقولة أو غير منقولة وقيمها ،على ان تساوي على الاقل ضعفي قيمة الضريبة\n المطلوب تقسيطها ،مختارة من قبل المكلف لغايات وضع اشارة التقسيط.\n ‐صورة عن الاذاعة التجارية أو السجل التجاري للشرآات في حال وجودها.\n ‐3تستلم دائرة التحصيل المختصة طلب تقسيط الضريبة مرفقا بالمستندات المبينة اعلاه وتسجله في نظام معلوماتية\n خاص بطلبات التقسيط يمسك لهذه الغاية.\n‐4يتسلم صاحب العلاقة أو من يمثله ايصالا صادرا عن دائرة التحصيل المختصة مبين فيه رقم وتاريخ الاستلام وتاريخ\n المراجعة اللاحقة المحددة بعشرة ايام عمل تلي تاريخ تقديم الطلب لتبلغ قرار الادارة.\n ‐5تتولى دائرة التحصيل المختصة دراسة الطلب وتحيله مع اقتراحها المعلل بالقبول أو بالرفض إلى رئيس الادارة\n الضريبية بالتسلسل الاداري ،مرفقا بافادة عن انواع الضرائب والرسوم المستحقة على المكلف لغاية تاريخ تقديم الطلب\n مع ذآر نوع ورقم وتاريخ مستند التكليف.\n ‐6يرفع رئيس الادارة الضريبية الطلب إلى مدير المالية العام مع اقتراحه المعلل بالقبول أو بالرفض."}, {"o": 251, "l": "المادة 106", "b": "‐7يبت مدير المالية العام بطلب التقسيط ويعيده إلى دائرة التحصيل المختصة.\n 73\n\f ‐8تقوم دائرة التحصيل المختصة ،بعد تبلغها قبول أو رفض طلب التقسيط بما يلي :\n أ -في حال رفض الطلب:\n ابلاغ المكلف شخصيا بقرار الرفض وأسبابه.\n ب -في حال الموافقة على الطلب :\n ‐ابلاغ المكلف شخصيا بقرار قبول طلب التقسيط فور استلام القرار.\n‐وضع برنامج التقسيط :قيمة الدفعة الاولى ،مدة التقسيط ،معدل الفائدة ،عدد الاقساط وقيمة آل منها على الا تتجاوز مدة\n التقسيط ثلاث سنوات ،وذلك خلال مهلة يومي عمل من تاريخ تبلغ المكلف قرار القبول.\n ‐ادخال المعلومات الواردة في الطلب على نظام المعلوماتية الخاص بطلبات التقسيط لادارة عملياته.\n ‐اصدار بيان تقسيط ،وفق نموذج معد من قبل وزارة المالية يوقعه المكلف بالموافقة عليه ،واشعار قبض الدفعة الاولى\n واشعارات قبض الاقساط المتبقية.\n ‐وضع اشارة تقسيط على اموال المكلف المنقولة وغير المنقولة بمبلغ يعادل ضعفي قيمة الضريبة المقسطة على الاقل .\n واجبات المكلف المادة ‐ 107\n ‐ 1استلام اشعار قبض الدفعة الاولى ،وسداد قيمتها في مهلة اسبوع من تاريخ تبلغه الاشعار على ان لا تتعدى نهاية\n الشهر الذي تمت فيه الموافقة على التقسيط في صندوق الخزينة أو لدى احد المصارف أو فروعها أو في احد مكاتب\n شرآة ليبان بوست أو أي شرآة اخرى تتعاقد معها وزارة المالية لهذا الغرض وتسليم دائرة التحصيل نسخة الادارة من\n اشعار القبض ،واستلام بيان التقسيط واشعارات قبض الاقساط الباقية لقاء توقيعه على نسخة البيان المذآور اشعارا\n بالقبول والاستلام.\n ‐2تسديد قيمة الاقساط المتبقية في التواريخ المحددة لها في جدول التقسيط وذلك تحت طائلة استحقاق آامل الاقساط.\n ‐3في الحالات التي يسري خلالها تخفيض معين للغرامات ،يستفيد المكلف من التسوية شرط تسديد الدفعة الاولى من\n الضريبة المقسطة خلال المهلة المحددة لتخفيض الغرامات ."}, {"o": 252, "l": "المادة 108", "b": "المادة108\n في حال تخلف المكلف عن دفع أي قسط من الاقساط بتاريخ استحقاقه ،تستحق آامل الاقساط مع فوائدها لغاية تاريخ\n استحقاق القسط الذي تخلف عن دفعه ،وتفرض غرامة تحصيل على قيمة آامل المبالغ المستحقة مع الفوائد المترتبة\n لتاريخ القسط الذي تمنع المكلف عن سداده ،وذلك ابتداء من تاريخ استحقاق القسط الذي تخلف عن دفعه ولغاية تاريخ\n الدفع الفعلي مع احتفاظ المكلف بحقه بتخفيض الغرامات الذي استفاد منه استنادا الى النص النافذ بتاريخ التقسيط ."}, {"o": 253, "l": "المادة 109", "b": "المادة109\n تعتبر دائرة التحصيل المعنية مسؤولة عن :\n ‐تدوين رقم طلب التقسيط وتاريخ الموافقة عليه على نسخ مستندات التكليف الالكترونية.\n ‐تخفيض قيمة الضريبة المقسطة من المبالغ المتوجبة على المكلف في حسابه.\n ‐تنظيم وضعية خاصة بالمبالغ المقسطة لكل ضريبة على حدة يحدد فيها مجموع المبالغ المقسطة والمبالغ المسددة من\n اصلها والمبالغ الباقية قيد التحصيل .\n وضع اشارة التقسيط المادة ‐ 110\nيتوجب على دائرة التحصيل المختصة الطلب من المديرية العامة للشؤون العقارية ،فور اصدار بيان التقسيط وبموجب\n 74\n\f آتاب ،وضع اشارة تقسيط بمبلغ يعادل ضعفي قيمة المبالغ المقسطة ،على عقارات محددة يملكها المكلف وفقا للتراتبية\n المحددة من قبله في طلب تقسيط الضريبة .\n آما يتوجب على دائرة التحصيل المختصة الطلب من السجل التجاري ،فور اصدار بيان التقسيط ،وضع اشارة تقسيط\n على السجل التجاري للمكلف )في حال وجوده( ،بمبلغ يعادل ضعفي قيمة المبالغ المقسطة على الاقل.\n تقوم المديرية العامة للشؤون العقارية وامانة السجل التجاري المختصة بابلاغ وحدة التحصيل بوضع الاشارة بموجب\n آتاب يضم الى ملف التقسيط.\n تقوم دائرة التحصيل عند تسديد آامل الاقساط المتوجبة بتوجيه آتاب رفع اشارة تقسيط الى المديرية العامة للشؤون\n العقارية أو الى امانة السجل التجاري المختصة ."}, {"o": 254, "l": "المادة 111", "b": "المادة111\n اذا طلب المكلف تسديد آامل الرصيد المتبقي دفعة واحدة يصار الى اصدار ايصال تحصيل بقيمة اصل المبلغ\n المتوجب مضافا اليه الفائدة المترتبة عن الفترة الممتدة من تاريخ تسديد آخر قسط لغاية تاريخ الدفع الفعلي مع اعتبار\n آسر الشهر شهرا آاملا ."}, {"o": 255, "l": "المادة 112", "b": "المادة112\n تقوم دائرة التحصيل المختصة بوضع اشارة تقسيط على الاموال المنقولة وغير المنقولة وفقا لما جاء سابقا المتعلقة\n بطلبات التقسيط الموافق عليها قبل تاريخ نشر هذا القرار .\n تحديد دقائق\n تطبيق احكام"}, {"o": 256, "l": "المادة 105", "b": "المادة 105\n من القانون المتعلقة بحصول مخالفة\n مشترآة بين عدة ضرائب"}, {"o": 257, "l": "المادة 113", "b": "المادة113\n عند حصول مخالفة تتناول مستندا أو عدة مستندات مشترآة بين عدة ضرائب تطبق الغرامة الاعلى على فرق\nالضريبة .وفي حال حصول عدة مخالفات تتعلق بضريبة واحدة ،تطبق على آل مخالفة الغرامة المحددة لها في القانون ."}, {"o": 258, "l": "المادة 114", "b": "المادة114\n يقصد بحصول مخالفة تتناول مستندا أو عدة مستندات مشترآة بين عدة ضرائب ،جميع المخالفات التي يتكرر فرض\n الغرامة عليها في اآثر من قانون ضريبة .\n ولا يعتبر مخالفة تتناول مستندا أو عدة مستندات مشترآة ،التأخر أو عدم التقدم بالتصاريح أو البيانات المطلوبة ،أو\n تسديد الضرائب المتوجبة عنها ،حيث يتوجب على آل مخالفة الغرامة الناتجة عنها ."}, {"o": 259, "l": "المادة 115", "b": "المادة115\n في حال آانت المخالفة المذآورة تؤثر على المطرح الضريبي ،تطبق الدائرة المالية المختصة التي اآتشفت المخالفة\n الغرامة المحددة لها في القانون.\n 75\n\f وعلى هذه الدائرة ان توثق الغرامة المذآورة على نظام المكننة المعتمد ،وتقوم بأرشفتها ،تسهيلا لامكانية التكليف بفرق\n الغرامة عند تدقيق ضريبة اخرى .\n احكام عامة"}, {"o": 260, "l": "المادة 116", "b": "المادة116\n تلغى جميع القرارات والتعاميم والمذآرات والتعليمات التي لا تأتلف مع احكام هذا القرار ."}, {"o": 261, "l": "المادة 117", "b": "المادة117\n ينشر هذا القرار في الجريدة الرسمية وعلى الموقع الالكتروني الخاص بوزارة المالية ،ويعمل به من تاريخ نشره.\nوزير المالية\nد .محمد شطح\n 76"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (98,'قوانين','قانون الحق في الوصول الى المعلومات قانون رقم 28 - 10 شباط 2017','2017-02-10','https://www.ppa.gov.lb/ar/pages/details/98','{"https://admin.ppa.gov.lb/storage/listing-pages/files/MHaeZejU7Dxb02BKtm3KHVoYR6jTYhBXB31W-1760210821.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/MHaeZejU7Dxb02BKtm3KHVoYR6jTYhBXB31W-1760210821.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=98),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "قانون الحق في الوصول الى المعلومات\n كما اقرته الهيئة العامة لمجلس النواب\n الفصل األول :أحكام عامة\n المادةاالولى :المستفيدون من هذا القانون:\n يحق لكل شخص ،طبيعي او معنوي ،الوصول الى المعلومات والمستندات الموجودة لدى اإلدارة واالطالع عليها ،وفقا ألحكام\n هذا القانون ،مع مراعاة عدم االساءة في استعمال الحق.\n المادة :2تعريف االدارة:\n يقصد باإلدارة بمفهوم هذا القانون:\n الدولة وإداراتها العامة. -1\n -2المؤسسات العامة.\n الهيئات االدارية المستقلة. -3\nالمحاكم والهيئات والمجالس ذات الطابع القضائي او التحكيمي ،العادية واألستثنائية ،بما فيها المحاكم العدلية واالدارية -4\n والمالية دون المحاكم الطائفية.\n البلديات واتحادات البلديات. -5\n المؤسسات والشركات الخاصة المكلفة بإدارة مرفق او ملك عام. -6\n الشركات المختلطة. -7\n المؤسسات ذات المنفعة العامة. -8\n سائر اشخاص القانون العام. -9\n - ٠١الهيئات الناظمة للقطاعات واإلمتيازات\n المادة :3المستندات االدارية:\nتعتبر مستندات إدارية ،بمفهوم هذا القانون ،المستندات الخطية والمستندات اإللكترونية والتسجيالت الصوتية والمرئية -1\n والبصرية والصور وكل المستندات القابلة للقراءة بصورة آلية ،مهما كان شكلها او مواصفاتها ،التي تحتفظ بها االدارة.\n تعد مستندات ادارية على سبيل المثال ال الحصر: -2\n الملفات والتقارير والدراسات والمحاضر واإلحصاءات . -1\n األوامر والتعليمات والتوجيهات والتعاميم والمذكرات والمراسالت واالراء والقرارات الصادرة عن االدارة . -2\n\f العقود التي تجريها االدارة. -3\n -4وثائق المحفوظات الوطنية.\n المادة :4المستندات االدارية المتعلقة بمعلومات ذات طابع شخصي:\n -1يحق لصاحب العالقة دون سواه الوصول الى الملفات الشخصية وأي تقرير تقييمي يتعلق بشخص طبيعي مشار إليه باالسم أو\n برقم تعريفي او برمز او بأي وصف تعريفي آخر كبصمات االصابع اوالعين او الصوت او الصورة."}, {"o": 1, "l": null, "b": "-يعنى بالملفات الشخصية :\n قيود االحوال الشخصية والملفات التي تتضمن جميع انواع المعلومات المتعلقة بالشخص الطبيعي على نحو مباشر أو غير مباشر.\nبما في ذلك عنوان بروتوكول االنترنت ( )IP addressوذلك عن طريق مقارنة المعلومات المتعددة المصادر أو التقاطع فيما بينها .\nب -ويحق لصاحب العالقة الطلب لتصحيح او اكمال او تحديث او محو المعلومات الشخصية المتعلقة به غير الصحيحة او الناقصة\n او الملتبسة او القديمة او التي يكون من الممنوع جمعها او استعمالها او تبادلها او حفظها.\n المادة :5المستندات غير القابلة لالطالع:\n أ -ال يمكن الوصول الى المعلومات المتعلقة بـ:\n أسرار الدفاع الوطني واألمن القومي واألمن العام. -1\n ادارة العالقات الخارجية للدولة ذات الطابع السري. -2\n ما ينال من المصالح المالية واالقتصادية للدولة وسالمة العملة الوطنية. -3\n -4حياة األفراد الخاصة وصحتهم العقلية والجسدية.\n -5األسرار التي يحميها القانون كالسر المهني او السر التجاري مثال.\n ب -ال يمكن االطالع على المستندات التالية:\n -1وقائع التحقيقات قبل تالوتها في جلسة علنية ،والمحاكمات السرية ،والمحاكمات التي تتعلق باألحداث وباالحوال الشخصية .\n محاضر الجلسات السرية لمجلس النواب او لجانه ،ما لم يقرر خالف ذلك. -2\n مداوالت مجلس الوزراء ومقرراته التي يعطيها الطابع السري. -3\n المستندات التحضيرية واإلعدادية والمستندات االدارية غير المنجزة. -4\n األراء الصادرة عن مجلس شورى الدولة إال من قبل اصحاب العالقة في إطار مراجعة قضائية. -5\n الفصل الثاني -موجب النشر حكما\n\f المادة :6األسباب الموجبة للقوانين والقرارات اإلدارية:\n تنشر األسباب الموجبة مع القوانين والمراسيم على مختلف أنواعها في الجريدة الرسمية ،وذلك بواسطة الجهة المناط بها صالحية\n النشر أو صالحية اإلصدار.\n المادة :7المستندات الواجب نشرها حكماً:"}, {"o": 2, "l": null, "b": "على اإلدارة أن تنشر حكما ً على مواقعها اإللكترونية ما يلي:\n القرارات والتعليمات والتعاميم والمذكرات التي تتضمن تفسيراً للقوانين واألنظمة أو تكون ذات صفة تنظيمية ،وذلك خالل -\n خمسة عشر يوما ً من تاريخ صدورها.\n يكون النشر في الجريدة الرسمية إضافةً إلى الموقع اإللكتروني التابع لإلدارة.\n مع مراعاة أحكام المادة 5من هذا القانون ،جميع العمليات التي بموجبها يتم دفع أموال عمومية تزيد عن خمسة ماليين ليرة -\n لبنانية ،وذلك خالل شهر من تاريخ إتمامها أو إتمام أحد أقساطها ،على أن يتضمن النشر ما يلي :قيمة عملية الصرف ،وكيفية\n الدفع ،والغاية منه ،والجهة المستفيدة ،والسند القانوني الذي بموجبه جرى الصرف (مثالً :مناقصة ،عقد بالتراضي ،تنفيذ حكم\n قضائي).\n يستثنى من أحكام هذه المادة رواتب وتعويضات الموظفين.\n المادة :8التقارير السنوية:\n أ -على الرئيس التسلسلي المختص في كل إدارة وضع تقرير سنوي عن نشاطاتها.\n ب -بالنسبة للقضاء ،يتولى وضع التقرير السنوي الجهة المسؤولة عن اإلشراف على كل من القضاء العدلي واإلداري والمالي\n والمذهبي والروحي والشرعي (مثالً :مجلس القضاء األعلى ،مكتب مجلس شورى الدولة) .يتضمن تقرير القضاء العدلي واقع\n المحاكم اإلستثنائية.\n ج -يجب ان تتضمن التقارير السنوية ما يأتي على االقل:\n -1معلومات حول آلية عمل االدارة تتضمن التكاليف واألهداف والقواعد واإلنجازات والصعوبات التي اعترضت سير العمل\n والحسابات المدققة.\n -2السياسة العامة المعتمدة والمشاريع الخاصة باالدارة المعنية ،التي نفّذت والتي لم تنفّذ وأسباب ذلك ،وأيّة إقتراحات تساهم في\n تطوير عمل اإلدارة.\n\f المادة :9وسائل النشر:\n تنشر جميع المستندات المذكورة في المادة السابقة على المواقع االلكترونية لالدارات المختصة.\n الفصل الثالث -موجب تعليل القرارات االدارية\n المادة :01حق الوصول الى اسباب القرارات االدارية:"}, {"o": 3, "l": null, "b": "ان األشخاص الطبيعيين أو المعنويين لهم حق بالوصول الى األسباب التي دفعت االدارة الى اتخاذ القرارات اإلدارية غير التنظيمية\n التي تمس حقوقهم.\n المادة :00شروط التعليل:\n على األدارة أن تعلل القرارات اإلدارية الغير تنظيمية ،تحت طائلة اإلبطال ،على الوجه اآلتي:\n -1أن يكون التعليل خطياً.\n أن يتضمن الحيثيات القانونية والواقعية التي تشكل مرتكز القرار. -2\n ان يكون موقعا\" من قبل المرجع الذي أصدره ،وان يذكر فيه اسم موقعه وتاريخ توقيعه. -3\n المادة :02االعفاء من التعليل:\n -1تعفى اإلدارة من موجب التعليل القرارات األدارية الغير تنظيمية في الحاالت التالية:\n أثناء قيام حالة الطوارئ. -1\n -2الظروف االستثنائية المتمثلة في حاالت الخطر الدائم ألتي تهدد عمل المؤسسات .\n أسرار الدفاع الوطني واألمن القومي واألمن العام. -3\n ادارة العالقات الخارجية للدولة ذات الطابع السري. -4\n\f ما ينال من المصالح المالية واالقتصادية للدولة وسالمة العملة الوطنية. -5\n حياة األفراد الخاصة وصحتهم العقلية والجسدية. -6\n األسرار التي يحميها القانون كالسر المهني او السر التجاري مثال. -7\nاذا زالت أسباب إعفاء اإلدارة من التعليل او في حالة قرار الرفض الضمني ،يحق لصاحب العالقة ضمن مهلة المراجعة -2\n القضائية ،أن يطلب إطالعه على أسباب القرار .وعلى السلطة المعنية أن تطلعه عليها خطيا ً ودون ابطاء.\n -يعتبر سكوت االدارة على الطلب مدة شهرين بمثابة قرار رفض ضمني قابل للطعن أمام مجلس شورى الدولة .\n الفصل الرابع -الموظف المكلف بالمعلومات\n المادة :03تسهيل عملية الوصول الى السجالت:\n على االدارة أن تحتفظ بالمعلومات التي بحوزتها بشكل منظم وبترتيب يسهل على الموظف المكلّف عملية استخراجها ،ويجب عليها\n حفظ المعلومات إلكترونيا كلما أمكن ذلك.\n المادة :04تقديم الطلب:"}, {"o": 4, "l": null, "b": "-1يقدم طلب الحصول على المعلومات بشكل خطي إلى االدارة التي تكون المعلومة في حوزتها ،ويجب أن يحتوي هذا الطلب\n على تفاصيل كافية تمكن الموظف المكلّف من استخراج المعلومة بجهد بسيط.\n -2على مقدم الطلب ان يتخذ مكان اقامة مختاراً يعلم به االدارة فور تقديمه الطلب.\n -5على الموظف المكلّف ان يضع سجال\" بالطلبات المقدمة ،وأن يعطي ،فور تسلمه الطلب ،إشعارا لمن تقدم بالطلب يبين\n فيه :تاريخ تقديم الطلب ونوع المعلومة المطلوبة والفترة الالزمة للرد على الطلب.\n د -في حال لم يكن الطلب دقيقا بشكل كاف ،يطلب الموظف المكلف من مقدمه االيضاحات الالزمة ،كما يقوم بمساعدته بالطرق\n المتاحة كافة.\n المادة :05موظف المعلومات:\n يكلف موظف في كل ادارة للنظر في طلبات الحصول على المعلومات ،وتكون له الصالحيات الالزمة للبحث والوصول إلى\n المعلومات المطلوبة وتسليمها للمواطنين.\n\f المادة :06مهل الرد:\n على الموظف المكلّف ان يرد على الطلب خالل خمسة عشر يوما من تاريخ تقديمه ،ويجوز تمديد هذه الفترة لمرة واحدة ولمدة ال\n تزيد عن خمسة عشر يوما\" ،إذا كان الطلب يتضمن عددا كبيراً من المعلومات ،أو كان الوصول إلى المعلومة يستوجب مراجعة\n طرف ثالث أو ادارة أخرى .ويعتبر عدم الرد خالل تلك الفترة بمثابة رفض ضمني للطلب.\n المادة :07قبول طلب االطالع:\n إذا تمت الموافقة على الطلب ،فعلى الموظف المكلّف أن يم ّكن الطالب من الحصول على المعلومات التي بينها في طلبه .وإذا احتوى\n الطلب على أكثر من معلومة مطلوب االطالع عليها ،يجوز للموظف المكلّف السماح للطالب بالوصول الى جزء من المعلومات إذا\n ما كانت المعلومات األخرى تدخل في نطاق االستثناءات المحددة في هذا القانون مع مراعاة حقوق الملكية الفكرية.\n المادة :08كيفية الوصول الى المستندات االدارية:"}, {"o": 5, "l": null, "b": "-1إن الوصول الى المستندات اإلدارية يتم مجانا ً في مكان وجودها ،ما لم تحل دون ذلك أسباب المحافظة المادية على المستند.\n ب -إن حصول صاحب العالقة على صورة أو نسخة عن المستند المطلوب يتم على نفقته ،على أن ال تتجاوز هذه النفقة كلفة\nاالستنساخ أو التصوير او تلك المحددة قانونا .واذا كان المستند الكترونيا ً أو تسجيالً صوتيا ً أو مرئياً ،يمكن لصاحب العالقة ان يطلب\n على نفقته نسخة مطبوعة أو تسجيالً صوتيا ً أو مرئيا ً او الكترونيا عنه .ويمكن ان يرسل المستند االلكتروني ،مجانا ،الى صاحب\n العالقة ،بواسطة البريد االلكتروني.\n المادة :09رفض الوصول الى المعلومات:\n -1ان قرارات رفض الوصول الى المعلومات يجب ان تكون خطية ومعللة.\nعلى اإلدارة ان تبلغ قرار رفض الوصول الى المعلومات الصريح الى صاحب العالقة ،الذي له خالل مهلة شهرين ان يراجع -2\n الهيئة االدارية المستقلة المحددة في قانون انشاء الهيئة الوطنية لمكافحة الفساد.\n ج -إن الرفض الضمني للوصول الى مستن ٍد ما ،يكون قابال للطعن وفقا ً لالصول المذكورة في الفقرة السابقة.\n\f المادة :21اعادة استخدام المعلومات:\nال يخول حق الوصول الى المعلومات المستفيدين منه او الغير إمكان نقل او نشر او استخدام المستندات المطّلع عليها في سبيل غايات\n تجارية ،اال اذا جمعت المستندات المذكورة ضمن مجموعات معلومات يكون اختيار او ترتيب مضمونها مبتكرا وفقا للمادة 3من\n القانون رقم 75المؤرخ في 1999/4/3المتعلّق بحماية الملكية االدبية والفنية ،وشرط اال تتضمن المستندات المذكورة اي معلومات\n ذات طابع شخصي ومع مراعاة حقوق الملكية الفكرية.\n تحت طائلة وقف نشاط المخالف وتغريم المخالف ال يقل عن ضعفي المنفعة المادية للمحصلة0\n المادة :20وثائق المحفوظات الوطنية:\nان إيداع المستندات اإلدارية القابلة لالطالع وفقا ً لهذا القانون لدى مؤسسة المحفوظات الوطنية ،ال يحول دون الوصول اليها في أي\n وقت."}, {"o": 6, "l": null, "b": "اما المستندات االدارية غير القابلة لالطالع بمفهوم هذا القانون ،فيصبح الوصول اليها ممكنا ً بعد انقضاء المهل المحددة لها قانونا ً\n ووفقا ً لألصول المحددة في القانون رقم 162المؤرخ في 1999/12/27المتعلق بالمحفوظات الوطنية.\n الفصل الخامس -الصالحيات الخاصة للهيئة الوطنية لمكافحة الفساد\n المادة :22مهام الهيئة الوطنية لمكافحة الفساد (الهيئة ):\n تتولى الهيئة:\n استالم الشكاوى المتعلقة بتطبيق أحكام هذا القانون والتحقيق فيها واصدار قرارات بشأنها ،وفقا الحكام المادة 23من هذا -1\n القانون.\n إبداء المشورة للسلطات المختصة بشأن كل مسألة تتعلق بتطبيق أحكام هذا القانون. -2\n وضع تقرير سنوي يتضمن ،بصورة خاصة ،الصعوبات الهامة التي تعترض وصول األشخاص الى المعلومات بالنسبة إلى -3\n مختلف فئات المستندات ،وتقارير خاصة حول مواضيع هامة عند االقتضاء ،تنشر وفقا للمادة 9من هذا القانون.\n المشاركة في تثقيف المواطن وبلورة وعيه حول أهمية الحق في الوصول الى المعلومات وأصول ممارسته ،واالسهام في -4\n تدريب الموظفين والمسؤولين في االدارة على كيفية وأهمية تمكين االفراد من الحصول على المعلومات.\n\f المادة :23قرارات الهيئة:\n -1تصدر الهيئة االدارية قرارا\" ملزماً ،خالل مهلة شهرين من تاريخ تقديم الشكوى ،بالموافقة على تسليم المستند او برفض ذلك\n .وتبلغه فوراً الى االدارة المختصة.\n ان قرارات الهيئة قابلة للطعن أمام مجلس شورى الدولة الذي يطبق بشأنها األصول الموجزة. -2\n الفصل السادس :أحكام ختامية\n المادة :24النصوص المخالفة لهذا القانون:\n تلغى جميع النصوص المخالفة ألحكام هذا القانون او التي ال تأتلف مع مضمونه.\n المادة :25دقائق تطبيق أحكام هذا القانون:\n تحدد عند االقتضاء دقائق تطبيق أحكام هذا القانون بمراسيم ،تتخذ في مجلس الوزراء بناء على أقتراح وزير العدل0\n المادة :26تاريخ بدء العمل بهذا القانون:"}, {"o": 7, "l": null, "b": "يعمل بهذا القانون فور نشره في الجريدة الرسمية."}]$j$::jsonb) e;
