insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (122,'توصيات الهيئة','توصية رقم /2ه.ش.ع/ 2022 موجهة إلى الجهات الخاضعة لأحكام قانون الشراء العام في ما خص عمليات البيع واإلستثمار التي تجريها بطريقة المزايدة العمومية وأي طريقة أخرى','2022-10-13','https://www.ppa.gov.lb/ar/pages/details/122','{"https://admin.ppa.gov.lb/storage/listing-pages/files/K72gfs7iO3970Y0XKVPCYHST5oRq22ylk7wi-1763459486.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/K72gfs7iO3970Y0XKVPCYHST5oRq22ylk7wi-1763459486.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=122),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "توصية رقم /2ه.ش.ع2022 /\n موجهة إلى الجهات الخاضعة ألحكام قانون الشراء العام في ما خص عمليات البيع\n واإلستثمار التي تجريها بطريقة المزايدة العمومية وأي طريقة أخرى\n إن رئيس هيئة الشراء العام،\n بناء على قانون الشراء العام رقم 2021/244تاريخ ،2021/7/19ال سيما المادتَين 5و 76منه،\n ً\nوبما أن المزايدات التى تقوم بها الدولة اللبنانية من شأنها أن تؤمن موارد هامة في ظل العجز المالي في الموارد\n القائمة،\nوبما أن إدراج قيمة عقود المزايدات بالليرة اللبنانية يؤدي الى غبن في واردات الدولة المالية مع اإلنخفاض\nالمستمر في قيمة العملة الوطنية ،سيما وأن المستثمرين يحصلون إيراداتهم في معظم األحيان بالعملة األجنبية،\n لـــــــــــــذلك،\n توصي هيئة الشراء العام بما يلي:\nنظر لإلنخفاض الحاصل في سعر صرف الليرة اللبنانية\n أولا :إعادة تخمين كل عقود اإلستثمار بالعملة األجنبية ًا\n مقابل العملة األجنبية.\nثانيا :بالنسبة لعمليات البيع واإلستثمار الجديدة ،تحديد سعر االفتتاح في المزايدات وعقود البيع واإلستثمار\n ا\nبالعملة األجنبية وفًقا ألحكام المادة الخامسة من قانون الشراء العام واألسباب التي أتت على ذكرها هذه التوصية.\n بيروت في 2022/10/13\n رئيس هيئة الشراء العام\n د.جان العلية"}]$j$::jsonb) e;
