insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (125,'قوانين','جدول توضيحي للقانون رقم 21 تاريخ 17/7/2025 (تفعيل عمل البلديات / صلاحيات المحافظ و القائمقامين)','2025-08-14','https://www.ppa.gov.lb/ar/pages/details/125','{"https://admin.ppa.gov.lb/storage/listing-pages/files/Rbv9bFzsEnWtnBdozQgCLF0aHAOtGN0djsGl-1760213025.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/Rbv9bFzsEnWtnBdozQgCLF0aHAOtGN0djsGl-1760213025.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=125),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "وزارة الداخلية و البلديات\nمحافظة لبنان الشمالي\nجانب كل من:\nالقانمقامين في محافظة لبنان الشمالي\nدائرة البلديات في محافظة لبنان الشمالي\nالموضوع:الالتزام بالتعديلات المنصوص عليها في القانون الذي يرمي الى تفعيل عمل البلديات\nالمرجع:القانون رقم ١١ تاريخ 5055/1/١1\nالمرسوم الاشتراعي رقم تاريخ 1\nبالاشارة الى الموضوع و المرجع اعلاه\nنودعكم ربطا الجدول أدناه الذي يبين أهم التعديلات التي وردت في القانون رقم ١ه المتعلقة\nبصلاحيات المحافظ و القائمقامين:\nأ نوع النفقة قيمة النفقة الخاضعة | قيمة النفقة الخاضعة | النصوص القانونية- |\nا | لتصديق القانمقام | لتصديق المحافظ )\n| شراء العقارات أو بيعها | لا تزيد قيمتها عن تزيد قيمتها عن المواد رقم 5٠ و١1\n| ودفاتر الشروط ٍْ 0 ظ 0٠٠,٠٠٠ إمن المرسوم الاشتراعي\n| الخاصة العائدة لها ل.ل. ٍْ ل.ل. رقم 1١91/1/1١\nا معطوفة على المادة رقم\n]أء 1 من القانون رقم\n١ 00\nعقود الايجار عندما تزيد بدلاتها عندما تزيد بدلاتها المواد رقم ٠١ و١5\n0 السنوية عن السنوية عن من المرسوم الاشتراعي\n| ل ا لاله رقم ١911/1١48\nع حو معطوفة على المادة رقم\nلديوان المحاسبة) و عن من القانون رقم\nح كالبل 0/1\n( في البلديات الأخرى)\nعلى أن لا تتعدى في\n| الحالتين\nْ ملل\n١\n31١9و 6٠١ عندما تزيد القيمة عندما تزيد القيمة | المواد رقم 1\n| اسعاف المعاقين و الاجمالية للمساعدات في | الاجمالية للمساعدات في | من المرسوم الاشتراعي\nأ ١111/١١48 المساعدات السنة عن السنة عن رقم ١\nلبل. | معطوفة على المادة رقم ٠٠٠٠٠.6٠ | لىيل. ٠66٠٠٠٠٠\nصلاحية المحافظ 5 من القانون رقم ( |\n| \"7١ محصورة في قضاء |\n0 | مركز المحافظة) | |\n| 1١و 6١ عندما تزيد قيمتها عندما تزيد قيمتها عن | المواد رقم ١ اجازة صفقات اللوازم و |\n| من المرسوم الاشتراعي | ١5٠. الأشغال و الخدمات و | 560296605969 ليل | اترت ءرد د"}, {"o": 1, "l": null, "b": "١9الال/1١١8مقر | دفاتر الشروط الخاصة ولا تتجاوز ل.ل.\nالعائدة لها تتررفرورء و5١ | معطوفة على المادة رقم\nل.ل. 5 من القانون رقم\n١ وت\n5١و 5١ اجازة الأشغال بالأمانة | عندما تزيد قيمتها عن | عندما تزيد قيمتها عن المواد رقم\nو شراء اللوازم بتورققوررءة ليل افتت رترت رت تت( من المرسوم الاشتراعي\n١91/17//1١8 بالفاتورة ولا تتجاوز ل.ل. رقم\nوه ؟ اعارص ميا معطوفة على المادة رقم\nل.ل. 5 من القانون رقم\n00\nالذي رفع قيمة عقد النفقة المسموح بها ٠١73/1١ من القانون رقم ٠ كما لا بد من الاشارة الى نص المادة\nلرئيس السلطة التنفيذية في البلدية بحيث تصبح مئة مليون ليرة لبنانية؛ ومليار ليرة لبنانية للمجلس البلدي\nكحد أقصى.\nللاطلاع و أخذ العلم و المقتضى0؟\nنسخة للحفظو/9 مالس ى 6/ </ ه..\nإيان معطم"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (126,'نماذج','نموذج إضافة مورّد/عارض جديد على المنصة الإلكترونية (خاص بالجهات الشارية المسجلة على المنصة)','2025-10-07','https://www.ppa.gov.lb/ar/pages/details/126','{"https://admin.ppa.gov.lb/storage/listing-pages/files/AxfwUGHn6fNnEMrgK21TytigVIgfMrOeNEhK-1759919682.xlsx","https://admin.ppa.gov.lb/storage/listing-pages/files/AxfwUGHn6fNnEMrgK21TytigVIgfMrOeNEhK-1759919682.xlsx"}',null) on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (127,'قرارات الرئيس','قرار رقم 79/ هـ.ش.ع./2025 - شُرعة قواعد السلوك والأخلاق المهنيّة والمواطنة الصالحة الخاصة بعمليّات الشراء العام','2025-09-23','https://www.ppa.gov.lb/ar/pages/details/127','{"https://admin.ppa.gov.lb/storage/listing-pages/files/laIWjQc7DuH5JPASfRlcrw7VHCxqdbd5pACN-1760029806.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/laIWjQc7DuH5JPASfRlcrw7VHCxqdbd5pACN-1760029806.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=127),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "م الجمهوريّة اللبنائيتة\n2# صهيئةالشراء العام\n00 شفافية . منافسة . نزاهة ١ قرار رقم 9/ هرش ع.ره ٠١\"\nشرعة قواعد السلوك والأخلاق المهنيّة والمواطنة الصالحة\nالخاصة بعمليّات الشراء العام\nان رئيس هيئة الشراء العام؛\nٍْ بناءً على الفقرة الثانية من"}, {"o": 1, "l": "المادة 85", "b": "المادة 85 من القانون رقم ؟ 5 ” الصادر بتاريخ ٠١5١/7/١1 (قانون الشراء\nا العام) التي أوكلت إلى رئيس هيئة الشراء العام مهام الهيئة الى حين تعيينها.\nبناءً على"}, {"o": 2, "l": "المادة ٠١", "b": "المادة ٠١ من القانون رقم 54 75 الصادر بتاريخ ٠١7١/7/١5 (قانون الشراء العام) التي تنص\nعلى ان تضع هيئة الشراء العام بموجب قرار تنظيمي شرعة لقواعد السلوك والأخلاق المهنيّة والمواطنة\nالصالحة الخاصة بعمليّات الشراء العام تُطبّق على كافة العاملين في الجهات الشارية وعلى المتعاقدين معها.\nبناءً على الفقرة )٠١( من المادة ؟ من القانون رقم ١544 الصادر بتاريخ 3١71/7/١5 (قانون الشراء\nالعام) التي تعتبر تضارب المصالح متحققاً في أي من الحالات المنصوص عليها في شرعة قواعد السلوك\nوالتي يجب تضمينها وجوب تنحّي الموظفين عن العمل الذي يقومون به إذا كان له علاقة بالشراءء في حال\nكانت تربطهم صلات قربى حتى الدرجة الرابعة أو مصالح مشتركة واضحة مع العارض أو العاملين لديه أو\nالشركاء في الشركة العارضة؛ وكان يُخشى معها عدم اتنَّصاف عملهم بالحياد أو تحمل بشكل واضح على الشك\nبهذا الحياد.\nبناء على الفقرة (8) من"}, {"o": 3, "l": "المادة 5", "b": "المادة 5 من القانون رقم 545 الصادر بتاريخ ٠١71/17/١4 (قانون الشراء\nالعام) التي تعتبير من صلاحيات هيئة الشراء العام وضع شرعة قواعد السلوك والأخلاق المهنية الخاصة\nبعمليات الشراء العام المنصوص عليها في"}, {"o": 4, "l": "المادة ٠١", "b": "المادة ٠١ من القانون؛\nبناغ على الفقرة الثانية من"}, {"o": 5, "l": "المادة ٠١١", "b": "المادة ٠١١ من القانون رقم 545 ؟ الصادر بتاريخ ٠١7١/7/١5 (قانون الشراء\nالعام) التي تلزم موظفي سلطة التعاقد والعاملين لديها بقواعد السلوك المنصوص عليها في"}, {"o": 6, "l": "المادة ٠١", "b": "المادة ٠١ من القانون\nوبالمعايير الأخلاقية والمهنية.\nولأجل تحقيق وتطبيق مبادئ الشراء العام عبر فرض مستويات عالية من النزاهة على جميع أصحاب\nالمصلحة في دورة الشراء من خلال توسيع المعايير المدرجة في أطر النزاهة ومدونات قواعد السلوك وتطبيقها\nعلى المتدخلين في كافة مراحل الشراء.\nيقرر ما يأتي: :\nالمادة الأولى: توضع شُرعة قواعد السلوك والأخلاق المهنيّة والمواطنة الصالحة الخاصة بعمليّات الشراء\nالعام المرفقة بهذا القرار موضع التنفيذ.\nالمادة الثانية: على جميع العاملين لدى الجهات الشارية بكل الصفات والمسميات الوظيفية وعلى المتعاقدين\nوالمتعاملين معها التقيّد بهذه الشرعة فور نشرها.\nالمادة الثالثة: يُعمل بهذا القرار فور صدوره وينشر على المنصة الإلكترونية المركزية لدى هيئة الشراء\nالعا\nم.\nمسر بيروت في 9/71.ره؟7١؟\nما 1 رئيس هيئة الشراء العام\nالح 1 زر\n// / سككفي ١ أ ١ جن الكلية\n00 1 7\n2 الشراء الععييه\n#صلييدة\nشرعة قواعد السلوك والأخلاق المهنيّة والمواطنة الصالحة\nالخاصة بعمليّات الشراء العام\nفهرس\nالغانة الأول والتطاف 0 ار ا ل ا ا ا 2 0 200\nالكل دكي الع لباقي اميه 1\nالفادة الراجعة: الااحكام العامة ...بدني ل دو 22225221\nالفقرة ”: القواعد العامة للأخلاقيات وقواعد السلوك للموظف العام ......................... 37\nالعادة الكامتة. الاطتقائل فى داع لياع 2 000207770700707\nالمنادة: 5 :(: التواهة والشفافية ال خادقية .. ا 42\nلاما اللتطورات ا 4\nالغاذة > ( خطن المشاهمات والقساصات ا لك\nالفقزة؛؟: الراقاية التسلسطلية :............. .دي و ا 3\nالفاذة 19 ممارسة السلطة التسلفطفة ٠... د مامد دده ممم ممم 90\nالغادة 1( واحب الإمتكال للسلطة التملسلية 6\nالفصل الثالث: معايير السلوك في إجراءات الشراء را ا ١\n١ 7 0 3\n/ ر ساهو ٠١"}, {"o": 7, "l": "المادة ٠١", "b": "القسم الأول: القواعد الخاصة بالأخلاقيات وقواعد السلوك المطبقة على الجهات الفاعلة في الشراء العام ................... ١١\nالفقوة ١١ الالترام بالمتادى الامناسية لمر اع العام بي 3"}, {"o": 8, "l": "المادة 1١", "b": "المادة 1١ ساد والصاء0 ادي عملي الست 2 ...1 ...0000 اده ل لا د 1\nللغاد ١ الوافتوك لخر ا إل لسر العام 1 ل ا"}, {"o": 9, "l": "المادة 15", "b": "المادة 15 احدر ام يدا المساواة ني