insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (129,'أنظمة وتشريعات خاصة','النظام المالي لهيئة الشراء العام - مرسوم رقم 27 تاريخ 27 كانون الثاني 2025','2025-01-28','https://www.ppa.gov.lb/ar/pages/details/129','{"https://admin.ppa.gov.lb/storage/listing-pages/files/Af0sJbjalWu7tTv2S9M2mw0AF8LakyJQI6RZ-1761800081.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/Af0sJbjalWu7tTv2S9M2mw0AF8LakyJQI6RZ-1761800081.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
