insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (132,'أنظمة وتشريعات خاصة','نظام الاجراء في الهيئة - مرسوم رقم 14633 تاريخ 9/1/2025','2025-01-09','https://www.ppa.gov.lb/ar/pages/details/132','{"https://admin.ppa.gov.lb/storage/listing-pages/files/406n3UJazSgEXMC4u1ke7fmCCgSFaEwxrqQG-1761799685.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/406n3UJazSgEXMC4u1ke7fmCCgSFaEwxrqQG-1761799685.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=132),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "ع ام#سيوز\nال ا مت ابتار\"\nتعر صدرور ا يموع ص 2\nتاريخ تمسق 8-6\n١ آثاسة زراء\n2\nرائيسة فانسق\n5\n©\n2 2\nب 4\n7\n2 38\n:\n| 1\nظ مرسوع يفم 21115\nنظام الأجراء في هيئة الشراء العام\nإن مجلس الوزراع\nبناءًٌ على الدستور لاسيما المادة 5١ منهء\nبناءً على القانون رقم 544 تاريخ 5٠7١/1/١5 وتعديلاته (قانون الشراء العام)» لا سيّما المواد\n»87 والمادة 68 منه المتعلقة بتولّي رئيس الهيئة مهامها إلى حين تعيين أعضائهاة\n© بناء على المرسوم رقم “5887 تاريخ ١194/11/7 وتعديلاته (النظام العام للأجراء)»\nبذاء على كتابي رئيس هيئة الشراء العام رقم 587 /ه.ش.ع./77١7 تاريخ 7077/٠١/١4\nوتاريخ 2375/8/57\nبناءً على اقتراح رئيس مجلس الوزراء»\nوبعد موافقة مجلس الخدمة المدنية بكتابه رقم ٠١54 تاريخ 4/8/١ 23707\nويعد على استشارة مجلس شورى الدولة (الرأي رقم 7077/974- 0 7004 تاريخ\nل\nوبعد موافقة مجلس الوزراء بتاريخ 7074/17/١1\nيرسم ما يأتي:\n© المادة :١\nيقصد في نص هذا النظام:\nبكلمة «الهيثة»: هيئة الشراء العام :\nبكلمة «رئيس الهيئة»: رئيس هيئة الشراء العام.\nالمادة ؟: م\nالأجير هو كل شخص يعمل في خدمة الهيئة ولا ينتسب الى ملاكها الدائم ولا يخضع للأحكام\nالخاصة بالمتعاقدين.\nحددت تسميات الأجراء في الهيئة وأعدادهم وأجورهم وفقا للجدول رقم )١( الملحق بالمرسوم.\nالمادة ؛: :\nحدّدت الشروط الخاصة بالاستخدام وفقا للجدول رقم (؟) الملحق بهذا المرسوم.\n©6\nالمادة 0: الأجراء نوعان:\n- أجير عادي الذي يستخدم لمدة معينة او لعمل مؤقت او عارض.\n- أجير موسمي الذي يستخدم لفترة موسمية.\nلا يترتب للدّجراء الموسميين أي حق تجاه الهيئة؛ بعد انتهاء الفترة الموسمية التي استخدموا\nمن اجلهاء سوى التقديمات التي يستفيدون منها وفقا لأحكام قانون الضمان الإجتماعي.\nالمادة 7: يشترط في الأجير:\n- أن يكون لبنانياً منذ أكثر عشر سنوات.\n- أن يكون قد اتم الثامنة عشر ولم يتجاوز الستين. 6"}, {"o": 1, "l": null, "b": "- أن يبرز شهادة من إللجنة الطبية الرسمية تثبت انه سليم من الامراض والعاهات التي تحول\nدون قيامه باعباء الخدمة.\n- أن يكون متمتعاً بحقوقه المدنية وغير محكوم عليه بإحدى الجرائم المنصوص عليها في\nالفقرة (ه) من البند )١( من المادة الرايعة من المرسوم الاشتراعي رقم ١١” تاريخ\n7/1 (وتطبق هذه الأحكام على الأشخاص الذين أعيد اليهم إعتبارهم أو استفادوا\nمن العفو.\nسر ئ\nالمادة 1 السلطة الصالحة للاستخدام:\nيستخدم الاجير بقرار من رئيس الهيئة بعد موافقة مجلس الخدمة المدنية ضمن حدود تسميات\nوعدد الأجراء الملحوظة للهيئة.\n- لا يستخدم الاجير إِلّا في مركز شاغر ومرصد له اعتماد خاص في الموازنة ووفقا للاصول\nالمحددة لذلك.\n- يسري مفعول الاستخدام ابتداء من تاريخ مباششرة العمل ولا يجوز أن يحدث اي مفعول ©\nرجعي.\n- يخضع الأجير في دوامه للدوام الرسمي المُقرر لمستخدمي الهيئة.\n- يستفيد الأجير من اجره كاملاً عن الايام التي تقفل فيها الهيئة.\n- يحق للاجير العادي الذي امضى ثلاثماية يوم عمل فعلي في الخدمة ان يستفيد من اجازة\nادارية باجر كامل مدتها ١5 يوم ويحق له الاستفادة من اجازة نسبية باجر كامل عن كل\nسنة لاحقة.\n- - يجوز ان تتراكم الاجازات الادارية لمدة اقصاها '' سنوات. 6\nالمادة :١١\n- تدفع اجور الاجراء على اساس اليوم» ويمكن ان تدفع اجور الموسميين على اساس الساعة. :\n- تحدّد الاجرة اليومية لفئة العمال بحاصل قسمة راتب الدرجة الأولى من سلسلة رواتب الفئة\nالخامسة النافذة في القطاع العام في أي حين على العدد .7٠ ْ\n- يعظى الاجير العادي زيادة دورية على اجرة تعادل خمسة بالمئة عن كل 74 شهر عمل\nفعلي يقضيها في الخدمة.\n- يمكن منح الأجير تعويضًا عن الأعمال الإضافية اذا كلفه رئيس الهيئة خطيًا بأعمال من\nهذا النوع شرط أن يتم التكليف قبل المباشرة بالعمل ووففا لأحكام المرسوم 79 تاريخ\n0١ وتعديلاته (نظام العمل الاضافي).\nالمادة :١١"}, {"o": 2, "l": null, "b": "يتقاضى الاجير الذي ينتقل خارج مركز عمله بداعي العمل تعويض انتقال يوميا يعطى على\nالاساس التالي:\n- لااشيء اذا كان الغياب خلال الدوام المطبق على الاجير.\n١/# - التعويض اذا كان الغياب يتجاوز الخمس ساعات ويتخلله وجبة الغذاء أو وجبة\nالعشاء م\n- \"/7 التعويض اذا كان الغياب يتجاوز الخمس ساعات ويتخلله العشاء والمنامة.\n- يحدد كامل تعويض الانتقال اليومي للاجير بما يوازي اجره عند يوم واحد.\n- يصدق على مدة الغياب رئيس الهيئة.\nالمادة ؟ :١\nتُطبق على الاجراء جميع الأحكام الوارد النص عليها في المرسوم رقم 5887 تاريخ\nونعديلاته (النظام العام للاجراء) والتي لم يرد النص عليها في هذا المرسوم.\nالمادة \" :١ ©\n1 . ينشر هذا المرسوم في الجريدة الرسمية ويعمل به-قور نشره-\nصدر عن مجلس الوزراء بيروت: في ٠١76/1/9 :\nالإمضاء محمد نجيب ميقاتي\nوزير المالية رئيس مجلس الوزراء رئيس مجلس الوزراء\nالإمضاء يوسف خليل الإمضاء محمد نجيب ميقاتي الإمضاء محمد نجيب ميقاتي\nنت لبور *\nد تر / صورة طبق الأصل\n2 3 أمين عام مجلس الوزراء\nمس ١ عق\nطمانة العامك << القاضي حبر ك1\nملحق\nجدول رقم )١(\nا 20202077 تسميات وأعداد وأجور الأجراء في الهيعة 0027|\n00 0 ل الأجر اليومي بالليرة\nا الفئة التسمية 0\nلم ل لاس الا ا ْ\n| ساح ّ | راتب الدرجة الأولى من\nا العمال | 06 غافل 2 ا 0 سلسلة رواتب الفئة ©\nا 3 الخامسة النافذة في ٌ\nأ ا ناطور 3 القطاع العام في أي حين ْ\n1 ل ات ف أ إ\nملحق\nجدول رقم (؟)\n| 20 الشروطالخاصة لاستخدام الأجراء في هيئة الشراء العام 2222202777 8 ٠\n1 22-2 التستمكة عو 000700 يديد ا\n| 0 ست 00002270000 لاترجد سوط مد 007\nا ا سعد اد 0 لات شط فيه 02\nْ ا ناطور اتح كرو دلضه م\nكك كك كك 757557 3 1515303 1 131102 ههه ) ٠. 1 ا ا 231511"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (133,'أنظمة وتشريعات خاصة','شُرعة قواعد السلوك والأخلاق المهنيّة والمواطنة الصالحة الخاصة بعمليّات الشراء العام','2025-09-23','https://www.ppa.gov.lb/ar/pages/details/133','{"https://admin.ppa.gov.lb/storage/listing-pages/files/E1uIO4V9rBcNbXzR76U5L5AL0XkZvOmShqx0-1761802481.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/E1uIO4V9rBcNbXzR76U5L5AL0XkZvOmShqx0-1761802481.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
